// Each scenario is a mini-case study with deep consequences and realistic stat impacts

export const photographerQuestions = [

    // SECTION 1: THE FREELANCE HUSTLE & GEAR DILEMMAS (Questions 1-10)

    {
        id: 'pho_001',
        text: {
            en: '📸 The Gear Investment: You have $3,000 saved. Your current camera is 5 years old and struggles in low light. You have a chance to shoot a high-end indoor gala next month. Do you buy the new $2,800 body, or spend $1,500 on two high-quality prime lenses and save the rest?',
            th: '📸 การลงทุนกับอุปกรณ์: คุณมีเงินออม $3,000 กล้องปัจจุบันของคุณอายุ 5 ปีและถ่ายในที่แสงน้อยลำบาก คุณมีโอกาสได้รับงานถ่ายงานกาล่าในร่มสุดหรูในเดือนหน้า คุณจะซื้อตัวกล้องใหม่ราคา $2,800 หรือจะซื้อเลนส์ฟิกซ์คุณภาพสูงสองตัวราคา $1,500 แล้วเก็บเงินที่เหลือไว้?',
            zh: '📸 器材投资：你攒了3000美元。你现在的相机已经用了5年，在弱光环境下表现吃力。下个月由于你有一个拍摄高端室内晚会的机会。你是买2800美元的新机身，还是花1500美元买两个高质量定焦镜头并存下剩下的钱？'
        },
        options: [
            { id: 'A', text: { en: '🎥 New Body Strategy:"Sensor technology has jumped. I need that ISO performance for the gala. The body is the engine of the workflow."', th: '🎥 กลยุทธ์ตัวกล้องใหม่:"เทคโนโลยีเซนเซอร์ก้าวไปไกลมาก ฉันต้องการประสิทธิภาพ ISO สำหรับงานกาล่า ตัวกล้องคือหัวใจของระบบงาน"', zh: '🎥 新机身策略：“传感器技术突飞猛进。我需要那样的ISO性能来应对晚会。机身是工作流的引擎。”' }, consequence: { en: '✅ Technical Edge! The gala photos are noiseless and crisp. The client is blown away by the quality. You land 3 more high-end indoor gigs. BUT: You realize your old lenses are now the bottleneck for sharpness. You are broke but have a premium portfolio piece.', th: '✅ ความได้เปรียบทางเทคนิค! ภาพถ่ายงานกาล่าใสเคลียร์ไม่มีนอยส์ ลูกค้าทึ่งในคุณภาพ คุณได้รับงานหรูในร่มเพิ่มอีก 3 งาน แต่: คุณตระหนักว่าเลนส์เก่ากลายเป็นตัวถ่วงความคมชัดไปแล้ว คุณเงินหมดตัวแต่มีผลงานระดับพรีเมียมประดับพอร์ต', zh: '✅ 技术领先！晚会照片无噪点且锐利。客户被品质惊艳了。你又获得了3个高端室内拍摄机会。但是：你发现老镜头现在成了锐度的瓶颈。你没钱了，但拥有了一件高端作品集。' }, stats: { competence: 40, ethics: 20, leadership: 20, innovation: 45 } },
            { id: 'B', text: { en: '🔍 Lens Priority:"Glass lasts forever, bodies deprecate. Prime lenses will give me a look the client has never seen. I\'ll rent a second body if needed."', th: '🔍 ให้ความสำคัญกับเลนส์:"เลนส์อยู่ได้ตลอดไป แต่ตัวกล้องตกรุ่นเร็ว เลนส์ฟิกซ์จะให้ภาพที่ลูกค้าไม่เคยเห็นมาก่อน ถ้าจำเป็นฉันค่อยเช่าตัวกล้องสำรองเอา"', zh: '🔍 镜头优先：“镜头发育长久，机身贬值快。定焦镜头会给客户带来从未见过的视觉效果。如果需要，我会租第二个机身。”' }, consequence: { en: '✅ Artistic Victory! The bokeh and character of the new lenses create a signature style. You are branded as an"Artistic Photographer."You saved $1,500 for marketing. The old camera body struggled a bit, but your editing skills compensated. You have a sustainable business foundation.', th: '✅ ชัยชนะทางศิลปะ! โบเก้และเอกลักษณ์ของเลนส์ใหม่สร้างสไตล์ที่เป็นลายเซ็นของคุณ คุณถูกจดจำในฐานะ"ช่างภาพสายอาร์ต"คุณเหลือเงิน $1,500 ไว้ทำเลือกการตลาด แม้กล้องเก่าจะลำบากบ้างแต่ทักษะการแต่งภาพของคุณช่วยไว้ได้ คุณมีฐานธุรกิจที่ยั่งยืน', zh: '✅ 艺术上的胜利！新镜头的焦外成像和特质创造了你的标志性风格。你被贴上了“艺术摄影师”的标签。你剩下了1500美元用于营销。老机身虽然有点吃力，但你的修图技巧弥补了这一点。你拥有了可持续的业务基础。' }, stats: { competence: 35, ethics: 20, leadership: 25, innovation: 40 } },
            { id: 'C', text: { en: '🛠️ Professional Lighting:"It’s not the camera, it’s the light. I’ll spend $2,000 on a pro portable strobe system and keep my current gear."', th: '🛠️ ระบบไฟมืออาชีพ:"มันไม่ได้อยู่ที่กล้อง แต่อยู่ที่แสง ฉันจะใช้เงิน $2,000 กับระบบไฟแฟลชพกพาและใช้อุปกรณ์เดิมต่อไป"', zh: '🛠️ 专业灯光：“关键不在相机，而在灯光。我会花2000美元买一套专业的便携闪光灯系统，并保留现有器材。”' }, consequence: { en: '✅ Light Master! You turned a dark gala into a studio-quality set. Other photographers are confused how your shots look so good. You get hired for corporate portraits. But: Dragging heavy lights to every gig is exhausting. You are a specialist now.', th: '✅ เจ้าแห่งแสง! คุณเปลี่ยนงานกาล่ามืดๆ ให้กลายเป็นภาพคุณภาพระดับสตูดิโอ ช่างภาพคนอื่นงงว่าภาพคุณสวยขนาดนี้ได้ยังไง คุณถูกจ้างไปถ่ายภาพบุคคลในองค์กร แต่: การแบกไฟหนักๆ ไปทุกงานมันเหนื่อยมาก ตอนนี้คุณกลายเป็นผู้เชี่ยวชาญเฉพาะทางไปแล้ว', zh: '✅ 灯光大师！你把昏暗的晚会变成了影棚级的片场。其他摄影师都很纳闷你的照片为什么拍得这么好。你收到了企业人像的聘请。但是：每次拍摄都拖着沉重的灯光非常累。你现在成了一名专家。' }, stats: { competence: 50, ethics: 20, leadership: 30, innovation: 35 } },
            { id: 'D', text: { en: '🎓 Education & Travel:"I’ll spend $3,000 on a workshop with a world-class photographer in Iceland. My gear is fine; my vision needs an upgrade."', th: '🎓 การศึกษาและการเดินทาง:"ฉันจะใช้เงิน $3,000 ไปเวิร์กชอปกับช่างภาพระดับโลกที่ไอซ์แลนด์ อุปกรณ์ฉันโอเคแล้ว แต่จินตนาการของฉันต้องอัปเกรด"', zh: '🎓 教育与旅行：“我会花3000美元去冰岛参加世界级摄影师的工作坊。我的器材没问题；我的眼界需要升级。”' }, consequence: { en: '🌟 Mindset Shift! You come back with a portfolio of stunning landscapes and a new way of seeing color. You raise your prices 50%. However, the gala gig was messy because your gear still failed in the dark. You are a better artist, but the technical debt remains.', th: '🌟 เปลี่ยนความคิด! คุณกลับมาพร้อมพอร์ตโฟลิโอภาพแลนด์สเคปที่น่าทึ่งและมุมมองเรื่องสีแบบใหม่ คุณขึ้นราคาได้ 50% อย่างไรก็ตาม งานกาล่าออกมาเละเทะเพราะอุปกรณ์ของคุณยังคงทำงานในที่มืดไม่ไหว คุณเป็นศิลปินที่เก่งขึ้นแต่ปัญหาเรื่องเทคนิคยังอยู่', zh: '🌟 观念转变！你带着惊艳的风景作品集和全新的色彩观回来了。你把价格调高了50%。然而，晚会的拍摄一团糟，因为你的器材在黑暗中还是不行。你是个更好的艺术家了，但技术债务依然存在。' }, stats: { competence: 30, ethics: 20, leadership: 40, innovation: 55 } }
        ]
    },

    {
        id: 'pho_002',
        text: {
            en: '🤝 The"Exposure"Trap: A famous local influencer with 500k followers wants a 4-hour lifestyle shoot for"exposure"and a tag. They refuse to pay your $800 fee but promise to recommend you to their wealthy friends. You have a free weekend. Do you take it?',
            th: '🤝 กับดัก"Exposure": อินฟลูเอนเซอร์ชื่อดังในพื้นที่ที่มีผู้ติดตาม 5 แสนคน ต้องการให้คุณถ่ายแนวไลฟ์สไตล์ 4 ชั่วโมงแลกกับความโด่งดังและการแท็กชื่อเขา เขาปฏิเสธจะจ่ายค่าตัว $800 แต่สัญญาจะแนะนำคุณให้เพื่อนรวยๆ ของเขา คุณมีเวลาว่างในสุดสัปดาห์นี้พอดี จะรับไหม?',
            zh: '🤝 “曝光”陷阱：一位拥有50万粉丝的当地著名网红想要一次4小时的写实拍摄，筹码是“曝光”和艾特。他们拒绝支付你800美元的费用，但承诺把你推荐给他们有钱的朋友。你周末正好有空。你接吗？'
        },
        options: [
            { id: 'A', text: { en: '✅ Take the Deal:"One tag could lead to thousands of followers. It’s effective marketing for just my time."', th: '✅ รับงาน:"แค่แท็กเดียวอาจนำไปสู่ผู้ติดตามหลายพันคน มันคือการตลาดที่คุ้มค่าเมื่อแลกกับแค่เวลาของฉัน"', zh: '✅ 接受交易：“一个艾特可能会带来成千上万的粉丝。这只需要花点时间，是一次有效的营销。”' }, consequence: { en: '⚠️ Popular but Broke. You gain 2,000 followers, but most are"fans"of the influencer, not clients. You get 50 inquiries for more free work. Your brand feels"cheap."You wasted a weekend, but learned that clout doesn\'t pay rent.', th: '⚠️ ดังแต่ไม่มีกิน! คุณได้ผู้ติดตามเพิ่ม 2,000 คน แต่ส่วนใหญ่เป็น"แฟนคลับ"ของอินฟลูฯ ไม่ใช่ลูกค้า คุณได้รับคำขอให้มาถ่ายฟรีๆ อีก 50 งาน แบรนด์ของคุณดู"ราคาถูก"คุณเสียเวลาเปล่าในวันหยุด แต่ได้เรียนรู้ว่าความดังมันจ่ายค่าเช่าบ้านไม่ได้', zh: '⚠️ 名气大但没钱。你涨了2000个粉丝，但大多数是网红的“粉丝”，而不是客户。你收到了50个要求更多免费工作的咨询。你的品牌感觉很“廉价”。你浪费了一个周末，但学到了名气不能用来付房租。' }, stats: { competence: 20, ethics: 30, leadership: 20, innovation: 35 } },
            { id: 'B', text: { en: '🚫 Professional Refusal:"My time and gear cost money. I’ll offer a 20% discount for a tag, but never work for free."', th: '🚫 ปฏิเสธอย่างมืออาชีพ:"เวลาและอุปกรณ์ของฉันมีต้นทุน ฉันจะให้ส่วนลด 20% เพื่อแลกกับการแท็ก แต่จะไม่มีวันทำงานฟรี"', zh: '🚫 专业拒绝：“我的时间和器材都要花钱。我会提供20%的折扣换取艾特，但绝不免费工作。”' }, consequence: { en: '✅ Reputation Intact. The influencer respects the boundary and pays the discounted fee. You realize they actually HAD the budget all along. You build a premium reputation. Other professionals respect you for not lowering the market value.', th: '✅ รักษาชื่อเสียง! อินฟลูฯ คนนั้นยอมรับขอบเขตและจ่ายค่าจ้างแบบลดราคา คุณถึงได้รู้ว่าเขามีงบอยู่แล้วแต่แรก คุณสร้างชื่อเสียงระดับพรีเมียม มืออาชีพคนอื่นๆ เคารพคุณที่คุณไม่ยอมลดมูลค่าของตลาดลง', zh: '✅ 声誉完好。网红尊重了这个界限，并支付了折扣费用。你意识到他们其实一直都有预算。你建立了高端的声誉。其他同行因为你没有拉低市场价值而尊重你。' }, stats: { competence: 35, ethics: 40, leadership: 45, innovation: 20 } },
            { id: 'C', text: { en: '🎨 Selective Collaboration:"I will do the shoot ONLY if I have 100% creative control. We shoot my vision, not your typical selfies."', th: '🎨 เลือกคอลแลปอย่างมีเงื่อนไข:"ฉันจะถ่ายให้ก็ต่อเมื่อฉันมีอำนาจตัดสินใจทางศิลปะ 100% เลิกถ่ายเซลฟี่แบบเดิมๆ แล้วมาถ่ายตามวิสัยทัศน์ของฉัน"', zh: '🎨 选择性合作：“只有在我拥有100%创意控制权的前提下，我才拍。拍我的视觉，而不是你那套平庸的自拍。”' }, consequence: { en: '🔥 Viral Portfolio! Because you controlled the art, the photos look like a high-fashion magazine cover. The influencer is thrilled. You use these shots to land a major clothing brand contract worth $5,000. You turned"exposure"into a high-value asset.', th: '🔥 พอร์ตโฟลิโอไวรัล! เพราะคุณคุมงานศิลป์เอง ภาพเลยออกมาเหมือนหน้าปกนิตยสารแฟชั่นชั้นสูง อินฟลูฯ แฮปปี้มาก คุณใช้ภาพเหล่านี้ไปดีลงานกับแบรนด์เสื้อผ้าใหญ่จนได้สัญญา $5,000 คุณเปลี่ยน"ความโด่งดัง"ให้เป็นสินทรัพย์ที่มีมูลค่าสูงได้สำเร็จ', zh: '🔥 爆火的作品集！因为你控制了艺术表现，照片看起来像高端时尚杂志封面。网红非常激动。你利用这些照片拿到了一份价值5000美元的大型服装品牌合同。你把“曝光”变成了高价值资产。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 60 } },
            { id: 'D', text: { en: '🛡️ Contractual Exposure:"I do it for free, but you sign a contract allowing me full Commercial Rights to sell the photos as stock/prints."', th: '🛡️ ผูกมัดด้วยสัญญา:"ฉันถ่ายให้ฟรี แต่คุณต้องเซ็นสัญญาอนุญาตให้ฉันมีสิทธิ์ขาดเชิงพาณิชย์ในการขายภาพเป็นสต็อกหรือภาพพิมพ์ได้"', zh: '🛡️ 合同保障曝光：“我免费拍，但你得签合同，允许我拥有完整的商用权，可以将照片作为图库照/印刷品出售。”' }, consequence: { en: '💰 Passive Income Win! The influencer agrees. One of the shots is bought by an international travel agency for $1,200. You made more money than your original fee, and the influencer gets no cut. You played the long game and won.', th: '💰 ชนะด้วยรายได้เสริม! อินฟลูฯ ตกลง หนึ่งในภาพนั้นถูกเอเจนซี่ท่องเที่ยวระดับโลกซื้อไปในราคา $1,200 คุณทำเงินได้มากกว่าค่าตัวตอนแรก และอินฟลูฯ ก็ไม่ได้ส่วนแบ่งเลย คุณเป็นผู้เล่นเกมยาวและชนะในที่สุด', zh: '💰 被动收入胜利！网红同意了。其中一张照片被一家国际旅行社以1200美元买走。你赚到的钱比最初的劳务费还多，而且网红拿不到任何分成。你放长线钓大鱼，赢了。' }, stats: { competence: 45, ethics: 30, leadership: 35, innovation: 45 } }
        ]
    },

    {
        id: 'pho_003',
        text: {
            en: '💍 The Wedding Disaster: It’s the"Kiss"moment at a $10,000 wedding. Your primary camera’s shutter jams at that exact second. You have a backup camera around your neck. What is your immediate reaction?',
            th: '💍 หายนะงานแต่งงาน: มันคือช่วงเวลา"จูบ"ในงานแต่งราคาสองแสนห้า กล้องหลักของคุณชัตเตอร์ค้างในวินาทีนพอดี คุณมีกล้องสำรองแขวนอยู่ที่คอ ปฏิกิริยาแรกของคุณคืออะไร?',
            zh: '💍 婚礼灾难：这是一场价值1万美元的婚礼，正值“亲吻”时刻。你的主相机快门恰好在那一秒卡住了。你脖子上挂着备用相机。你的直觉反应是什么？'
        },
        options: [
            { id: 'A', text: { en: '⚡ Instant Switch:"Don’t blink. Drop the main, grab the backup, and fire. I might miss the first second, but I’ll catch the embrace."', th: '⚡ สลับทันที:"อย่ากระพริบตา ปล่อยกล้องหลัก คว้าตัวสำรองแล้วกดชัตเตอร์เลย อาจจะพลาดวิแรกไปแต่ต้องได้ท่ากอดกอดทิ้งท้าย"', zh: '⚡ 瞬间切换：“别眨眼。放下主相机，拿起备用相机，开火。我可能会错过头一秒，但我能拍到拥抱。”' }, consequence: { en: '✅ Professional Save. You caught the moment. The couple never knew there was a problem. This is why you carry a backup. You earn a 5-star review for being"fast and invisible."Your reputation for reliability grows.', th: '✅ กู้สถานการณ์อย่างมืออาชีพ! คุณจับภาพช่วงเวลานั้นได้ ทั้งคู่ไม่เคยรู้เลยว่ามีปัญหา นี่คือเหตุผลที่คุณต้องมีตัวสำรอง คุณได้รีวิว 5 ดาวฐานะทำงาน"รวดเร็วและเป็นมืออาชีพ"ชื่อเสียงเรื่องความเชื่อใจได้ของคุณพุ่งสูงขึ้น', zh: '✅ 专业救场。你抓拍到了那一刻。新人完全不知道出过问题。这就是你带备用机的原因。你因为“快速且悄无声息”获得了五星好评。你可靠的声誉日益增长。' }, stats: { competence: 50, ethics: 40, leadership: 35, innovation: 20 } },
            { id: 'B', text: { en: '🎭 Direct the Moment:"Stop! My camera jammed! Can you two do that one more time? The light was perfect, let’s get it again!"', th: '🎭 กำกับการแสดง:"หยุดก่อนครับ! กล้องผมค้าง! ทั้งคู่ช่วยจูบอีกรอบได้ไหมครับ? แสงกำลังสวยเลย ขอกันอีกสักรอบนะ!"', zh: '🎭 现场指挥：“停！我相机卡住了！你们两位能不能再来一次？光线很完美，我们再拍一遍！”' }, consequence: { en: '❌ Awkward Vibe. The family looks at you like a fraud. The moment feels staged and unnatural. The couple is annoyed. They still pay, but you get zero referrals from this wedding. You broke the"organic"flow of their special day.', th: '❌ บรรยากาศอึดอัด! ครอบครัวเล็งคุณเหมือนเป็นพวกกำมะลอ ช่วงเวลานั้นดูเป็นการแสดงและไม่เป็นธรรมชาติ ทั้งคู่รู้สึกหงุดหงิด พวกเขายังจ่ายเงินให้คุณแต่คุณจะไม่มีวันได้รับการแนะนำต่อจากงานนี้ คุณทำลายความลื่นไหลของวันพิเศษของพวกเขาไปแล้ว', zh: '❌ 气氛尴尬。家人们看你的眼神就像看个骗子。那个时刻感觉是摆拍的，很不自然。新人很生气。他们照样付钱，但你通过这场婚礼没得到任何转介绍。你打破了他们特殊日子里的“自然”流感。' }, stats: { competence: 20, ethics: 30, leadership: 20, innovation: 10 } },
            { id: 'C', text: { en: '📸 The Multitasking Hack:"Try to fix the jam while shooting with the backup in one hand. I need both options just in case."', th: '📸 แก้ไขพร้อมถ่าย:"พยายามซ่อมตัวที่ค้างไปพร้อมกับใช้มืออีกข้างถือตัวสำรองถ่าย ฉันต้องการตัวเลือกทั้งคู่เผื่อไว้"', zh: '📸 多任务处理技巧：“一只手用备用机拍摄，另一只手尝试修复卡住的相机。以防万一，我需要两个选项。”' }, consequence: { en: '⚠️ Blurry Results. Trying to do two things at once made you miss the focus on the backup. You have a blurry photo of the kiss. You spend 10 hours in Photoshop trying to"save"it. It looks okay, but it’s not your best work. Don’t be a hero, just be a photographer.', th: '⚠️ ภาพเบลอ! การพยายามทำสองอย่างพร้อมกันทำให้คุณหลุดโฟกัสในกล้องสำรอง คุณได้ภาพจูบที่เบลอๆ คุณต้องเสียเวลา 10 ชั่วโมงใน Photoshop เพื่อพยายาม"กู้"ภาพนั้น กลับออกมาพอดูได้แต่ไม่ใช่ผลงานที่ดีที่สุด อย่าพยายามเป็นฮีโร่ แค่เป็นช่างภาพที่ทำตามหน้าที่ก็พอ', zh: '⚠️ 结果模糊。尝试一心二用导致你备用机的对焦飞了。你得到了一张模糊的吻照。你花了10个小时用Photoshop尝试“拯救”它。看起来还行，但不是你最好的作品。别逞英雄，就做一个摄影师该做的。' }, stats: { competence: 30, ethics: 30, leadership: 25, innovation: 40 } },
            { id: 'D', text: { en: '🤫 The Silent Panic:"Pretend it’s fine. I’ll keep clicking the jammed shutter so they think I’m working, then I’ll capture the reception later."', th: '🤫 ตีเนียน:"ทำเป็นเหมือนไม่มีอะไรเกิดขึ้น กดชัตเตอร์ตัวที่ค้างรัวๆ ให้เขาคิดว่าเราทำงานอยู่ แล้วค่อยไปเน้นเก็บภาพบรรยากาศช่วงงานเลี้ยงแทน"', zh: '🤫 沉默的恐慌：“假装没事。我会继续按卡住的快门，让他们觉得我在工作，待会儿去拍接待处。”' }, consequence: { en: '💀 Legal Nightmare. You missed the one photo they paid $10k for. The couple sues you for breach of contract. You have no"Safe Harbor"in your agreement for gear failure. You lose the case and your insurance premiums skyrocket. Total failure.', th: '💀 ฝันร้ายทางกฎหมาย! คุณพลาดภาพสำคัญที่เขาจ่ายเงินตั้งสองแสนห้า ทั้งคู่ฟ้องคุณฐานผิดสัญญา คุณไม่มีข้อตกลง"คุ้มครองเหตุสุดวิสัย"ในสัญญาเรื่องอุปกรณ์ขัดข้อง คุณแพ้คดีและค่าเบี้ยประกันของคุณพุ่งทะลุเพดาน ล้มเหลวโดยสิ้นเชิง', zh: '💀 法律噩梦。你错过了他们花了1万美元买的那张核心照片。这对新人起诉你违约。你的合同中没有关于器材故障的“避风港”条款。你输掉了官司，保费飙升。彻底失败。' }, stats: { competence: 10, ethics: 10, leadership: 10, innovation: -20 } }
        ]
    },

    {
        id: 'pho_004',
        text: {
            en: '🎨 The Ethics of Retouching: A portrait client (a small business owner) asks you to"slim down"her waist by 4 inches and remove all facial wrinkles. She says she wants to look 10 years younger for her website. Do you comply?',
            th: '🎨 จริยธรรมในการแต่งภาพ: ลูกค้าถ่ายภาพบุคคล (เจ้าของธุรกิจขนาดเล็ก) ขอให้คุณ"บีบเอว"เธอเข้าไปสัก 4 นิ้วและพวริ้วรอยบนใบหน้าออกให้หมดเธอบอกว่าอยากดูเด็กกว่าเดิมสัก 10 ปีเพื่อใช้ลงเว็บไซต์ คุณจะยอมทำตามไหม?',
            zh: '🎨 修图的道德：一位人像客户（一个小企业主）要求你把她的腰“修细”4英寸，并去掉脸上所有的皱纹。她说她想为自己的网站看起来年轻10岁。你会照做吗？'
        },
        options: [
            { id: 'A', text: { en: '🖌️ The"Client is King"Path:"It’s my job to make them happy. I’ll do heavy retouching. A happy client is a paying client."', th: '🖌️ วิถี"ลูกค้าคือพระเจ้า":"หน้าที่ของฉันคือทำให้เขามีความสุข ฉันจะจัดเต็มเรื่องแต่งภาพ ลูกค้าแฮปปี้เงินสะพัด"', zh: '🖌️ “客户至上”之路：“我的工作就是让他们快乐。我会进行过度修图。快乐的客户就是付钱的客户。”' }, consequence: { en: '⚠️ Short-term Win. She loves it and pays a bonus. BUT: When people meet her in person, they are shocked by the difference. Your studio earns a reputation for"fake"photography. High-end lifestyle brands stop hiring you because your work lacks authenticity.', th: '⚠️ ชนะแค่ระยะสั้น! เธอชอบมากและให้โบนัสพิเศษ แต่: เมื่อผู้คนมาเจอตัวจริงของเธอ พวกเขาตกใจมากที่ต่างกันลิบลับ สตูดิโอของคุณเลยได้ชื่อเสียงเรื่องงานถ่าย"ปลอม"แบรนด์ไลฟ์สไตล์หรูๆ เลิกจ้างคุณเพราะงานของคุณขาดความสมจริง', zh: '⚠️ 短期获胜。她非常喜欢并支付了奖金。但是：当人们见到她本人时，会被这种差异吓到。你的工作室赢得了“虚假”摄影的名声。高端生活方式品牌停止聘请你，因为你的作品缺乏真实感。' }, stats: { competence: 40, ethics: 20, leadership: 20, innovation: 30 } },
            { id: 'B', text: { en: '⚖️ The Balanced Approach:"I’ll do subtle skin cleaning and light slimming, but 4 inches is too much. I want you to look like the best version of YOU, not someone else."', th: '⚖️ ทางสายกลาง:"ฉันจะเกลี่ยผิวให้เนียนและบีบเอวเล็กน้อย แต่ 4 นิ้วมันเยอะไป ฉันอยากให้คุณดูเป็นตัวของคุณเองในเวอร์ชันที่ดูดีที่สุด ไม่ใช่คนอื่น"', zh: '⚖️ 平衡的方法：“我会做细微的皮肤清理和轻度修身，但4英寸太多了。我想让你看起来像最好的‘你’，而不是别人。”' }, consequence: { en: '✅ Ethical Success. She’s initially hesitant but loves the natural results. She feels confident instead of fake. You become known for"Empowerment Photography."You get featured in a blog about body positivity. Your niche becomes clear.', th: '✅ สำเร็จด้วยจริยธรรม! ตอนแรกเธอลังเลแต่สุดท้ายก็หลงรักผลงานที่ดูเป็นธรรมชาติ เธอรู้สึกมั่นใจมากกว่ารู้สึกปลอมๆ คุณกลายเป็นที่รู้จักในฐานะ"ช่างภาพที่ส่งเสริมพลังบวก"และได้รับการลงบล็อกเรื่อง Body Positivity ตลาดเฉพาะทางของคุณเริ่มชัดเจนขึ้น', zh: '✅ 道德上的成功。她起初有些犹豫，但喜欢这种自然的结果。她感到自信而非虚假。你以“赋能摄影”而闻名。你被一篇关于身体积极性的博客报道了。你的定位变得清晰。' }, stats: { competence: 45, ethics: 50, leadership: 40, innovation: 30 } },
            { id: 'C', text: { en: '🎨 The Artistic Purist:"I don’t do body manipulation. I’m a photographer, not a digital surgeon. If you want that, find someone else."', th: '🎨 สายศิลปินบริสุทธิ์:"ฉันไม่รับแก้อสรพิษ ฉันเป็นช่างภาพ ไม่ใช่ศัลยแพทย์ดิจิทัล ถ้าอยากได้แบบนั้นไปหาคนอื่นเถอะ"', zh: '🎨 艺术纯粹主义者：“我不做身体修正。我是摄影师，不是数字外科医生。如果你想要那个，找别人吧。”' }, consequence: { en: '⚠️ Respect but Less Revenue. You keep your integrity, but you lost the $500 gig and the client tells her friends you are"difficult to work with."Your career is pure, but your bank account is thin. You need to find clients who value"raw"art specifically.', th: '⚠️ ได้ความเคารพแต่รายได้ลด! คุณรักษาความสัตย์จริงไว้ได้แต่เสียงานมูลค่า $500 ไป แถมลูกค้ายังไปบอกเพื่อนๆ ว่าคุณ"ทำงานด้วยยาก"อาชีพคุณขาวสะอาดแต่เงินในกระเป๋าเบาบางลง คุณต้องหาลูกค้าที่ชอบงานสาย"เรียล"ให้เจอโดยเฉพาะ', zh: '⚠️ 赢得尊重但收入较少。你保持了正直，但你失去了一笔500美元的单子，而且客户告诉她的朋友你“很难合作”。你的职业生涯很纯粹，但银行存款很薄。你需要专门寻找那些看重“原始”艺术的客户。' }, stats: { competence: 30, ethics: 60, leadership: 25, innovation: 10 } },
            { id: 'D', text: { en: '📸 The"Better Angles"Strategy:"Instead of heavy editing, let’s reshoot with better lighting and poses that naturally flatter your shape. Professional technique over AI tools."', th: '📸 กลยุทธ์"มุมกล้องช่วยได้":"แทนที่จะมาแก้ภาพจัดๆ มาลองถ่ายกันใหม่ด้วยการจัดแสงและท่าทางที่ช่วยเสริมรูปร่างคุณให้ดูดีตามธรรมชาติเถอะ อาศัยเทคนิคระดับโปรแทนที่จะใช้ AI"', zh: '📸 “更好角度”策略：“与其过度修图，不如用更好的光线和姿势重拍，自然地衬托你的体型。专业技巧优于人工智能工具。”' }, consequence: { en: '✅ Master Craftman. The reshoot is stunning. You proved that skill beats software. She is so impressed she hires you for her entire staff. You gained $2,500 in new contracts because you showed you care about the result more than just clicking the button.', th: '✅ ยอดฝีมือ! การถ่ายใหม่ครั้งนี้ออกมาอึ้งมาก คุณพิสูจน์แล้วว่าทักษะเหนือกว่าซอฟต์แวร์ เธอประทับใจมากจนจ้างคุณไปถ่ายพนักงานทั้งบริษัท คุณได้สัญญาใหม่รวมมูลค่า $2,500 เพราะความใส่ใจในผลลัพธ์มากกว่าแค่การกดปุ่มชัตเตอร์', zh: '✅ 大师级工匠。重拍的效果惊人。你证明了技巧胜过软件。她印象非常深刻，甚至雇你为她所有的员工拍摄。你因为表现出对结果的在乎而获得了2500美元的新合同，而不仅仅是按个快门。' }, stats: { competence: 60, ethics: 40, leadership: 45, innovation: 40 } }
        ]
    },

    {
        id: 'pho_005',
        text: {
            en: '🚨 The Copyright Theft: You find a major national sporting goods brand using one of your photos for a massive billboard campaign. They didn’t license it; they just took it from Instagram. Your lawyer says you can settle for $2,000 or sue for $50,000, but a lawsuit could take years. What do you do?',
            th: '🚨 การขโมยลิขสิทธิ์: คุณพบแบรนด์อุปกรณ์กีฬาระดับประเทศใช้ภาพของคุณทำแคมเปญบิลบอร์ดยักษ์ใหญ่ พวกเขาไม่ได้ซื้อลิขสิทธิ์ แค่ดึงภาพมาจาก Instagram ทนายบอกว่าคุณสามารถเรียกร้องค่าเสียหาย $2,000 หรือฟ้องร้องเรียกเงิน $50,000 แต่คดีอาจลากยาวไปหลายปี จะเอายังไง?',
            zh: '🚨 版权失窃：你发现一家大型国家体育用品品牌在巨型广告牌活动中使用了你的一张照片。他们没有获得授权，只是从Instagram上拿走了它。你的律师说你可以以2000美元和解，或者起诉索赔5万美元，但诉讼可能需要数年时间。你会怎么做？'
        },
        options: [
            { id: 'A', text: { en: '💰 Quick Settlement:"I need the cash now to buy gear. $2,000 is better than nothing, and I don\'t want the stress."', th: '💰 ยอมความด่วน:"ฉันต้องใช้เงินตอนนี้ไปซื้ออุปกรณ์ $2,000 ยังดีกว่าไม่ได้อะไรเลย ไม่อยากปวดหัวเรื่องคดีด้วย"', zh: '💰 快速和解：“我现在需要现金买器材。2000美元总比没有好，而且我不想有压力。”' }, consequence: { en: '⚠️ Money but Weakness. You get the $2,000, but the brand puts you on a"blacklist"of creators who are easy to push around. They continue using your work without permission later. You are seen as a"hobbyist"by the industry, not a business owner.', th: '⚠️ ได้เงินแต่ดูอ่อนแอ! คุณได้เงิน $2,000 แต่แบรนด์นั้นหมายหัวคุณเป็นครีเอเตอร์ที่"จัดการง่าย"ต่อไปพวกเขาก็ยังแอบเอางานคุณไปใช้โดยไม่ขออีก วงการมองคุณเป็นแค่"พวกมือสมัครเล่น"ไม่ใช่เจ้าของธุรกิจจริงๆ', zh: '⚠️ 拿到了钱但表现出软弱。你拿到了2000美元，但品牌将你列入了“好欺负”的创作者“黑名单”。他们以后会继续未经许可使用你的作品。你在业界被视为“业余爱好者”，而不是个企业主。' }, stats: { competence: 30, ethics: 30, leadership: 20, innovation: 20 } },
            { id: 'B', text: { en: '⚖️ The"Strong Letter"Middle Ground:"Demand $8,000 (Market Rate x4) as a penalty. If they don’t pay in 48 hours, then we sue. Show teeth, but stay practical."', th: '⚖️ สายเจรจาข่มขวัญ:"เรียกเงิน $8,000 (4 เท่าของราคาตลาด) เป็นค่าปรับ ถ้าไม่จ่ายใน 48 ชม. ค่อยฟ้อง โชว์เขี้ยวเล็บให้เห็นแต่ยังมองตามความเป็นจริง"', zh: '⚖️ “强势信函”中间立场：“要求赔偿8000美元（市场价的4倍）作为惩罚。如果他们在48小时内不付钱，我们就起诉。表现出强硬，但要保持务实。”' }, consequence: { en: '✅ Respect & Revenue! The brand’s legal team realizes you know your worth. They pay the $8,000 immediately to avoid a PR disaster. You use the money to upgrade your studio. You are now respected as a professional who protects their intellectual property.', th: '✅ ได้ทั้งความเคารพและรายได้! ฝ่ายกฎหมายของแบนด์รู้ซึ้งแล้วว่าคุณไม่ใช่คนที่จะมาล้อเล่นได้ พวกเขาจ่าย $8,000 ทันทีเพื่อเลี่ยงวิกฤต PR คุณเอาเงินไปอัปเกรดสตูดิโอ ตอนนี้คุณได้รับการยอมรับในฐานะมืออาชีพที่รู้จักปกป้องลิขสิทธิ์ทางปัญญาของตัวเอง', zh: '✅ 尊重与收入！品牌的法律团队意识到你清楚自己的价值。他们立即支付了8000美元，以避免公关灾难。你利用这笔钱升级了工作室。你现在被视为一名保护自己知识产权的专业人士。' }, stats: { competence: 45, ethics: 40, leadership: 45, innovation: 30 } },
            { id: 'C', text: { en: '🔥 Full Nuclear Sue:"I want the $50,000. It’s about the principle. I will spend every cent and every year to win. No bullying allowed."', th: '🔥 ฟ้องให้ยับ:"ฉันจะเอา $50,000 มันคือเรื่องของศักดิ์ศรี ฉันจะทุ่มทุกบาททุกสตางค์และเวลาทุกปีเพื่อเอาชนะ ไม่มีการยอมให้ใครมารังแกทั้งนั้น"', zh: '🔥 全面开战起诉：“我要5万美元。这是原则问题。我会花每一分钱、每一年去赢。绝不容忍霸凌。”' }, consequence: { en: '⚖️ The Long Grind. 3 years later, you win $30,000 after lawyer fees. The industry sees you as"The Giant Killer."You become a hero for independent artists. BUT: The stress cost you many creative years. You are famous in the legal world, but your photography portfolio stagnated during the fight.', th: '⚖️ การต่อสู้ที่ลากยาว! 3 ปีต่อมาคุณชนะคดีและเหลือเงิน $30,000 หลังหักค่าทนาย วงการมองคุณเป็น"มือปราบยักษ์ใหญ่"คุณกลายเป็นฮีโร่ของเหล่าศิลปินอิสระ แต่: ความเครียดทำให้คุณเสียเวลาสร้างสรรค์ผลงานไปหลายปี คุณดังในวงการกฎหมายแต่พอร์ตภาพถ่ายของคุณนิ่งสนิทในช่วงที่ต่อสู้คดี', zh: '⚖️ 漫长的消耗。3年后，你扣除律师费后赢得了3万美元。业界视你为“巨人杀手”。你成了独立艺术家的英雄。但是：压力让你虚度了多年的创作时光。你在法律界出名了，但在打官司期间，你的摄影作品集停滞不前。' }, stats: { competence: 40, ethics: 60, leadership: 50, innovation: 20 } },
            { id: 'D', text: { en: '🤝 Leverage for Partnership:"I won’t sue if you give me a $20,000 contract to shoot your next three national campaigns. Turn an enemy into a client."', th: '🤝 เปลี่ยนคดีเป็นคอนเนคชัน:"ฉันจะไม่ฟ้องถ้าคุณมอบสัญญา $20,000 ให้ฉันถ่ายแคมเปญระดับประเทศ 3 งานถัดไป เปลี่ยนศัตรูให้กลายเป็นลูกค้าซะเลย"', zh: '🤝 利用机会合作：“如果你给我一份2万美元的合同，负责拍摄你们接下来的三个全国性活动，我就不起诉。化敌为友。”' }, consequence: { en: '🏆 Master Strategist! The brand is impressed by your business savvy. They sign the contract. You are now the official photographer for a major brand. Your net worth soars and you are now in the"Big Leagues."High-risk, high-reward move.', th: '🏆 ยอดนักยุทธศาสตร์! แบรนด์ประทับใจในหัวธุรกิจของคุณ พวกเขาเซ็นสัญญาให้ทันที ตอนนี้คุณกลายเป็นช่างภาพอย่างเป็นทางการของแบรนด์ใหญ่ รายได้คุณพุ่งกระฉูดและก้าวเข้าสู่"ลีกใหญ่"เรียบร้อย นี่คือการเดินเกมที่เสี่ยงสูงแต่คุ้มค่าสุดๆ', zh: '🏆 大师级战略家！品牌被你的商业头脑打动。他们签下了合同。你现在成为了大品牌的官方摄影师。你的身价飞涨，你现在进入了“大联盟”。高风险、高回报之举。' }, stats: { competence: 60, ethics: 30, leadership: 55, innovation: 50 } }
        ]
    },

    {
        id: 'pho_006',
        text: {
            en: '💾 The Card Corruption: You just finished a high-stakes luxury wedding. Both memory cards in your camera have failed. You lost 40% of the ceremony photos. What do you do?',
            th: '💾 การ์ดหน่วยความจำเสีย: คุณเพิ่งถ่ายงานแต่งงานสุดหรูเสร็จ แต่การ์ดทั้งสองใบเสีย คุณทำรูปหายไป 40% คุณจะทำอย่างไร?',
            zh: '💾 存储卡顺坏：你刚拍完一场奢华婚礼，相机的两张存储卡都坏了。你丢了40%的仪式照片。你会怎么做？'
        },
        options: [
            { id: 'A', text: { en: '🤝 Honesty & Refund:"Tell the couple immediately, refund the labor cost, and offer a free \'post-wedding\' shoot."', th: '🤝 ซื่อสัตย์และคืนเงิน:"บอกบ่าวสาวทันที คืนค่าแรง และเสนอถ่ายรูปนอกรอบให้ฟรี"', zh: '🤝 坦诚并退款：“立即告知新人，退还劳务费，并提供免费的‘婚后’拍摄。”' }, consequence: { en: '✅ Trust Recovered. The couple appreciates your integrity. The post-wedding shots are better than the originals. Ethics 100.', th: '✅ กู้คืนความเชื่อใจ บ่าวสาวชื่นชมความซื่อสัตย์ของคุณ รูปถ่ายนอกรอบออกมาสวยกว่าเดิม ค่าจริยธรรม 100', zh: '✅ 赢得信任。新人欣赏你的正直。婚后拍摄的效果比原来的还好。职业道德指标 100。' }, stats: { competence: 30, ethics: 50, leadership: 40, innovation: 20 } },
            { id: 'B', text: { en: '🛠️ Data Recovery Pro:"Spend $2,000 on a professional laboratory to attempt recovery without telling the client yet."', th: '🛠️ จ้างกู้ข้อมูล:"จ่ายเงิน $2,000 ให้ห้องแล็บกู้คืนข้อมูลโดยยังไม่บอกลูกค้า"', zh: '🛠️ 专业数据恢复：“花2000美元请专业实验室尝试恢复，先不告诉客户。”' }, consequence: { en: '✅ Success! 99% of images recovered. You lost your profit, but saved your reputation. Competence 100.', th: '✅ สำเร็จ! กู้คืนรูปได้ 99% แม้จะเสียกำไรไปแต่รักษาชื่อเสียงไว้ได้ ค่าความเชี่ยวชาญ 100', zh: '✅ 成功！恢复了99%的图像。你虽然亏损了，但保住了名声。能力指标 100。' }, stats: { competence: 50, ethics: 35, leadership: 30, innovation: 10 } },
            { id: 'C', text: { en: '🤐 Bluff & Edit:"Don\'t tell them. Use the remaining 60% and pretend those were the best \'artistic choices.\'"', th: '🤐 ปกปิดและเนียน:"ไม่บอกลูกค้า ใช้รูปที่เหลือ 60% แล้วแสร้งว่านั่นคือการตัดสินใจด้านศิลปะที่ดีที่สุด"', zh: '🤐 隐瞒并修图：“别告诉他们。用剩下的60%，假装那是最棒的‘艺术选择’。”' }, consequence: { en: '❌ Lawsuit! The bride realizes the exchange of rings is missing. She sues for emotional distress and ruins you on social media.', th: '❌ โดนฟ้อง! เจ้าสาวรู้ว่ารูปช่วงแลกแหวนหายไป เธอฟ้องคุณและแฉจนคุณเสียคนในโซเชียล', zh: '❌ 吃官司！新娘发现交换戒指的画面没了。她起诉你造成精神损失，并在社交媒体上把你搞臭。' }, stats: { competence: 15, ethics: 10, leadership: 10, innovation: 40 } },
            { id: 'D', text: { en: '🔄 Crowdsource:"Contact all guests and ask for their phone photos to fill the gaps in your album."', th: '🔄 ขอรูปจากแขก:"ติดต่อแขกทุกคนเพื่อขอรูปจากมือถือมาเติมเต็มส่วนที่หายไปในอัลบั้ม"', zh: '🔄 众包：“联系所有宾客，请求他们提供手机拍摄的照片，以填补相册的空缺。”' }, consequence: { en: '⚠️ Mixed Results. You have a full story, but the quality difference is obvious. You look unprofessional but resourceful.', th: '⚠️ ผลลัพธ์ก้ำกึ่ง คุณเล่าเรื่องได้ครบถ้วนแต่คุณภาพรูปต่างกันอย่างชัดเจน คุณดูเหมือนมือสมัครเล่นที่แก้ปัญหาเก่ง', zh: '⚠️ 结果参差不齐。故事讲完了，但画质差异明显。你看起不专业，但很有办法。' }, stats: { competence: 25, ethics: 30, leadership: 40, innovation: 30 } }
        ]
    },

    {
        id: 'pho_007',
        text: {
            en: '📸 The"Exposure"Deal: A celebrity influencer with 2 million followers wants a 4-hour shoot for free in exchange for"exposure"and a tag on Instagram. What do you do?',
            th: '📸 งานแลกโปรโมท: อินฟลูเอนเซอร์ชื่อดังที่มีผู้ติดตาม 2 ล้านคนขอให้คุณถ่ายรูปให้ฟรี 4 ชั่วโมง แลกกับการแท็กชื่อคุณใน Instagram คุณจะทำอย่างไร?',
            zh: '📸 “曝光论”交易：一位拥有200万粉丝的网红想让你免费拍摄4小时，以换取“曝光”和Instagram上的艾特。你会怎么做？'
        },
        options: [
            { id: 'A', text: { en: '🚫 Decline & Quote:"I don\'t work for exposure. Send them a professional invoice with your standard rates."', th: '🚫 ปฏิเสธและส่งราคา:"ฉันไม่ทำงานแลกการโปรโมท ส่งใบเสนอราคามาตรฐานของคุณไปให้แทน"', zh: '🚫 拒绝并报价：“我不为曝光工作。发送包含你标准费率的专业账单。”' }, consequence: { en: '✅ Respect Earned. They realize you are a professional. They actually pay full price and hire you regularly. Competence up.', th: '✅ ได้รับความเคารพ พวกเขารู้ว่าคุณเป็นมืออาชีพ จึงยอมจ่ายราคาเต็มและจ้างคุณเป็นประจำ ค่าความเชี่ยวชาญเพิ่มขึ้น', zh: '✅ 赢得尊重。他们意识到你是专业人士。他们最后付了全款，并定期聘请你。能力指标提升。' }, stats: { competence: 40, ethics: 35, leadership: 45, innovation: 10 } },
            { id: 'B', text: { en: '🤝 Partial Barter:"I\'ll do it for free, but I want the full copyright to sell these images as stock or to magazines."', th: '🤝 ข้อตกลงแลกเปลี่ยน:"ถ่ายให้ฟรี แต่ต้องได้ลิขสิทธิ์เต็มเพื่อเอาไปขายเป็นภาพสต็อกหรือขายให้แมกกาซีน"', zh: '🤝 部分易货：“我会免费拍，但我要求拥有全部版权，以便将这些图像作为库存照片或卖给杂志。”' }, consequence: { en: '✅ Strategic Win! One photo gets bought by a major fashion magazine for $5,000. You made more than your fee. Innovation 100.', th: '✅ ชนะอย่างมีกลยุทธ์! รูปหนึ่งใบถูกนิตยสารแฟชั่นซื้อไปในราคา $5,000 คุณทำเงินได้มากกว่าค่าแรงปกติเสียอีก ค่า ‘นวัตกรรม’ 100', zh: '✅ 策略性胜利！其中一张照片被一家主流时尚杂志以5000美元收购。你赚得比固定劳务费还多。创新指标 100。' }, stats: { competence: 45, ethics: 30, leadership: 40, innovation: 50 } },
            { id: 'C', text: { en: '🤳 Accept the Hype:"Yes! This is the big break I need. I\'ll do it and spend extra time editing."', th: '🤳 ยอมรับกระแส:"ตกลง! นี่อาจเป็นโอกาสแจ้งเกิดที่ฉันรอคอย จะถ่ายให้และตั้งใจแต่งรูปสุดๆ"', zh: '🤳 接受热度：“太棒了！这是我需要的成名机会。我会接，并花额外时间修图。”' }, consequence: { en: '⚠️ Empty Fame. You gain 5,000 followers, but none of them are paying clients. You are now known as the"Free Photographer."', th: '⚠️ ชื่อเสียงจอมปลอม ได้ผู้ติดตามเพิ่ม 5,000 คน แต่ไม่มีใครจ้างงานจริงจัง ตอนนี้ทุกคนจำคุณในฐานะ"ช่างภาพที่ถ่ายให้ฟรี"', zh: '⚠️ 虚名。你涨了5000个粉丝，但没一个是付钱的客户。你现在被称为“免费摄影师”。' }, stats: { competence: 30, ethics: 15, leadership: 20, innovation: 30 } },
            { id: 'D', text: { en: '📉 Negotiate Half:"I\'ll offer a 50% discount if you promise three posts and a permanent link in your bio."', th: '📉 เจรจาครึ่งราคา:"เสนอส่วนลด 50% แลกกับโพสต์ 3 ครั้งและใส่ลิงก์เว็บคุณที่หน้าโปรไฟล์เขา"', zh: '谈半价：“如果你承诺发三条动态并在简介里永久挂我链接，我给你打五折。”' }, consequence: { en: '✅ Fair Trade. You get some cash and decent marketing. A solid middle-ground for a growing business.', th: '✅ การแลกเปลี่ยนที่ยุติธรรม คุณได้เงินบ้างและได้การตลาดที่ใช้ได้ เป็นทางสายกลางที่ดีสำหรับธุรกิจที่กำลังโต', zh: '✅ 公平交易。你拿到了一些现金和还不错的推广。这是业务增长的一个稳健折中方案。' }, stats: { competence: 35, ethics: 30, leadership: 35, innovation: 20 } }
        ]
    },

    {
        id: 'pho_008',
        text: {
            en: '⛰️ The Dangerous Shot: To get the perfect landscape shot for a travel magazine, you need to climb a restricted, unstable ledge. Do you take the risk?',
            th: '⛰️ ช็อตเสี่ยงตาย: เพื่อให้ได้ภาพวิวที่สวยที่สุดสำหรับนิตยสารท่องเที่ยว คุณต้องปีนไปยังหน้าผาที่อันตรายและเป็นพื้นที่หวงห้าม คุณจะเสี่ยงไหม?',
            zh: '⛰️ 危险镜头：为了给旅游杂志拍到完美的风景照，你需要爬上一段受限且不稳定的岩壁。你愿意冒险吗？'
        },
        options: [
            { id: 'A', text: { en: '🚁 Use a Drone:"Safety first. I\'ll fly my drone up there instead. I can get the same angle safely."', th: '🚁 ใช้โดรน:"ความปลอดภัยต้องมาก่อน จะใช้โดรนบินขึ้นไปถ่ายแทน ได้มุมเดียวกันแต่ปลอดภัยกว่า"', zh: '🚁 使用无人机：“安全第一。我会用无人机飞上去。这样我也能安全地获得同样的视角。”' }, consequence: { en: '✅ Innovation Win! The magazine loves the unique drone perspective. You are hired for a drone-only project next month. Innovation 100.', th: '✅ ชนะด้วยนวัตกรรม! นิตยสารชอบมุมมองจากโดรนที่แปลกใหม่ คุณถูกจ้างงานถ่ายโดรนโดยเฉพาะในเดือนหน้า ค่า ‘นวัตกรรม’ 100', zh: '✅ 创新获胜！杂志非常喜欢独特的无人机视角。你下个月又接到了一个全无人机拍摄的项目。创新指标 100。' }, stats: { competence: 40, ethics: 35, leadership: 30, innovation: 55 } },
            { id: 'B', text: { en: '🧗 Take the Risk:"The best shots require sacrifice. I\'m climbing it for the art."', th: '🧗 ยอมเสี่ยง:"ภาพที่ดีที่สุดต้องแลกมาด้วยความลำบาก จะปีนขึ้นไปเพื่อศิลปะ"', zh: '🧗 冒险一试：“最好的照片需要牺牲。为了艺术，我爬了。”' }, consequence: { en: '✅ Legendary Shot. You get the Cover of the Year. BUT: You receive a heavy fine for trespassing and a lifetime ban from the park.', th: '✅ ช็อตในตำนาน! คุณได้ขึ้นหน้าปกแห่งปี แต่: คุณถูกปรับฐานบุกรุกและถูกแบนจากอุทยานนั้นตลอดชีวิต', zh: '✅ 传奇镜头。你拿到了年度封面。但是：你因擅自闯入被处以重罚，且终身禁止进入该公园。' }, stats: { competence: 50, ethics: 15, leadership: 20, innovation: 45 } },
            { id: 'C', text: { en: '🔍 Different Viewpool:"It\'s not worth it. I\'ll find a more creative angle from the safe path."', th: '🔍 หามุมใหม่:"มันไม่คุ้มเลย จะหามุมที่สร้างสรรค์กว่าเดิมจากเส้นทางที่ปลอดภัย"', zh: '🔍 寻找新视角：“不值得。我会从安全地带找到一个更有创意的角度。”' }, consequence: { en: '⚠️ Safe but Standard. The photo is good, but the magazine goes with another photographer who got the"unique"shot. You stay safe but lose the layout.', th: '⚠️ ปลอดภัยแต่ธรรมดาไป รูปออกมาดีแต่นิตยสารเลือกใช้รูปของช่างภาพอีกคนที่ได้มุมที่แปลกกว่า คุณปลอดภัยแต่พลาดงานนี้ไป', zh: '⚠️ 安全但平庸。照片不错，但杂志选择了另一个拍到“独特”镜头的摄影师。你保住了命，但丢了版面。' }, stats: { competence: 35, ethics: 40, leadership: 40, innovation: 20 } },
            { id: 'D', text: { en: '🤝 Hire a Local Guide:"I\'ll pay a local climber to carry my gear and show me a legal, secret path to a similar view."', th: '🤝 จ้างไกด์ท้องถิ่น:"จะจ้างนักปีนเขาแถวนั้นช่วยแบกของและพาไปจุดชมวิวลับที่ถูกกฎหมายและให้ภาพคล้ายๆ กัน"', zh: '🤝 雇佣当地向导：“我会付钱给当地登山者背我的设备，并带我走一条合法的秘密小路去往类似的景观。”' }, consequence: { en: '✅ Professional & Secure. You get a great shot safely and support the local economy. The magazine values your logistics skills. Leadership up.', th: '✅ มือโปรและมั่นคง! ได้ภาพสวยแบบปลอดภัยและช่วยเศรษฐกิจท้องถิ่น นิตยสารชื่นชมทักษะการจัดการของคุณ ค่าความเป็นผู้นำเพิ่มขึ้น', zh: '✅ 专业且安全。你安全地拍到了大片并支持了当地经济。杂志非常看重你的调度能力。领导力指标提升。' }, stats: { competence: 45, ethics: 40, leadership: 50, innovation: 30 } }
        ]
    },

    {
        id: 'pho_009',
        text: {
            en: '⚖️ The Retouching Dilemma: A portrait client wants you to edit them to look 20 years younger and 15kg lighter. It would look completely fake. What do you do?',
            th: '⚖️ วิกฤตการรีทัช: ลูกค้าถ่ายพอร์ตเทรตขอให้คุณแต่งรูปให้ดูเด็กกว่าเดิม 20 ปีและผอมลง 15 กก. ซึ่งมันจะดูปลอมมาก คุณจะทำอย่างไร?',
            zh: '⚖️ 修图困境：一位肖像客户想让你把他们修得年轻20岁，瘦30斤。这看起来会非常假。你会怎么做？'
        },
        options: [
            { id: 'A', text: { en: '🎨 The Natural Compromise:"Explain your philosophy of \'Enhanced Reality.\' Offer to soften wrinkles and adjust lighting instead."', th: '🎨 ทางสายกลาง:"อธิบายปรัชญาการแต่งรูปแบบเน้นความจริงที่ดูดีขึ้น เสนอให้ลดริ้วรอยและปรับแสงแทน"', zh: '🎨 自然折中：“解释你的‘增强现实’理念。提议通过光影和虚化皱纹来替代。”' }, consequence: { en: '✅ Happy Client. They realize they look better when they look like themselves. You keep your artistic integrity. Ethics 100.', th: '✅ ลูกค้าแฮปปี้ พวกเขาตระหนักว่าดูดีที่สุดเมื่อเป็นตัวเอง คุณรักษาจุดยืนทางศิลปะไว้ได้ ค่าจริยธรรม 100', zh: '✅ 满意的客户。他们意识到做自己时看起来更棒。你保持了艺术诚信。职业道德指标 100。' }, stats: { competence: 40, ethics: 50, leadership: 40, innovation: 30 } },
            { id: 'B', text: { en: '🖥️ Give Them Everything:"The client is always right. Spend 10 hours in Photoshop making the impossible happen."', th: '🖥️ จัดให้เต็มที่:"ลูกค้าคือพระเจ้า จะเสียเวลา 10 ชม. ใน Photoshop เพื่อทำสิ่งที่เป็นไปไม่ได้ให้เป็นจริง"', zh: '全力满足：“客户永远是对的。花10小时修图，化腐朽为神奇。”' }, consequence: { en: '⚠️ Uncanny Valley. The client is happy, but you are embarrassed to put the photo in your portfolio. It looks like a plastic doll. Competence down.', th: '⚠️ ดูแปลกประหลาด ลูกค้าชอบใจแต่คุณอายเกินกว่าจะเอาภาพนี้ลงพอร์ต รูปมันดูเหมือนตุ๊กตาพลาสติก ค่าความเชี่ยวชาญลดลง', zh: '⚠️ 恐怖谷效应。客户很满意，但你却不敢把这张照片放进作品集。由于修图过度，看起来像个塑料娃娃。能力指标下降。' }, stats: { competence: 20, ethics: 20, leadership: 15, innovation: 20 } },
            { id: 'C', text: { en: '🚫 Refuse the Work:"I am a photographer, not a plastic surgeon. I don\'t do unrealistic modifications."', th: '🚫 ปฏิเสธงาน:"ฉันเป็นช่างภาพ ไม่ใช่ศัลยแพทย์ ไม่รับแต่งรูปที่เกินจริงขนาดนั้น"', zh: '🚫 拒绝拍摄：“我是摄影师，不是整形医生。我不做不切实际的修改。”' }, consequence: { en: '⚠️ Strict Reputation. You gain a reputation for"Authenticity,"but lose the client and the word-of-mouth revenue from their social circle.', th: '⚠️ ชื่อเสียงที่เคร่งครัด ได้ชื่อว่าเป็นช่างภาพ"สายเรียล"แต่เสียลูกค้าและรายได้จากการแนะนำบอกต่อในกลุ่มเพื่อนเขา', zh: '⚠️ 严苛的名声。你赢得了“真实”的声誉，但也失去了这位客户及其社交圈的口碑收入。' }, stats: { competence: 35, ethics: 40, leadership: 30, innovation: 10 } },
            { id: 'D', text: { en: '🎭 High-Concept Edit:"Do the heavy edit, but style it as a \'conceptual art project\' about social media pressure."', th: '🎭 แต่งแบบงานศิลป์:"แต่งให้หนักตามขอ แต่จัดวางเป็นแนวงานศิลปะเชิงสัญลักษณ์เรื่องความกดดันจากโซเชียลแทน"', zh: '概念性修图：“按照要求重修，但把它定义为一个关于社交媒体压力的‘概念艺术项目’。”' }, consequence: { en: '✅ Art Gallery Hit! The"Fake"photo wins a fine-art award. You managed to satisfy the client and your ego. Innovation 100.', th: '✅ งานอาร์ตที่ปัง! ภาพที่แต่งจนปลอมชนะรางวัลวิจิตรศิลป์ คุณทำให้ทั้งลูกค้าและตัวเองพอใจได้ ค่า ‘นวัตกรรม’ 100', zh: '✅ 艺术馆大火！这张“假”照片获得了美术奖。你成功地满足了客户，也成全了大我。创新指标 100。' }, stats: { competence: 40, ethics: 30, leadership: 35, innovation: 60 } }
        ]
    },
    {
        id: 'pho_010',
        text: {
            en: '💨 The High-Speed Action: A car brand wants you to shoot their new electric vehicle racing through a desert at 100mph. You need a"Chase Car"(a vehicle with a camera crane) but it costs $5,000 to rent and your budget is tight. Do you rent it or try to shoot from the window of your friend\'s SUV?',
            th: '💨 ปฏิบัติการความเร็วสูง: แบรนด์รถยนต์ต้องการให้คุณถ่ายรถไฟฟ้าตัวใหม่ขณะวิ่งทะลุทะเลทรายด้วยความเร็ว 160 กม./ชม. คุณต้องใช้"Chase Car"(รถที่มีเครนกล้อง) แต่ค่าเช่ามันสูงถึง $5,000 และงบคุณจำกัด คุณจะยอมเช่าหรือลองถ่ายจากหน้าต่างรถ SUV ของเพื่อนแทน?',
            zh: '💨 高速动作拍摄：一家汽车品牌想要你拍摄他们的新型电动汽车以100英里/小时的速度穿越沙漠。你需要一辆“跟拍车”（带有摄像摇臂的车辆），但租金要5000美元，而你的预算很紧。你是租用它，还是尝试从朋友的SUV窗口拍摄？'
        },
        options: [
            { id: 'A', text: { en: '🎥 Rent the Chase Car:"Safety and stability are non-negotiable for action. Spend the money to get the pro result."', th: '🎥 เช่า Chase Car:"ความปลอดภัยและความนิ่งของภาพคือสิ่งที่ต่อรองไม่ได้สำหรับงานสายแอ็กชัน ยอมควักเงินเพื่อให้ได้งานระดับบมืออาชีพเถอะ"', zh: '租用跟拍车：“对于动作拍摄，安全和稳定性是不可逾越的底线。花这笔钱去获得专业的结果。”' }, consequence: { en: '✅ Spectacular Production! The shots are buttery smooth and professional. The car brand is so impressed they hire you for a global commercial. You are now an"Action Specialist."You broke even on the budget but earned a massive reputation boost.', th: '✅ โปรดักชันสุดอลังการ! ภาพที่ได้ออกมาลื่นไหลและดูเป็นมืออาชีพสุดๆ แบรนด์รถประทับใจมากจนจ้างคุณไปถ่ายโฆษณาระดับโลกต่อ ตอนนี้คุณกลายเป็น"ผู้เชี่ยวชาญสายแอ็กชัน"แม้จะแค่เสมอตัวเรื่องงบประมาณแต่ชื่อเสียงเพิ่มขึ้นมหาศาล', zh: '✅ 精彩的制作！镜头平滑如丝，非常专业。汽车品牌对此印象极其深刻，甚至聘请你拍摄全球商业广告。你现在成了“动作拍摄专家”。虽然预算刚刚收支平衡，但声誉得到了巨大提升。' }, stats: { competence: 60, ethics: 40, leadership: 45, innovation: 40 } },
            { id: 'B', text: { en: '🚙 The SUV Window Strategy:"I’ll use a handheld gimbal and hang out the window. My friend is a great driver. We can save the $5,000."', th: '🚙 กลยุทธ์หน้าต่าง SUV:"ฉันจะใช้กิมบอลมือถือแล้วโผล่ออกไปนอกหน้าต่าง เพื่อนฉันขับรถเก่งอยู่แล้ว ประหยัดเงิน $5,000 ไปได้เยอะ"', zh: 'SUV窗口策略：“我会用手持云台，身子探出窗外。我朋友车技很好。我们可以省下那5000美元。”' }, consequence: { en: '❌ Disaster & Danger. The wind at 100mph almost ripped the camera out of your hands. The footage is shaky and unusable. The client is furious about the"amateur"approach and fires you. Worse: You almost caused an accident. You are banned from high-end auto shoots.', th: '❌ หายนะและความเสี่ยง! แรงลมตอนวิ่ง 160 กม./ชม. เกือบพัดกล้องหลุดมือคุณไปแล้ว ภาพที่ได้สั่นไหวจนใช้ไม่ได้ ลูกค้าโกรธจัดที่ใช้วิธีแบบ"มือสมัครเล่น"และไล่คุณออก ที่แย่กว่านั้นคือคุณเกือบทำให้เกิดอุบัติเหตุ คุณโดนสั่งแบนจากงานถ่ายรถยนต์ระดับสูงตั้งแต่นั้นมา', zh: '❌ 灾难与危险。100英里/小时的风速几乎把相机从你手中夺走。镜头抖动严重，无法使用。客户对这种“业余”做法大发雷霆，并解雇了你。更糟的是：你差点引发事故。你被禁止拍摄高端汽车。' }, stats: { competence: 10, ethics: 10, leadership: 10, innovation: 20 } },
            { id: 'C', text: { en: '🛸 Drone Alternative:"I’ll spend $2,000 on a high-speed FPV racing drone and pilot. It can keep up with the car better than any crane."', th: '🛸 ทางเลือกโดรน:"ฉันจะใช้เงิน $2,000 ไปกับโดรนแข่ง FPV ความเร็วสูงพร้อมคนบังคับ มันตามรถได้ดีกว่าเครนตัวไหนๆ แน่นอน"', zh: '无人机替代方案：“我会花2000美元买一架高速FPV穿越机，并请个飞手。它比任何摇臂都能更好地跟上车速。”' }, consequence: { en: '✅ Innovation Win! The FPV shots have an energy a chase car could never get. The brand loves the"Modern"feel. You become the go-to guy for hybrid drone/camera work. You saved $3,000 and created a new style.', th: '✅ ชนะด้วยนวัตกรรม! ภาพจากโดรน FPV มีพลังที่ Chase Car ทำไม่ได้ แบรนด์ชอบสไตล์ที่ดู"โมเดิร์น"มาก คุณกลายเป็นคนแรกที่คนนึกถึงถ้าอยากได้งานผสมผสานโดรนกับกล้อง ประหยัดเงินไปได้ $3,000 แถมยังได้สไตล์ใหม่เป็นของตัวเอง', zh: '✅ 创新获胜！FPV镜头拥有一种跟拍车永远无法企及的活力。品牌非常喜欢这种“现代感”。你成了无人机/摄像复合工作的首选。你省下了3000美元，并开创了一种新风格。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 70 } },
            { id: 'D', text: { en: '🛠️ Remote Camera Mount:"I’ll mount 5 GoPro/Action cams on the car body itself. I get all the angles with zero risk to myself."', th: '🛠️ ติดกล้องรีโมท:"ฉันจะติดกล้อง GoPro หรือ Action Cam 5 ตัวไว้ที่ตัวรถเอง จะได้ทุกมุมโดยที่ฉันไม่ต้องเสี่ยงอันตรายอะไรเลย"', zh: '远程相机支架：“我会把5台GoPro/运动相机安装在车身本身。我能拍到所有角度，而且对自己零风险。”' }, consequence: { en: '⚠️ Safe but Boring. The shots are stable, but they lack the"Cinematic"movement of a moving camera. It looks like a YouTube review, not a luxury ad. The client is"okay"with it, but doesn\'t hire you again. You played it too safe.', th: '⚠️ ปลอดภัยแต่จืดชืด! ภาพนิ่งดีทีเดียว แต่ขาดการเคลื่อนไหวที่ดูเป็น"ภาพยนตร์"มันออกมาเหมือนคลิปรีวิวใน YouTube มากกว่าโฆษณาหรูๆ ลูกค้าก็"โอเค"แหละแต่ไม่จ้างคุณซ้ำ คุณเพลย์เซฟเกินไปหน่อย', zh: '⚠️ 安全但无聊。镜头很稳，但缺乏摄像机移动带来的“电影感”。看起来像YouTube上的测评，而不是奢侈品广告。客户觉得“还可以”，但不会再聘请你。你做得太保守了。' }, stats: { competence: 35, ethics: 40, leadership: 30, innovation: 20 } }
        ]
    },

    {
        id: 'pho_011',
        text: {
            en: '🥈 The Underpriced Bid: You find out a competitor won a major hotel contact worth $50,000 by bidding $10,000. You know that at that price, they can\'t afford professional lighting or assistants. Do you reach out to the hotel to warn them or let them learn the hard way?',
            th: '🥈 การประมูลตัดราคา: คุณพบว่าคู่แข่งชนะงานโรงแรมใหญ่มูลค่า $50,000 ไปได้ด้วยการเสนอราคาแค่ $10,000 คุณรู้เลยว่าในราคานั้นเขาไม่มีทางจ่ายค่าไฟหรือจ้างผู้ช่วยระดับโปรได้แน่ๆ คุณจะแจ้งเตือนโรงแรมหรือจะปล่อยให้เขาเรียนรู้ความจริงที่เจ็บปวดเอง?',
            zh: '🥈 低价招标：你发现一个竞争对手通过出价1万美元赢得了一份价值5万美元的大型酒店合同。你很清楚，以那个价格，他们根本付不起专业灯光或助手的费用。你是联系酒店警告他们，还是让他们经历教训？'
        },
        options: [
            { id: 'A', text: { en: '📞 The"Quality Warning":"Call the hotel manager. Explain the technical requirements for a $50k job and why a $10k bid is a red flag. Offer to consult."', th: '📞 คำเตือนเรื่องคุณภาพ:"โทรหาผู้จัดการโรงแรม อธิบายข้อกำหนดทางเทคนิคของงานระดับห้าหมื่นดอลลาร์ และทำไมราคาหมื่นเดียถึงเป็นสัญญาณเตือนภัย เสนอตัวเป็นที่ปรึกษาให้"', zh: '“质量预警”：“给酒店经理打电话。解释价值5万美元的工作对应的技术要求，以及为什么1万美元的出价是个危险信号。提议提供咨询。”' }, consequence: { en: '⚠️ Mixed Results. The manager suspects you are just"jealous."BUT, when the other photographer shows up with a single flash, the manager remembers your call. They fire the competitor and hire you mid-shoot. You saved the hotel, but the industry sees you as"The Snitch."', th: '⚠️ ผลลัพธ์ก้ำกึ่ง! ผู้จัดการสงสัยว่าคุณแค่"อิจฉา"แต่พอช่างภาพคนนั้นโผล่มาพร้อมกับแฟลชตัวเดียว ผู้จัดการก็นึกถึงที่คุณโทรมาทันที เขาไล่คนนั้นออกแล้วจ้างคุณมาทำต่อกลางคัน คุณช่วยโรงแรมไว้ได้แต่คนในวงการมองคุณเป็น"พวกขี้ฟ้อง"', zh: '⚠️ 结果参差不齐。经理怀疑你只是在“嫉妒”。但是，当另一名摄影师只带着一个闪光灯出现时，经理记起了你的电话。他们在拍摄中途解雇了竞争对手并聘请了你。你挽救了酒店，但业界视你为“告密者”。' }, stats: { competence: 40, ethics: 30, leadership: 40, innovation: 10 } },
            { id: 'B', text: { en: '🤫 Silence is Golden:"Let them fail. When the hotel gets bad photos, they will come to me later and I can charge double to fix it."', th: '🤫 ความเงียบคือทองคำ:"ปล่อยให้เขาพลาดไป พอโรงแรมได้รูปห่วยๆ เดี๋ยวเขาก็มาหาฉันเอง ถึงตอนนั้นจะคิดราคาแก้เป็นสองเท่าเลย"', zh: '沉默是金：“让他们失败。当酒店拿到糟糕的照片时，他们以后会来找我，到时我可以收取双倍费用来修复。”' }, consequence: { en: '✅ Strategic Patience. The competitor fails miserably. The hotel is desperate. You step in 2 months later as the"Saviour."You get the $50,000 contract plus a $5,000 rush fee. You kept your dignity and won the market.', th: '✅ ความอดทนเชิงกลยุทธ์! คู่แข่งล้มเหลวไม่เป็นท่า โรงแรมกำลังเข้าตาจน คุณก้าวเข้าไปในฐานะ"ผู้กอบกู้"ในอีก 2 เดือนต่อมา ได้สัญญามูลค่า $50,000 แถมค่าลัดคิวอีก $5,000 คุณรักษาศักดิ์ศรีและเอาชนะตลาดได้สำเร็จ', zh: '✅ 战略性的耐心。竞争对手惨败。酒店走投无路。你2个月后以“救世主”的身份介入。你获得了5万美元的合同，外加5000美元的加急费。你保持了尊严并赢得了市场。' }, stats: { competence: 45, ethics: 35, leadership: 45, innovation: 20 } },
            { id: 'C', text: { en: '📚 Public Education:"Post a blog titled \'What a $50k Architecture shoot actually costs\' breaking down fees. Don\'t name names, just educate."', th: '📚 ให้ความรู้แก่สาธารณะ:"เขียนบล็อกหัวข้อ \'ราคาจริงของงานดีลอาคารถ้าจะจ้างในราคา $50,000\' สรุปค่าใช้จ่ายให้ดูชัดๆ ไม่เอ่ยชื่อใครแต่เน้นให้ความรู้"', zh: '公众教育：“发布一篇名为《一次5万美元的建筑拍摄实际成本是多少》的博客，详细列出各项费用。不点名，只进行科普。”' }, consequence: { en: '✅ Reputation as Expert. The blog goes viral in the hospitality industry. You are seen as the"Authority"on hotel photography. Future clients stop asking for discounts because they understand the value. You raised the tide for everyone.', th: '✅ ชื่อเสียงในฐานะผู้เชี่ยวชาญ! บล็อกนั้นกลายเป็นไวรัลในวงการโรงแรม คุณถูกมองว่าเป็น"เจ้าพ่อ"งานภาพถ่ายโรงแรม ลูกค้ารายใหม่เลิกต่อราคาเพราะเข้าใจในมูลค่าของงานแล้ว คุณช่วยยกระดับวงการให้ทุกคนจริงๆ', zh: '✅ 专家声誉。这篇博客在酒店业疯传。你被视为酒店摄影方面的“权威”。未来的客户不再要求打折，因为他们理解了价值。你为所有人提升了行业地位。' }, stats: { competence: 50, ethics: 50, leadership: 60, innovation: 40 } },
            { id: 'D', text: { en: '🤝 Collaborate with Competitor:"I’ll offer to be their Lighting Lead for a $5,000 fee. I get paid, they don’t fail, and I keep the relationship alive."', th: '🤝 ร่วมมือกับคู่แข่ง:"ลองเสนอตัวเป็นหัวหน้าคุมไฟให้เขาแลกกับเงิน $5,000 ฉันได้เงิน เขาไม่พัง และยังรักษาความสัมพันธ์ไว้ได้ด้วย"', zh: '与竞争对手合作：“我会提议做他们的灯光负责人，收取5000美元费用。我拿到了钱，他们没失败，我也维持了关系。”' }, consequence: { en: '⚠️ Sub-Contractor Trap. You did the hard work, the competitor got the credit and the relationship with the hotel. They hire the competitor again next year for $15k, and you are just their"worker."You helped a price-cutter survive.', th: '⚠️ กับดักซับคอนแทรคเตอร์! คุณทำงานหนักแทบตายแต่คู่แข่งได้หน้าและได้คอนเนคชันกับโรงแรมไปเต็มๆ ปีหน้าเขาก็จ้างคนนั้นอีกในราคา $15,000 ส่วนคุณก็เป็นแค่"ลูกน้อง"ของเขา คุณไปช่วยให้คนตัดราคาอยู่รอดได้ซะงั้น', zh: '⚠️ 分包商陷阱。你干了重活，竞争对手得了荣誉，还和酒店建立了关系。明年他们又以1.5万美元聘请了竞争对手，而你只是他们的“打工人”。你帮一个压价者活了下来。' }, stats: { competence: 45, ethics: 40, leadership: 20, innovation: 20 } }
        ]
    },

    {
        id: 'pho_012',
        text: {
            en: '👰 The Sunset Wedding Rush: It’s the"Golden Hour"at a wedding. You have 15 minutes of perfect light left. The bride wants formal family portraits (at least 20 people), but you know the light is better for the intimate couple shots. What do you prioritize?',
            th: '👰 วินาทีทองของงานแต่ง: ช่วง"Golden Hour"มาถึงแล้ว! คุณเหลือเวลาแค่ 15 นาทีกับแสงที่สวยที่สุด เจ้าสาวอยากถ่ายรูปครอบครัวแบบทางการ (อย่างน้อย 20 คน) แต่คุณรู้ว่าแสงนี้มันเหมาะจะถ่ายรูปคู่บ่าวสาวที่สุด จะเลือกทำอะไรก่อน?',
            zh: '👰 晚霞婚礼突击：婚礼进入了“黄金时刻”。你还有15分钟完美的自然光。新娘想要拍摄正式的家庭人像（至少20人），但你清楚这个光线更适合拍摄亲密的夫妻照。你优先考虑哪个？'
        },
        options: [
            { id: 'A', text: { en: '💍 Couple Shots First:"The couple are the heroes. Family can wait for flash. Take the couple to the cliffside now!"', th: '💍 ถ่ายคู่บ่าวสาวก่อน:"คู่รักคือพระเอกของงานนี้ รูปครอบครัวไว้ถ่ายตอนใช้แฟลชทีหลังได้ รีบพาบ่าวสาวไปที่หน้าผาเดี๋ยวนี้!"', zh: '先拍夫妻照：“这对新人才是主角。拍家人可以用闪光灯等。现在带新人去悬崖边！”' }, consequence: { en: '✅ Portfolio Gold! Those couple shots become the cover of your website and land you 5 more premium weddings. BUT: The Mother-of-the-Bride is angry that she didn\'t get"the good light."You have to use heavy editing to make the family shots look okay.', th: '✅ ภาพประดับพอร์ต! รูปคู่บ่าวสาวนั้นกลายเป็นหน้าปกเว็บคุณและเรียกงานแต่งหรูๆ มาให้อีก 5 งาน แต่: แม่เจ้าสาวเคืองมากที่ไม่ได้"แสงสวยๆ"คุณต้องนั่งแต่งภาพครอบครัวตาแตกเพื่อให้มันออกมาพอดูได้', zh: '✅ 作品集黄金之作！那些夫妻照成了你网站的封面，并为你赢得了另外5场高端婚礼。但是：岳母大人很生气，因为她没赶上“好光线”。你不得不进行大量的后期修图，让家庭照片看起来还行。' }, stats: { competence: 40, ethics: 30, leadership: 35, innovation: 45 } },
            { id: 'B', text: { en: '👨‍👩‍👧 Family Duty:"Listen to the bride. If she wants family shots, I do family shots. I am a service provider first."', th: '👨‍👩‍👧 หน้าที่เพื่อครอบครัว:"ฟังเจ้าสาวสิ ถ้าเขาอยากถ่ายครอบครัว ฉันก็ถ่ายให้ หน้าที่ฉันคือการให้บริการลูกค้ามาก่อนเสมอ"', zh: '尽家庭义务：“听新娘的。如果她想要家庭照，我就拍家庭照。我首先是一个服务提供者。”' }, consequence: { en: '⚠️ Happy Family but Sad Portfolio. You got the family shots, but they look generic. You missed the"Epic"couple shot that sells future weddings. You are seen as"Easy to work with"but not a"Creative Visionary."Your career stays mid-tier.', th: '⚠️ ครอบครัวแฮปปี้แต่พอร์ตน่าเศร้า! คุณได้รูปครอบครัวมาแต่ดูธรรมดามาก คุณพลาดช็อตบ่าวสาวที่ดู"ขลัง"ซึ่งจะช่วยให้คุณรับงานใหม่ได้ในอนาคต คุณถูกมองว่าเป็นช่างภาพที่"คุยง่าย"แต่ไม่ใช่นักสร้างสรรค์ที่มีวิสัยทัศน์ อาชีพคุณเลยหยุดอยู่ที่ระดับกลางๆ', zh: '⚠️ 家庭圆满但作品集平庸。你拍到了家庭照，但看起来普普通通。你错过了能招揽未来婚礼生意的“史诗级”夫妻快拍。你被视为“容易共事”，但不是“创意远见者”。你的职业生涯处于中游水平。' }, stats: { competence: 35, ethics: 45, leadership: 30, innovation: 10 } },
            { id: 'C', text: { en: '⚡ The Speed-Demon Split:"10 mins for family, 5 mins for the couple. I’ll run between locations and shout directions like a drill sergeant."', th: '⚡ สายสปีดแบ่งตัว:"10 นาทีให้ครอบครัว 5 นาทีให้บ่าวสาว ฉันจะวิ่งรอกระหว่างสองที่แล้วตะโกนสั่งยังกับครูฝึกทหาร"', zh: '极速分秒必争：“10分钟拍家人，5分钟拍新人。我会在不同地点穿梭，像个教官一样大声指挥。”' }, consequence: { en: '❌ Stress & Blur. Everyone felt rushed and looked tense in the photos. You missed focus on half the shots because you were sweating and shaking. You tried to do too much and failed at both. Your reputation for"Zen professionalism"is gone.', th: '❌ เครียดจนภาพเบลอ! ทุกคนรู้สึกโดนเร่งและดูเกร็งกันไปหมดในรูป คุณหลุดโฟกัสไปครึ่งนึงเพราะเหงื่อแตกและมือสั่น พยายามทำเยอะเกินไปจนพังทั้งคู่ ชื่อเสียงเรื่อง"ความเป็นมืออาชีพที่นิ่งสยบทุกอย่าง"ของคุณมลายหายไป', zh: '❌ 压力大且模糊。照片里每个人都感觉很仓促，看起来很紧张。因为你在出汗且手抖，一半的镜头都没对上焦。你试图做得太多，结果两边都搞砸了。你那“禅意专业主义”的名声毁于一旦。' }, stats: { competence: 20, ethics: 30, leadership: 10, innovation: 20 } },
            { id: 'D', text: { en: '🎤 The Leadership Move:"Gather everyone. Tell them: \'We have 5 minutes of golden light. Everyone, look at the sun NOW. One epic group shot, then the couple.\'"', th: '🎤 โชว์ภาวะผู้นำ:"เรียกทุกคนมารวมกัน แล้วบอกว่า: \'เรามีเวลา 5 นาทีกับแสงสีทอง ทุกคน หันหน้าหาดวงอาทิตย์เดี๋ยวนี้! ถ่ายรวมกลุ่มสุดอลังการหนึ่งช็อต แล้วค่อยต่อด้วยบ่าวสาว\'"', zh: '展现领导力：“召集所有人，告诉他们：‘我们还有5分钟黄金光线。所有人，现在看太阳。先拍一张壮观的大合照，然后是新人。’”' }, consequence: { en: '✅ Total Victory! You managed the crowd perfectly. You got one stunning group shot that satisfied the bride, and still had 10 minutes for intimate couple shots. You are a Master of Ceremonies as much as a Photographer. You earn a massive tip.', th: '✅ ชนะขาดรอย! คุณจัดการฝูงชนได้เป๊ะมาก ได้รูปกลุ่มสุดว้าวที่เจ้าสาวพอใจ และยังเหลืออีก 10 นาทีไว้ช็อตซึ้งๆ ของบ่าวสาว คุณคือเจ้าพิธีตัวจริงพอๆ กับที่เป็นช่างภาพ ได้ทิปหนักมากงานนี้', zh: '✅ 全面胜利！你完美地管理了人群。你拍到了一张让新娘满意的惊艳大合照，而且还留了10分钟拍摄亲密的夫妻照。你既是一个摄影师，也是一个掌控全场的大师。你赢得了巨额小费。' }, stats: { competence: 55, ethics: 40, leadership: 70, innovation: 35 } }
        ]
    },

    {
        id: 'pho_013',
        text: {
            en: '🎭 The"Free"Event Trap: A local charity wants you to shoot their annual 8-hour fundraiser for free. They promise"connections with donors"but you already have 3 free events this month. Do you accept?',
            th: '🎭 กับดักงานการกุศล: องค์กรการกุศลในพื้นที่ขอให้คุณถ่ายงานระดมทุน 8 ชั่วโมงให้ฟรี พวกเขาสัญญาเรื่อง"คอนเนคชันกับผู้บริจาครายใหญ่"แต่เดือนนี้คุณรับงานฟรีไป 3 งานแล้ว จะทำอย่างไร?',
            zh: '🎭 “免费”活动陷阱：当地一家慈善机构想让你免费为他们为期8小时年度筹款活动拍摄。他们承诺“与捐赠者建立联系”，但你本月已经参加了3场免费活动了。你接受吗？'
        },
        options: [
            { id: 'A', text: { en: '🤝 Strategic Charity:"I’ll do it, but I want a booth to display my work and 5 minutes on stage to introduce myself."', th: '🤝 การกุศลเชิงกลยุทธ์:"ตกลงทำ แต่ขอตั้งบูธโชว์ผลงานและขอเวลา 5 นาทีบนเวทีเพื่อแนะนำตัวเอง"', zh: '战略慈善：“我会做，但我想要一个展位展示我的作品，并有5分钟的台时间来介绍自己。”' }, consequence: { en: '✅ Networking Win! Two major donors hire you for their children’s weddings. You turned a free gig into $15,000 of future work. Leadership and Innovation up.', th: '✅ ชนะด้วยคอนเนคชัน! ผู้บริจาครายใหญ่ 2 คนจ้างคุณไปถ่ายงานแต่งลูกๆ ของเขา คุณเปลี่ยนงานฟรีให้กลายเป็นงานหลักแสนได้สำเร็จ ค่าความเป็นผู้นำและนวัตกรรมเพิ่มขึ้น', zh: '✅ 社交获胜！两名大捐赠者聘请你拍摄他们孩子的婚礼。你把一份免费工作变成了价值1.5万美元的未来项目。领导力和创新指标提升。' }, stats: { competence: 40, ethics: 50, leadership: 50, innovation: 40 } },
            { id: 'B', text: { en: '🚫 Professional Boundary:"I support the cause, but I can only offer a 50% discount. Pro bono slots for this month are full."', th: '🚫 กำหนดขอบเขตอาชีพ:"ฉันสนับสนุนโครงการนี้นะ แต่ให้ส่วนลดได้แค่ 50% งานฟรีสำหรับเดือนนี้เต็มแล้ว"', zh: '职业界限：“我支持这项事业，但我只能提供50%的折扣。本月的公益名额已满。”' }, consequence: { en: '✅ Respect & Revenue. They find the budget and pay you. They realize your time is valuable. You maintain your market value and still support the charity.', th: '✅ ได้ทั้งความเคารพและรายได้! พวกเขาหาเงินมาจ่ายคุณจนได้ เพราะรู้ว่าเวลาของคุณมีค่า คุณรักษาพยุงราคาตลาดไว้ได้และยังได้ช่วยการกุศลด้วย', zh: '✅ 尊重与收入。他们找到了预算并支付了你的费用。他们意识到你的时间很宝贵。你维持了自己的市场价值，同时也支持了慈善事业。' }, stats: { competence: 35, ethics: 40, leadership: 45, innovation: 10 } },
            { id: 'C', text: { en: '🙋 The Enthusiastic Yes:"I love helping! I’ll do it for free and even stay late to edit the highlights for social media tonight."', th: '🙋 ยินดีเป็นที่สุด:"ฉันชอบช่วยงานอยู่แล้ว! จะถ่ายให้ฟรีแถมจะอยู่ดึกเพื่อตัดไฮไลท์ลงโซเชียลให้คืนนี้เลย"', zh: '热情答应：“我很乐意帮忙！我会免费做，甚至今晚加班为社交媒体编辑精彩片段。”' }, consequence: { en: '⚠️ Burnout Warning. You gain"Goodwill,"but you are exhausted and broke. The local business community now sees you as the"Free Guy"and never offers to pay. You are busy but not profitable.', th: '⚠️ สัญญาณเตือนภาวะหมดไฟ! คุณได้"แต้มบุญ"แต่ร่างกายพังและเงินหมด กระเป๋าฉีก สังคมธุรกิจแถวนั้นจำคุณในชื่อ"คนถ่ายฟรี"และไม่มีใครคิดจะจ่ายเงินจ้างคุณเลย คุณยุ่งมากแต่ไม่มีกำไร', zh: '⚠️ 倦怠预警。你赢得了“声誉”，但你已经精疲力竭且破产了。当地商界现在视你为“免费劳动力”，从未提议付钱。你很忙，但没有盈利。' }, stats: { competence: 30, ethics: 60, leadership: 20, innovation: 30 } },
            { id: 'D', text: { en: '🛡️ Barter Move:"I’ll do it for free if the charity features my studio in their quarterly magazine and social media for a year."', th: '🛡️ ข้อเสนอแลกเปลี่ยน:"จะทำฟรีให้ถ้าองค์กรลงโฆษณาสตูดิโอฉันในนิตยสารรายไตรมาสและโซเชียลมีเดียให้เป็นเวลา 1 ปี"', zh: '易货交易：“如果慈善机构在他们的季度杂志和社交媒体上展示我的工作室一年，我就免费拍。”' }, consequence: { en: '✅ Long-Term Marketing. The steady exposure leads to dozens of high-end corporate headshot gigs over the next year. A smart low-cost marketing play.', th: '✅ การตลาดระยะยาว! การได้ปรากฏชื่อสม่ำเสมอทำให้มีงานถ่ายโปรไฟล์ผู้บริหารหรูๆ เข้ามาเพียบในปีถัดไป เป็นการลงทุนการตลาดที่ฉลาดและต้นทุนต่ำ', zh: '✅ 长期营销。持续的曝光在接下来的一年里带来了数十个高端企业头像拍摄项目。这是一个聪明的低成本营销策略。' }, stats: { competence: 35, ethics: 45, leadership: 40, innovation: 50 } }
        ]
    },

    {
        id: 'pho_014',
        text: {
            en: '🚨 The Illegal Shot: A travel blogger wants you to sneak into a high-security rooftop to get a viral sunset photo of Bangkok. They offer $1,000 for one shot. It involves trespassing. Do you take the risk?',
            th: '🚨 ช็อตผิดกฎหมาย: บล็อกเกอร์ท่องเที่ยวอยากให้คุณแอบขึ้นไปบนดาดฟ้าที่มีระบบรักษาความปลอดภัยสูงเพื่อถ่ายรูปพระอาทิตย์ตกในกรุงเทพฯ ให้เป็นไวรัล เขาเสนอเงิน $1,000 ต่อหนึ่งรูป แต่นี่คือการบุกรุกนะ จะเสี่ยงเงไหม?',
            zh: '🚨 违规拍摄：一位旅游博主想让你潜入一个高安保级别的屋顶，拍一张曼谷落日的爆火照片。他们出一张照片1000美元。这涉及非法入侵。你愿意冒险吗？'
        },
        options: [
            { id: 'A', text: { en: '🧗 Technical Risk:"I can do it. I’ve jumped fences before for the shot. The art is worth the danger."', th: '🧗 เสี่ยงเพื่อเทคนิค:"ฉันทำได้ เคยปีนรั้วถ่ายรูปมาแล้ว ศิลปะมีค่าพอกับความเสี่ยง"', zh: '技术风险：“我能行。我以前为了拍到好镜头也翻过围栏。为了艺术，冒点险是值得的。”' }, consequence: { en: '❌ Arrested! Security caught you on camera. You spend the night in jail and lose your camera gear to police seizure. Your reputation is ruined. High-risk, zero reward.', th: '❌ โดนรวบ! กล้องวงจรปิดจับภาพคุณไว้ได้ คุณต้องเข้าคุกหนึ่งคืนและโดนยึดอุปกรณ์กล้องทั้งหมด ชื่อเสียงพังป่นปี้ เสี่ยงสูงแต่ไม่ได้อะไรเลย', zh: '❌ 被捕！安保人员在监控里抓到了你。你在监狱里过了一夜，相机设备也被警方没收了。你的名誉毁了。高风险，零回报。' }, stats: { competence: 10, ethics: 10, leadership: 10, innovation: 30 } },
            { id: 'B', text: { en: '🛡️ Legal Alternative:"I won’t trespass. But I know a legal rooftop bar 2 blocks away with the same angle. I’ll shoot from there instead."', th: '🛡️ ทางเลือกถูกกฎหมาย:"ฉันจะไม่มีวันบุกรุก แต่ฉันรู้จักรูฟท็อปบาร์ที่อยู่ถัดไป 2 บล็อกซึ่งได้มุมเดียวกันเป๊ะ จะไปถ่ายจากพิกัดนั้นแทน"', zh: '合法替代方案：“我不会非法闯入。但我知道两个街区外的一家合法屋顶酒吧，视角是一样的。我会从那里拍。”' }, consequence: { en: '✅ Professional Edge. The blogger loves the shot and is impressed by your local knowledge. You get the $1,000 and stay out of jail. You are a smart pro.', th: '✅ ความเหลื่อมล้ำมืออาชีพ! บล็อกเกอร์ชอบรูปนั้นมากและทึ่งในความกว้างขวางของคุณ คุณได้เงิน $1,000 และไม่ต้องนอนคุก คุณคือมือโปรที่ฉลาดหลักแหลม', zh: '✅ 专业优势。博主非常喜欢这张照片，并对你对当地的了解印象深刻。你拿到了1000美元，而且没进监狱。你是个聪明的专家。' }, stats: { competence: 45, ethics: 50, leadership: 40, innovation: 20 } },
            { id: 'C', text: { en: '🚁 Drone Strategy:"I’ll use a drone. I can get that angle from the public street safely without entering the building."', th: '🚁 กลยุทธ์โดรน:"จะใช้โดรนแทน ฉันสามารถได้มุมนั้นจากถนนสาธารณะได้ปลอดภัยโดยไม่ต้องก้าวเข้าตึกเลย"', zh: '无人机策略：“我会用无人机。我可以在公共街道上安全地获取那个视角，而无需进入大楼。”' }, consequence: { en: '✅ Innovation Win! The angle is actually BETTER than the rooftop. The video goes viral. You get hired for more drone-related travel work. Innovation 100.', th: '✅ ชนะด้วยนวัตกรรม! มุมที่ได้จากโดรนจริงๆ แล้วดีกว่าบนดาดฟ้าเสียอีก วิดีโอกลายเป็นไวรัล คุณได้รับงานเกี่ยวกับการท่องเที่ยวด้วยโดรนเพิ่มเพียบ ค่า ‘นวัตกรรม’ 100', zh: '✅ 创新获胜！这个视角其实比屋顶拍到的还要好。视频疯传。你接到了更多与无人机相关的旅游拍摄工作。创新指标 100。' }, stats: { competence: 40, ethics: 40, leadership: 30, innovation: 60 } },
            { id: 'D', text: { en: '🚫 Strict Refusal:"I don’t work with people who break the law. Find another photographer."', th: '🚫 ปฏิเสธอย่างเด็ดขาด:"ฉันไม่ทำงานกับคนที่ทำผิดกฎหมาย ไปหาคนอื่นเถอะ"', zh: '严词拒绝：“我不和违法的人合作。找别的摄影师吧。”' }, consequence: { en: '⚠️ Safe but Isolated. You kept your record clean, but the blogger tells their community you are"difficult"and"not fun."You lose some social marketing points but keep your integrity.', th: '⚠️ ปลอดภัยแต่โดดเดี่ยว! คุณรักษาประวัติให้ขาวสะอาดได้ แต่บล็อกเกอร์คนนั้นไปโพนทะนาว่าคุณ"เรื่องเยอะ"และ"ไม่สนุก"เสียคะแนนการตลาดโซเชียลไปบ้างแต่รักษาจริยธรรมไว้ได้', zh: '⚠️ 安全但孤立。你保持了清白记录，但博主在圈子里说你“难相处”且“无趣”。你失去了一些社交营销分数，但保持了正直。' }, stats: { competence: 30, ethics: 70, leadership: 40, innovation: 10 } }
        ]
    },

    {
        id: 'pho_015',
        text: {
            en: '🎨 The AI Threat: A long-term corporate client tells you they are cutting your contract because they can now generate their stock photos and office portraits using AI for $10 a month. What do you do?',
            th: '🎨 ภัยคุกคามจาก AI: ลูกค้าบริษัทขาประจำบอกว่าจะยกเลิกสัญญาจ้างคุณ เพราะตอนนี้เขาสามารถใช้ AI สร้างรูปสต็อกและรูปพนักงานได้ในราคาแค่เดือนละ $10 คุณจะรับมือยังไง?',
            zh: '🎨 AI威胁：一位长期企业客户告诉你，他们要终止与你的合同，因为他们现在每月只需花10美元就能使用AI生成图库照片和办公室人像。你会怎么做？'
        },
        options: [
            { id: 'A', text: { en: '🛠️ Master the AI:"If you can\'t beat them, join them. I’ll offer to curate and edit their AI results for a premium consulting fee."', th: '🛠️ เซียน AI:"ถ้าสู้ไม่ได้ก็เข้าร่วมเลย! ฉันจะเสนอตัวเป็นคนคัดเลือกและแต่งรูปจาก AI ให้เขาแทน โดยคิดค่าปรึกษาระดับพรีเมียม"', zh: '精通AI：“如果打不过，就加入。我会提议为他们筛选和编辑AI生成的结果，并收取高端咨询费。”' }, consequence: { en: '✅ Pivot Success! You spend less time shooting and more time directing. Your business becomes highly profitable and tech-forward. Innovation 100.', th: '✅ เปลี่ยนวิกฤตเป็นโอกาส! คุณใช้เวลาถ่ายภาพน้อยลงแต่ใช้เวลากำกับงานมากขึ้น ธุรกิจของคุณมีกำไรมหาศาลและดูล้ำหน้ามาก ค่า ‘นวัตกรรม’ 100', zh: '✅ 转型成功！你花更少的时间拍摄，花更多的时间指导。你的业务变得利润丰厚且技术领先。创新指标 100。' }, stats: { competence: 40, ethics: 30, leadership: 50, innovation: 70 } },
            { id: 'B', text: { en: '📸 Double Down on Human:"Explain the \'Soul factor.\' Show them why AI portraits look dead and why human connectivity wins sales."', th: '📸 เน้นความเป็นมนุษย์:"อธิบายเรื่อง \'ปัจจัยด้านจิตวิญญาณ\' โชว์ให้เขาเห็นว่าทำไมรูป AI ถึงดูไร้ชีวิตชีวา และทำไมการเชื่อมโยงถึงความจริงจะช่วยกระตุ้นยอดขายได้มากกว่า"', zh: '加倍下注于人工：“解释‘灵魂因素’。向他们展示为什么AI肖像看起来死气沉沉，以及为什么人类的连接感能赢得销售。”' }, consequence: { en: '✅ Quality Win. The client realizes the AI faces look"uncanny"and return to you. You are now the"Authenticity Specialist."Ethics and Competence up.', th: '✅ ชนะด้วยคุณภาพ! ลูกค้าตระหนักว่าหน้าจาก AI มันดู"แปลกประหลาด"เกินไปจนต้องกลับมาหาคุณ ตอนนี้คุณกลายเป็น"ผู้เชี่ยวชาญด้านความสมจริง"', zh: '✅ 品质取胜。客户意识到AI生成的面孔看起来有“恐怖谷效应”，于是重新找你。你现在成了“真实感专家”。职业道德和能力指标提升。' }, stats: { competence: 55, ethics: 50, leadership: 40, innovation: 20 } },
            { id: 'C', text: { en: '📉 Lower Your Rates:"I’ll match the AI price! I’ll work for $50 a shoot just to keep the client."', th: '📉 ลดราคาลงสู้:"จะลดราคาให้เท่า AI เลย! จะยอมถ่ายให้ในราคาแค่ $50 เพื่อรักษาลูกค้าไว้"', zh: '降低费率：“我跟AI一个价！为了留住客户，我一次拍摄只收50美元。”' }, consequence: { en: '❌ Financial Suicide. You can’t pay your studio rent on $50. You work yourself to death for no profit. The client still respects you less because you are"cheap."Worst of both worlds.', th: '❌ ฆ่าตัวตายทางการเงิน! คุณไม่สามารถจ่ายค่าเช่าสตูดิโอด้วยเงินแค่ $50 ได้หรอก ต้องทำงานหนักเจียนตายโดยไม่มีกำไร แถมลูกค้ายังมองคุณไร้ค่าเพราะราคา"ถูก"เกินไปอีก พังทั้งขึ้นทั้งล่อง', zh: '❌ 经济自杀。靠50美元付不起工作室房租。你没日没夜地干活却毫无利润。客户依然不怎么尊重你，因为你很“廉价”。两头落空。' }, stats: { competence: 20, ethics: 10, leadership: 10, innovation: 10 } },
            { id: 'D', text: { en: '🎭 High-End Pivot:"Leave the corporate world. Pivot to luxury weddings and fine art where AI can’t replace the experience."', th: '🎭 ขยับสู่ระดับบน:"ออกจากโลกธุรกิจซะ แล้วหันไปทำตลาดงานแต่งหรูหราหรืองานวิจิตรศิลป์ที่ AI ไม่สามารถมาแทนที่ประสบการณ์จริงได้"', zh: '高端转型：“离开企业界。转向AI无法替代体验的奢华婚礼和美术摄影。”' }, consequence: { en: '✅ New Horizons. You struggle for 6 months, then land a $20,000 gala. You are now in a higher tax bracket. Sometimes a threat is a push toward greatness.', th: '✅ เปิดโลกใหม่! คุณอาจจะลำบากในช่วง 6 เดือนแรก แต่แล้วก็ได้งานกาล่าราคาเจ็ดแสนบาท ตอนนี้คุณก้าวเข้าสู่กลุ่มรายได้สูงแล้ว บางครั้งภัยคุกคามก็คือแรงผลักดันไปสู่ความยิ่งใหญ่', zh: '✅ 新地平线。你挣扎了6个月，然后接到了一份2万美元的晚会单子。你现在的纳税等级更高了。有时，威胁正是迈向卓越的推力。' }, stats: { competence: 40, ethics: 30, leadership: 60, innovation: 40 } }
        ]
    }, // End of Section 1

    // SECTION 2: STUDIO EXPANSION & PROFESSIONAL CHALLENGES (Questions 16-25)

    {
        id: 'pho_016',
        text: {
            en: '👥 The Assistant\'s Blunder: You hired an assistant for a $5,000 corporate shoot. They forgot to bring the backup batteries. You are halfway through the shoot and your main battery is at 10%. The CEO is busy and annoyed. What do you do?',
            th: '👥 ความผิดพลาดของผู้ช่วย: คุณจ้างผู้ช่วยสำหรับงานถ่ายภาพองค์กรราคา $5,000 แต่เขาลืมนำแบตเตอรี่สำรองมา คุณถ่ายไปได้ครึ่งทางแล้วและแบตเตอรี่หลักเหลือ 10% CEO กำลังยุ่งและหงุดหงิด คุณจะทำอย่างไร?',
            zh: '👥 助手的失误：你为一个5000美元的企业拍摄聘请了一名助手。他们忘了带备用电池。拍摄进行了一半，你的主电池只剩10%。CEO很忙且很恼火。你会怎么做？'
        },
        options: [
            { id: 'A', text: { en: '😡 Public Blame: "I can\'t believe this! My assistant messed up. I need 20 minutes to run to the store." (Throw them under the bus)', th: '😡 โทษผู้ช่วยต่อหน้าทุกคน: "ไม่อยากเชื่อเลย! ผู้ช่วยผมทำพลาด ผมขอเวลา 20 นาทีวิงไปซื้อของหน่อย" (โยนความผิดให้ผู้ช่วย)', zh: '😡 公开指责：“简直不敢相信！我的助手搞砸了。我需要20分钟跑去商店。”（把责任推给助手）' }, consequence: { en: '❌ Professional Suicide. The CEO fires you on the spot for lack of leadership. "If you hired them, it\'s your fault." You lose the $5,000 and the client. Leadership -50.', th: '❌ ฆ่าตัวตายทางอาชีพ CEO ไล่คุณออกทันทีเพราะขาดภาวะผู้นำ "ถ้าคุณจ้างเขา มันก็เป็นความผิดของคุณ" คุณเสียเงิน $5,000 และเสียลูกค้า ค่าความเป็นผู้นำ -50', zh: '❌ 职业自杀。CEO因缺乏领导力当场解雇你。“如果你雇了他们，那就是你的错。”你损失了5000美元和客户。领导力 -50。' }, stats: { competence: 20, ethics: 10, leadership: -50, innovation: 10 } },
            { id: 'B', text: { en: '🤫 The Silent MacGyver: "Switch to single-shot mode, turn off image preview, lower screen brightness. Shoot efficiently. Don\'t tell the client."', th: '🤫 แก้ปัญหาเงียบๆ: "เปลี่ยนเป็นโหมดถ่ายทีละภาพ ปิดการดูรูปย้อนหลัง ลดแสงหน้าจอ ถ่ายอย่างประหยัดที่สุด ห้ามบอกลูกค้า"', zh: '🤫 沉默的马盖先：“切换到单拍模式，关闭图像预览，降低屏幕亮度。高效拍摄。不要告诉客户。”' }, consequence: { en: '✅ Stressful Victory. You sweat bullets but finish the shoot with 1% battery left. The client is happy. You realized you need a checklist system for assistants. Competence +40.', th: '✅ ชัยชนะที่เครียดจัด คุณเหงื่อตกแต่ถ่ายจบโดยเหลือแบต 1% ลูกค้าแฮปปี้ คุณตระหนักว่าต้องมีระบบเช็คลิสต์สำหรับผู้ช่วยแล้ว ค่าความเชี่ยวชาญ +40', zh: '✅ 充满压力的胜利。你汗流浃背，但在电池剩余1%时完成了拍摄。客户很高兴。你意识到你需要为助手建立检查清单系统。能力 +40。' }, stats: { competence: 40, ethics: 30, leadership: 30, innovation: 30 } },
            { id: 'C', text: { en: '🤝 Fall on the Sword: "Apologize to the CEO. \'We possess a technical hurdle. Let\'s take a 15-min coffee break on me while I sort this.\' Send assistant to buy batteries."', th: '🤝 ยอมรับผิด: "ขอโทษ CEO \'เรามีปัญหาทางเทคนิคเล็กน้อย ขอเชิญพักดื่มกาแฟ 15 นาที เดี๋ยวผมจัดการให้ครับ\' แล้วรีบส่งผู้ช่วยไปซื้อแบต"', zh: '🤝 承担责任：“向CEO道歉。‘我们遇到了技术障碍。请大家喝15分钟咖啡，我来处理。’派助手去买电池。”' }, consequence: { en: '✅ Respect Earned. The CEO appreciates the honesty and the coffee. The break actually relaxes the stiff board members. Photos turn out better. You lose $50 on coffee but keep the client.', th: '✅ ได้รับความเคารพ CEO ชื่นชมความซื่อสัตย์และกาแฟ ช่วงพักช่วยให้บอร์ดบริหารที่เกร็งๆ ผ่อนคลายลง รูปออกมาดีขึ้น คุณเสียค่ากาแฟ $50 แต่รักษาลูกค้าไว้ได้', zh: '✅ 赢得尊重。CEO很欣赏你的诚实和咖啡。休息实际上让僵硬的董事会成员放松了下来。照片效果更好。你损失了50美元咖啡钱，但留住了客户。' }, stats: { competence: 35, ethics: 45, leadership: 50, innovation: 20 } },
            { id: 'D', text: { en: '📱 iPhone Backup: "Battery is dead. Let\'s finish the shoot with my iPhone 15 Pro Max. It\'s \'modern and authentic\'."', th: '📱 ใช้มือถือถ่ายต่อ: "แบตหมดแล้ว มาถ่ายต่อด้วย iPhone 15 Pro Max ของผมกันดีกว่า มันดู \'ทันสมัยและเรียล\' ดีนะ"', zh: '📱 iPhone备选：“电池没电了。让我们用我的iPhone 15 Pro Max完成拍摄。这很‘现代且真实’。”' }, consequence: { en: '💀 Laughing Stock. The CEO laughs at you. "I didn\'t pay $5k for phone pics." You are asked to leave. Reputation ruined.', th: '💀 ตัวตลกของงาน CEO หัวเราะใส่คุณ "ผมไม่ได้จ่าย $5k เพื่อรูปจากมือถือนะ" คุณโดนเชิญกลับ ชื่อเสียงพังยับ', zh: '💀 笑柄。CEO嘲笑你。“我付5000美元不是为了手机照片。”你被请离。名誉扫地。' }, stats: { competence: -20, ethics: 20, leadership: 10, innovation: -10 } }
        ]
    },

    {
        id: 'pho_017',
        text: {
            en: '📈 The Viral Trend: A new photography trend ("Neon Noir") is exploding on TikTok. Everyone wants it. It\'s not your style (you prefer natural light), but clients are asking for it. Do you adapt?',
            th: '📈 กระแสไวรัล: เทรนด์ถ่ายภาพใหม่ ("Neon Noir") กำลังมาแรงใน TikTok ทุกคนอยากได้แบบนี้ มันไม่ใช่สไตล์คุณ (คุณชอบแสงธรรมชาติ) แต่ลูกค้าเรียกร้อง คุณจะปรับตัวไหม?',
            zh: '📈 病毒式趋势：一种新的摄影趋势（“霓虹黑色”）在TikTok上爆发。每个人都想要它。这不是你的风格（你更喜欢自然光），但客户在要求。你会适应吗？'
        },
        options: [
            { id: 'A', text: { en: '🌊 Ride the Wave: "Buy the gels, watch the tutorials. I\'m a Neon Noir photographer now! Capture the revenue while it lasts."', th: '🌊 เกาะกระแส: "ซื้อเจลสี ดูคลิปสอน ตอนนี้ฉันคือช่างภาพ Neon Noir แล้ว! กอบโกยเงินตอนที่เทรนด์ยังอยู่"', zh: '🌊 顺势而为：“买滤色片，看教程。我现在是霓虹黑色摄影师了！趁热打铁赚取收入。”' }, consequence: { en: '💰 Quick Cash, Brand Confusion. You make $10,000 in two months. But your portfolio now looks messy. When the trend dies in 3 months, you are stuck with gear you don\'t use and clients who only want the fad.', th: '💰 เงินไวแต่แบรนด์งง คุณทำเงิน $10,000 ในสองเดือน แต่พอร์ตคุณดูเละเทะ พอเทรนด์จบใน 3 เดือน คุณติดอยู่กับอุปกรณ์ที่ไม่ได้ใช้และลูกค้าที่ต้องการแค่กระแส', zh: '💰 快钱，品牌混淆。你在两个月内赚了1万美元。但你的作品集现在看起来很乱。当3个月后趋势消退时，你只剩下一堆不用的器材和只想要赶时髦的客户。' }, stats: { competence: 30, ethics: 30, leadership: 20, innovation: 40 } },
            { id: 'B', text: { en: '🚫 Stay True: "I am a Natural Light specialist. I simply say no to these requests. My style is timeless."', th: '🚫 ยึดมั่นในจุดยืน: "ฉันคือผู้เชี่ยวชาญแสงธรรมชาติ ฉันปฏิเสธคำขอพวกนี้ สไตล์ของฉันอยู่เหนือกาลเวลา"', zh: '🚫 保持真实：“我是自然光专家。我直接拒绝这些请求。我的风格是永恒的。”' }, consequence: { en: '📉 Short-term Dip, Long-term Respect. You lose some hype, but your core clients trust you more. 5 years later, your work is still valid, while the Neon trend looks dated. Stability win.', th: '📉 รายได้ลดช่วงสั้นแต่ได้ความเคารพระยะยาว คุณเสียกระแสไปบ้าง แต่ลูกค้าหลักเชื่อใจคุณมากขึ้น 5 ปีต่อมางานคุณยังดูดี ในขณะที่เทรนด์ Neon ดูเชยไปแล้ว ชนะด้วยความมั่นคง', zh: '📉 短期下滑，长期尊重。你失去了一些热度，但核心客户更信任你。5年后，你的作品依然经得起考验，而霓虹趋势看起来已经过时。稳定性胜利。' }, stats: { competence: 45, ethics: 40, leadership: 40, innovation: 10 } },
            { id: 'C', text: { en: '🧠 The Fusion: "Integrate elements of the trend into my style. \'Natural Light Noir.\' Evolve my art without selling out."', th: '🧠 ผสมผสาน: "นำองค์ประกอบของเทรนด์มาใส่ในสไตล์ฉัน \'Natural Light Noir\' พัฒนางานศิลป์โดยไม่สูญเสียตัวตน"', zh: '🧠 融合：“将趋势元素融入我的风格。‘自然光黑色’。进化我的艺术而不出卖灵魂。”' }, consequence: { en: '✅ Innovation Master. You create a unique sub-genre. It helps your work stand out even more. You get booked for a magazine spread on "Modern Photography." Best of both worlds.', th: '✅ เจ้าแห่งนวัตกรรม คุณสร้างแนวทางย่อยที่ไม่เหมือนใคร มันช่วยให้งานคุณโดดเด่นขึ้นไปอีก คุณได้รับจ้างให้ถ่ายลงนิตยสารในหัวข้อ "การถ่ายภาพร่วมสมัย" ดีที่สุดทั้งสองทาง', zh: '✅ 创新大师。你创造了一个独特的子流派。这有助于你的作品更加脱颖而出。你被预订拍摄关于“现代摄影”的杂志专栏。两全其美。' }, stats: { competence: 50, ethics: 40, leadership: 45, innovation: 60 } },
            { id: 'D', text: { en: '🤝 Outsource: "Partner with a young photographer who loves this style. I take the booking, keep 20%, and let them shoot it."', th: '🤝 จ้างคนอื่น: "ร่วมมือกับช่างภาพรุ่นใหม่ที่ชอบสไตล์นี้ ฉันรับงานมา หัก 20% แล้วให้เขาถ่าย"', zh: '🤝 外包：“与一位喜欢这种风格的年轻摄影师合作。我接单，保留20%，让他们去拍。”' }, consequence: { en: '💼 Agency Mode. You start transitioning from photographer to "Studio Manager." It\'s good passive income, but you lose touch with the camera. Are you an artist or a boss?', th: '💼 โหมดเอเจนซี่ คุณเริ่มเปลี่ยนจากช่างภาพเป็น "ผู้จัดการสตูดิโอ" มันเป็นรายได้เสริมที่ดี แต่คุณเริ่มห่างเหินจากกล้อง คุณจะเป็นศิลปินหรือเจ้านาย?', zh: '💼 代理模式。你开始从摄影师向“工作室经理”转型。这是不错的被动收入，但你失去了与相机的接触。你是艺术家还是老板？' }, stats: { competence: 30, ethics: 35, leadership: 50, innovation: 30 } }
        ]
    },

    {
        id: 'pho_018',
        text: {
            en: '🏢 The Studio Lease: You are currently working from a home office. A perfect storefront studio in a trendy arts district becomes available for $2,500/month. It\'s a stretch for your budget, but could attract walk-in clients. Do you sign the 3-year lease?',
            th: '🏢 สัญญาเช่าสตูดิโอ: ตอนนี้คุณทำงานจากโฮมออฟฟิศ มีสตูดิโอหน้าร้านทำเลทองในย่านศิลปะว่างให้เช่าในราคา $2,500/เดือน มันเกินงบคุณไปหน่อย แต่น่าจะดึงลูกค้าขาจรได้ คุณจะเซ็นสัญญา 3 ปีไหม?',
            zh: '🏢 工作室租赁：你目前在家庭办公室工作。一个位于时尚艺术区的完美临街工作室空出来了，租金为每月2500美元。这对你的预算来说很勉强，但可以吸引散客。你会签这份3年租约吗？'
        },
        options: [
            { id: 'A', text: { en: '📝 Sign It: "High risk, high reward. A storefront signals legitimate business. I\'ll raise my prices to cover the rent."', th: '📝 เซ็นเลย: "เสี่ยงสูง ผลตอบแทนสูง หน้าร้านแสดงถึงธุรกิจที่น่าเชื่อถือ ฉันจะขึ้นราคาเพื่อครอบคลุมค่าเช่า"', zh: '📝 签了：“高风险，高回报。店面标志着正规业务。我会提高价格来支付租金。”' }, consequence: { en: '📈 Growth & Stress. Your visibility explodes. Walk-in headshots cover the rent. BUT you now have overhead stress every month. You can\'t take a vacation because "the rent eats while you sleep." You are a serious business now.', th: '📈 เติบโตพร้อมความเครียด การมองเห็นของคุณพุ่งกระฉูด รายได้จากลูกค้ารูปติดบัตรพอจ่ายค่าเช่า แต่คุณต้องเครียดเรื่องรายจ่ายทุกเดือน ลาพักร้อนไม่ได้เพราะ "ค่าเช่ากินเงินตอนคุณหลับ" ตอนนี้คุณเป็นธุรกิจเต็มตัวแล้ว', zh: '📈 增长与压力。你的知名度爆发。散客大头照收入覆盖了租金。但你现在每个月都有开销压力。你不能休假，因为“你睡觉时租金也在吃钱”。你现在是个正经生意人了。' }, stats: { competence: 40, ethics: 30, leadership: 45, innovation: 30 } },
            { id: 'B', text: { en: '🏡 Stay Home: "Overhead kills creativity. I\'ll keep my expenses low and invest that $2,500/month in digital marketing instead."', th: '🏡 อยู่บ้านต่อ: "รายจ่ายฆ่าความคิดสร้างสรรค์ ฉันจะประหยัดค่าใช้จ่ายแล้วเอาเงิน $2,500/เดือนไปลงโฆษณาออนไลน์แทน"', zh: '🏡 留在家里的：“开销扼杀创造力。我会保持低开支，把每月2500美元投资于数字营销。”' }, consequence: { en: '💰 Profit King. You don\'t have a storefront, but your website is #1 on Google. You keep 80% of your earnings as profit. You buy a house while the studio-renters are broke. Smart financial move.', th: '💰 ราชาแห่งกำไร คุณไม่มีหน้าร้าน แต่เว็บคุณอยู่อันดับ 1 ใน Google คุณเก็บกำไร 80% เข้ากระเป๋า คุณซื้อบ้านได้ในขณะที่คนเช่าสตูดิโอกำลังถังแตก การเงินฉลาดมาก', zh: '💰 利润之王。你没有店面，但你的网站在Google上排名第一。你保留80%的收入作为利润。当租赁工作室的人破产时，你买了房子。聪明的财务举措。' }, stats: { competence: 45, ethics: 35, leadership: 40, innovation: 20 } },
            { id: 'C', text: { en: '🤝 Co-Op Studio: "Find 3 other creatives (videographer, makeup artist, graphic designer) to split the space. $625/month each."', th: '🤝 แชร์สตูดิโอ: "หาครีเอทีฟอีก 3 คน (ช่างวิดีโอ, ช่างแต่งหน้า, กราฟิก) มาแชร์พื้นที่กัน ตกคนละ $625/เดือน"', zh: '🤝 合作工作室：“找另外3位创意人士（摄像师、化妆师、平面设计师）分摊空间。每人每月625美元。”' }, consequence: { en: '✅ Community Win. You get the space for cheap AND constant referrals from your flatmates. "Oh, you need a logo? Talk to Jim in the corner." An ecosystem of success.', th: '✅ ชนะพลังชุมชน คุณได้ที่ราคาถูก แถมได้งานแนะนำจากเพื่อนร่วมห้องตลอด "อ๋อ อยากทำโลโก้เหรอ? คุยกับจิมมุมโน้นเลย" ระบบนิเวศแห่งความสำเร็จ', zh: '✅ 社区共赢。你便宜拿到了空间，还能从室友那里获得持续的推荐。“哦，你需要设计logo？找角落里的Jim。”一个成功的生态系统。' }, stats: { competence: 45, ethics: 40, leadership: 55, innovation: 45 } },
            { id: 'D', text: { en: '🏭 Rent-as-Needed: "I\'ll join a Peerspace network. Rent premium studios strictly when clients pay for it. Variable cost vs Fixed cost."', th: '🏭 เช่าเมื่อจำเป็น: "สมัครสมาชิกเครือข่าย Peerspace เช่าไสตูดิโอหรูเฉพาะตอนลูกค้าจ่ายเท่านั้น ต้นทุนแปรผัน vs ต้นทุนคงที่"', zh: '🏭 按需租赁：“加入Peerspace网络。只在客户付费时租用高端工作室。变动成本 vs 固定成本。”' }, consequence: { en: '⚖️ Flexible but Homeless. Great for cash flow, but you lack a "base." You haul gear around constantly. Clients are confused why your location changes every shoot. Good for freelancers, bad for branding.', th: '⚖️ ยืดหยุ่นแต่ไร้บ้าน ดีต่อกระแสเงินสด แต่คุณขาด "ฐานทัพ" ต้องขนของไปมาตลอด ลูกค้างงว่าทำไมสถานที่เปลี่ยนทุกครั้ง เหมาะกับฟรีแลนซ์แต่แย่สำหรับการสร้างแบรนด์', zh: '⚖️ 灵活但无家可归。对现金流很好，但你缺乏一个“基地”。你不断地搬运器材。客户很困惑为什么你每次拍摄地点都变。适合自由职业者，不利于品牌建设。' }, stats: { competence: 35, ethics: 30, leadership: 30, innovation: 35 } }
        ]
    },

    {
        id: 'pho_019',
        text: {
            en: '🎯 The Niche Pivot: You are a generalist shooting everything. A mentor tells you: "Riches are in the niches." You notice you are good at "Pet Photography." Do you drop everything else to focus ONLY on luxury pet portraits?',
            th: '🎯 การเจาะตลาดเฉพาะกลุ่ม: คุณเป็นช่างภาพจับฉ่ายถ่ายทุกอย่าง เมนเทอร์บอกว่า "ขุมทรัพย์อยู่ในนิช" คุณสังเกตว่าคุณถนัด "ถ่ายภาพสัตว์เลี้ยง" คุณจะทิ้งอย่างอื่นเพื่อโฟกัสแค่การถ่ายภาพสัตว์เลี้ยงหรูหราไหม?',
            zh: '🎯 细分市场转型：你是一个什么都拍的通才。一位导师告诉你：“财富在利基市场。”你发现自己擅长“宠物摄影”。你会放弃其他一切，只专注于高端宠物肖像吗？'
        },
        options: [
            { id: 'A', text: { en: '🐶 All-In Doggo: "Rebrand to \'The Posh Paw.\' No weddings, no corporate. Only dogs in tuxedos. Charge $500/session."', th: '🐶 ทุ่มสุดตัวเพื่อน้องหมา: "รีแบรนด์เป็น \'The Posh Paw\' ไม่รับงานแต่ง ไม่รับงานองค์กร รับแต่หมาใส่สูทเท่านั้น คิด $500/ครั้ง"', zh: '🐶 全力投入狗狗：“重塑品牌为‘The Posh Paw’。不拍婚礼，不拍企业。只拍穿燕尾服的狗。每场收费500美元。”' }, consequence: { en: '✅ Expert Status. It\'s scary for 3 months, then you become THE pet photographer. Wealthy owners fly you around the country. You work fewer hours for more money. Generalists compete on price; specialists compete on value.', th: '✅ สถานะผู้เชี่ยวชาญ น่ากลัวอยู่ 3 เดือน จากนั้นคุณกลายเป็น "ช่างภาพสัตว์เลี้ยงอันดับหนึ่ง" เจ้าของรวยๆ บินพาคุณไปถ่ายทั่วประเทศ ทำงานน้อยลงแต่ได้เงินมากขึ้น คนจับฉ่ายแข่งกันที่ราคา คนเชี่ยวชาญแข่งกันที่มูลค่า', zh: '✅ 专家地位。头3个月很吓人，然后你成了最好的宠物摄影师。富有的主人飞遍全国请你。你工作时间更少，赚得更多。通才拼价格；专才拼价值。' }, stats: { competence: 50, ethics: 40, leadership: 35, innovation: 45 } },
            { id: 'B', text: { en: '🤹 Maintain Balance: "I\'ll add a \'Pet\' tab to my website. I can\'t afford to lose the wedding revenue. I\'ll do both."', th: '🤹 รักษาสมดุล: "เพิ่มแท็บ \'สัตว์เลี้ยง\' ในเว็บ ฉันเสียรายได้จากงานแต่งไม่ได้หรอก ทำควบสองอย่างไปเลย"', zh: '🤹 保持平衡：“我会在网站上加一个‘宠物’标签。我承担不起失去婚礼收入的代价。我两个都做。”' }, consequence: { en: '⚠️ Brand Dilution. You confuse clients. "Are you a wedding photographer or a dog photographer?" You get some pet gigs, but low-paying ones. You remain a busy generalist. Jack of all trades, master of none.', th: '⚠️ แบรนด์เจือจาง ลูกค้างง "ตกลงคุณถ่ายงานแต่งหรือถ่ายหมา?" คุณได้งานสัตว์เลี้ยงบ้างแต่ราคาถูก คุณยังคงเป็นเป็ดที่ยุ่งตลอดเวลา รู้ทุกอย่างแต่ไม่เก่งสักอย่าง', zh: '⚠️ 品牌稀释。你让客户困惑。“你是婚礼摄影师还是宠物摄影师？”你接到了一些宠物活，但报酬很低。你仍然是一个忙碌的通才。样样通，样样松。' }, stats: { competence: 35, ethics: 30, leadership: 25, innovation: 20 } },
            { id: 'C', text: { en: '🚀 Spin-Off Brand: "Create a separate website and Instagram for the pet business. Keep the main brand for weddings. Run two distinct businesses."', th: '🚀 แบรนด์ลูก: "สร้างเว็บและไอจีแยกสำหรับธุรกิจสัตว์เลี้ยง เก็บแบรนด์หลักไว้งานแต่ง รันสองธุรกิจแยกกันไปเลย"', zh: '🚀 分拆品牌：“为宠物业务创建一个单独的网站和Instagram。婚礼保留主品牌。经营两个截然不同的业务。”' }, consequence: { en: '✅ Extra Work, Double Revenue. It\'s exhausting to manage two brands, but you capture both markets. Eventually, the pet brand outgrows the main one and you can retire the wedding side safely.', th: '✅ งานเพิ่ม รายได้คูณสอง เหนื่อยหน่อยที่ต้องคุมสองแบรนด์ แต่คุณกินรวบทั้งสองตลาด ในที่สุดแบรนด์สัตว์เลี้ยงก็โตแซงแบรนด์หลัก และคุณก็เกษียณจากงานแต่งได้อย่างปลอดภัย', zh: '✅ 额外工作，双倍收入。管理两个品牌很累，但你占据了两个市场。最终，宠物品牌超过了主品牌，你可以安全地退休不再拍婚礼。' }, stats: { competence: 55, ethics: 40, leadership: 50, innovation: 40 } },
            { id: 'D', text: { en: '🚫 Ignore the Niche: "Pets are a fad. Weddings are forever. I\'ll stick to the safe bet."', th: '🚫 เมินนิช: "สัตว์เลี้ยงแค่กระแส งานแต่งสิของจริง ฉันจะยึดกับของตายดีกว่า"', zh: '🚫 忽略利基市场：“宠物只是一时的狂热。婚礼才是永恒的。我会坚持稳妥的选择。”' }, consequence: { en: '📉 Stagnation. You keep shooting weddings, but the market gets saturated. Your rates flatline. Meanwhile, the "Pet Photographer" in your town just bought a Porsche. You played it too safe.', th: '📉 หยุดนิ่ง คุณถ่ายงานแต่งต่อไป แต่ตลาดเริ่มอิ่มตัว ค่าตัวคุณนิ่งสนิท ในขณะที่ "ช่างภาพสัตว์เลี้ยง" แถวบ้านเพิ่งถอยปอร์เช่ คุณเพลย์เซฟเกินไป', zh: '📉 停滞。你继续拍婚礼，但市场变得饱和。你的费率持平。与此同时，你镇上的“宠物摄影师”刚买了辆保时捷。你做得太保守了。' }, stats: { competence: 30, ethics: 30, leadership: 20, innovation: 10 } }
        ]
    },

    {
        id: 'pho_020',
        text: {
            en: '😭 The Unhappy Bride: A bride calls you in tears 2 weeks after delivering the gallery. She hates the photos. "I look fat, the lighting is weird, and you missed my grandmother." You know the photos are good, but she is emotional. What is your policy?',
            th: '😭 เจ้าสาวขี้แย: เจ้าสาวโทรหาคุณทั้งน้ำตา 2 สัปดาห์หลังส่งงาน เธอกลียดรูป "ฉันดูอ้วน แสงก็ประหลาด แถมคุณไม่ได้ถ่ายยายฉันด้วย" คุณรู้ว่ารูปมันดี แต่เธอกำลังใส่อารมณ์ นโยบายของคุณคือ?',
            zh: '😭 不快乐的新娘：交付照片两周后，一位新娘哭着给你打电话。她讨厌这些照片。“我看起来很胖，光线很奇怪，而且你漏拍了我祖母。”你知道照片很好，但她很情绪化。你的政策是什么？'
        },
        options: [
            { id: 'A', text: { en: '🛡️ Contract Defense: "I executed the contract professionally. The technical specs are met. I\'m sorry you feel that way, but no refunds." (Hang up)', th: '🛡️ เกราะกำบังสัญญา: "ผมดำเนินการตามสัญญาอย่างมืออาชีพ สเปคทางเทคนิคครบถ้วน เสียใจที่คุณรู้สึกแบบนั้นแต่ไม่คืนเงินครับ" (วางสาย)', zh: '🛡️ 合同辩护：“我专业地执行了合同。符合技术规格。很遗憾你有这种感觉，但不退款。”（挂断）' }, consequence: { en: '💀 1-Star Bomb. She writes a 2,000-word review everywhere destroying you. "Arrogant, insensitive robot." You lose 10 future bookings. Being "right" cost you $30,000.', th: '💀 ระเบิด 1 ดาว เธอเขียนรีวิว 2,000 คำด่าคุณเละทุกที่ "หุ่นยนต์จอมหยิ่ง ยะโส" คุณเสียลูกค้าใหม่ 10 ราย การเป็นฝ่าย "ถูก" ทำให้คุณเสียเงิน $30,000', zh: '💀 1星炸弹。她在所有地方写了一篇2000字的评论毁掉你。“傲慢、麻木的机器人。”你失去了10个未来的预订。即使你是“对的”，也让你损失了3万美元。' }, stats: { competence: 30, ethics: 20, leadership: 10, innovation: 20 } },
            { id: 'B', text: { en: '👂 Empathy & Edit: "Invite her to the studio. Sit down. Listen. Offer to re-edit her 20 favorite shots for slimming/lighting adjustments."', th: '👂 เห็นใจและแก้ให้: "เชิญเธอมาที่สตูดิโอ นั่งลง รับฟัง เสนอแก้รูปโปรด 20 ใบของเธอให้ผอมลง/ปรับแสงใหม่"', zh: '👂 同理心与编辑：“邀请她来工作室。坐下来。倾听。提议为她最喜欢的20张照片重新修图，进行瘦身/光线调整。”' }, consequence: { en: '✅ Crisis Averted. She just wanted to be heard. The re-edits took 2 hours. She changes her mind and tells friends you "went above and beyond." Customer Service wins.', th: '✅ รอดพ้นวิกฤต เธอแค่ต้องการคนรับฟัง การแก้รูปใช้เวลา 2 ชั่วโมง เธอเปลี่ยนใจและบอกเพื่อนว่าคุณ "บริการเหนือความคาดหมาย" ชนะด้วยบริการลูกค้า', zh: '✅ 危机解除。她只是想被倾听。重新修图花了2小时。她改变了主意，告诉朋友你“超越了期望”。客户服务获胜。' }, stats: { competence: 40, ethics: 50, leadership: 45, innovation: 30 } },
            { id: 'C', text: { en: '💰 Full Refund: "I never want an unhappy client. Here is your $3,000 back. Please don\'t write a bad review."', th: '💰 คืนเงินเต็มจำนวน: "ผมไม่อยากให้ลูกค้าไม่มีความสุข นี่ครับเงิน $3,000 คืนให้ ได้โปรดอย่าเขียนรีวิวแย่ๆ เลยนะ"', zh: '💰 全额退款：“我不希望客户不开心。这是退给你的3000美元。请不要写差评。”' }, consequence: { en: '⚠️ Weakness Signal. You lost money and dignity. She takes the money AND complains anyway. Word gets out that you are a pushover. Clients start fishing for refunds.', th: '⚠️ สัญญาณความอ่อนแอ คุณเสียเงินและศักดิ์ศรี เธอรับเงินแล้วก็ยังบ่นอยู่ดี ข่าวรั่วว่าคุณยอมคนง่าย ลูกค้าเริ่มหาเรื่องขอเงินคืน', zh: '⚠️ 软弱信号。你失去了金钱和尊严。她拿了钱而且照样抱怨。传言说你很好欺负。客户开始想方设法要求退款。' }, stats: { competence: 20, ethics: 30, leadership: 10, innovation: 10 } },
            { id: 'D', text: { en: '📸 The Reshoot: "Let\'s do a \'Day After\' session in her wedding dress. Perfect light, just her, looking amazing. Free of charge."', th: '📸 ถ่ายซ่อม: "มาถ่ายเซสชั่น \'Day After\' ในชุดแต่งงานกัน แสงสวยๆ มีแค่เธอ สวยจึ้ง ถ่ายให้ฟรี"', zh: '📸 重拍：“让我们再拍一次身穿婚纱的‘婚后日’写真。完美的光线，只有她，看起来美极了。免费。”' }, consequence: { en: '✅ Hero Move. She feels like a model. The new photos are stunning. She forgets about the wedding day photos and posts the new ones constantly. You turned a hater into a superfan.', th: '✅ ท่าไม้ตายฮีโร่ เธอรู้สึกเหมือนนางแบบ รูปใหม่ออกมาตะลึงมาก เธอลืมรูปวันงานไปเลยและโพสต์แต่รูปใหม่รัวๆ คุณเปลี่ยนคนเกลียดให้เป็นซูเปอร์แฟน', zh: '✅ 英雄之举。她感觉像个模特。新照片美极了。她忘记了婚礼当天的照片，不断发布新照片。你把黑粉变成了超级粉丝。' }, stats: { competence: 50, ethics: 45, leadership: 50, innovation: 40 } }
        ]
    },

    {
        id: 'pho_021',
        text: {
            en: '🔐 The Insurance Claim: Your bag gets stolen with $8,000 of gear. You have insurance, but you realize your policy expired 3 days ago. You could "fudge" the date on the police report to make it look like it happened 4 days ago. Do you commit fraud?',
            th: '🔐 เคลมประกัน: กระเป๋าคุณโดนขโมยพร้อมอุปกรณ์มูลค่า $8,000 คุณมีประกัน แต่นึกได้ว่ากรมธรรม์หมดอายุไปเมื่อ 3 วันก่อน คุณสามารถ "แก้" วันที่ในใบแจ้งความให้ดูเหมือนโดนขโมยเมื่อ 4 วันก่อนได้ คุณจะโกงไหม?',
            zh: '🔐 保险理赔：你的包被偷了，里面有价值8000美元的器材。你有保险，但你发现保单3天前过期了。你可以“篡改”警方报告上的日期，让它看起来像是4天前发生的。你会诈骗吗？'
        },
        options: [
            { id: 'A', text: { en: '📝 Fudge the Date: "It\'s just 3 days! Take the police report, edit the `3` to a `1` in Photoshop. Submit it. I paid premiums for years."', th: '📝 แก้วันที่: "แค่ 3 วันเอง! เอาใบแจ้งความมา แก้เลข 3 เป็นเลข 1 ใน Photoshop ส่งไปเลย ฉันจ่ายเบี้ยมาตั้งหลายปี"', zh: '📝 篡改日期：“只有3天！拿警方报告，在Photoshop里把3改成1。提交。我交了好几年保费了。”' }, consequence: { en: '💀 Caught & Blacklisted. Insurance adjusters investigate. They check security cam timestamps. You are charged with Insurance Fraud (a felony). You are banned from ever getting gear insurance again. Career over.', th: '💀 โดนจับได้และติดแบล็กลิสต์ เจ้าหน้าที่ประกันตรวจสอบ เขาเช็คเวลาในกล้องวงจรปิด คุณโดนข้อหาโกงประกัน (อาชญากรรม) คุณถูกแบนจากการทำประกันอุปกรณ์ตลอดชีวิต จบเห่', zh: '💀 被抓且被列入黑名单。保险理算员进行调查。他们检查监控时间戳。你被指控保险欺诈（重罪）。你被禁止再次购买器材保险。职业生涯结束。' }, stats: { competence: 20, ethics: -100, leadership: 10, innovation: 20 } },
            { id: 'B', text: { en: '💸 Swallow the Loss: "It hurts, but I won\'t lie. I\'ll put the $8,000 on a credit card and work double shifts to pay it off."', th: '💸 กลืนเลือด: "เจ็บปวดแต่ฉันจะไม่โกหก หลับหูหลับตารูดบัตร $8,000 ซื้อใหม่แล้วทำงานกะสองเท่าเพื่อใช้หนี้"', zh: '💸 吞下损失：“很痛，但我不会撒谎。我会刷信用卡支付8000美元，然后加倍工作来还清。”' }, consequence: { en: '✅ Hard Lesson. You are broke for a year. BUT you sleep well at night. You engage "Hustle Mode" and actually grow your client base out of necessity. You learn to set auto-renew on insurance.', th: '✅ บทเรียนราคาแพง คุณถังแตกไปเป็นปี แต่นอนหลับสบายใจ คุณเข้าสู่ "โหมดสู้ชีวิต" และขยายฐานลูกค้าได้จริงเพราะความจำเป็น เรียนรู้ที่จะตั้งต่ออายุประกันอัตโนมัติซะ', zh: '✅ 惨痛的教训。你破产了一年。但在晚上睡得很香。你开启“拼搏模式”，出于必要实际上扩大了你的客户群。你学会了设置保险自动续费。' }, stats: { competence: 40, ethics: 50, leadership: 40, innovation: 30 } },
            { id: 'C', text: { en: '🤝 Crowdfund: "Tell my story on social media. \'Stolen Gear Fund.\' Ask the community for help."', th: '🤝 ระดมทุน: "เล่าเรื่องลงโซเชียล \'กองทุนอุปกรณ์หาย\' ขอความช่วยเหลือจากชาวเน็ต"', zh: '🤝 众筹：“在社交媒体上讲我的故事。‘被盗器材基金’。向社区寻求帮助。”' }, consequence: { en: '⚠️ Charity Case. You raise $3,000. It helps. But professional clients look at you with pity/suspicion. "Why didn\'t they have insurance?" It looks amateurish.', th: '⚠️ ผู้ประสบภัย คุณระดมทุนได้ $3,000 ช่วยได้บ้าง แต่ลูกค้ามืออาชีพมองคุณด้วยความสงสาร/สงสัย "ทำไมไม่ทำประกัน?" ดูมือสมัครเล่นชะมัด', zh: '⚠️ 慈善案例。你筹集了3000美元。这有帮助。但专业客户用怜悯/怀疑的眼光看你。“他们为什么没有保险？”看起来很业余。' }, stats: { competence: 25, ethics: 35, leadership: 20, innovation: 25 } },
            { id: 'D', text: { en: '🎥 Rental Strategy: "Don\'t rebuy yet. Rent gear per shoot for 2 months. Use cash flow to slowly rebuild the kit. Keep debt low."', th: '🎥 กลยุทธ์เช่า: "อย่าเพิ่งซื้อใหม่ เช่าเอาทีละงานสัก 2 เดือน หมุนเงินสดค่อยๆ ซื้อสะสม หนี้จะได้ไม่เยอะ"', zh: '🎥 租赁策略：“先别重买。每次拍摄租用器材，持续2个月。利用现金流慢慢重建装备库。保持低债务。”' }, consequence: { en: '✅ Smart Finance. You realize you don\'t need to own EVERYTHING. You become smarter about gear choices. You end up with a lighter, more efficient kit.', th: '✅ การเงินฉลาด คุณตระหนักว่าไม่ต้องเป็นเจ้าของ "ทุกอย่าง" ก็ได้ คุณฉลาดเลือกอุปกรณ์มากขึ้น สุดท้ายได้ชุดอุปกรณ์ที่เบาและมีประสิทธิภาพกว่าเดิม', zh: '✅ 聪明的财务。你意识到你不需要拥有所有东西。你在器材选择上变得更聪明。最终你拥有了一套更轻便、更高效的装备。' }, stats: { competence: 45, ethics: 40, leadership: 35, innovation: 40 } }
        ]
    },

    {
        id: 'pho_022',
        text: {
            en: '🎓 The Masterclass Opportunity: You have 10k followers. A platform offers you $5,000 upfront to create a "Mastering Portraits" course. It will take you 100 hours to produce. Your photography rate is $100/hr, so it\'s technically a loss. Do you do it?',
            th: '🎓 โอกาสทำคอร์ส: คุณมีผู้ติดตาม 10k แพลตฟอร์มหนึ่งเสนอเงินก้อน $5,000 ให้ทำคอร์ส "Mastering Portraits" ต้องใช้เวลา 100 ชม. ในการผลิต ค่าตัวถ่ายภาพคุณคือ $100/ชม. ดังนั้นทางเทคนิคแล้วขาดทุน จะทำไหม?',
            zh: '🎓 大师班机会：你有1万名粉丝。一个平台预付5000美元邀请你制作“精通人像”课程。你需要花100小时制作。你的摄影费率是100美元/小时，所以这在技术上是亏损的。你会做吗？'
        },
        options: [
            { id: 'A', text: { en: '📹 Passive Income Play: "Yes. The $5k is just the advance. Once the course is live, I\'ll make royalties forever. It scales better than shooting."', th: '📹 เกมรายได้ Passive: "ทำ $5k มันแค่เงินมัดจำ พบคอร์สขายได้ ฉันจะได้ค่าลิขสิทธิ์ตลอดไป มันขยายผลได้ดีกว่ารับจ้างถ่าย"', zh: '📹 被动收入策略：“做。5000美元只是预付款。课程上线后，我将永远获得版税。这比拍摄更容易扩展。”' }, consequence: { en: '✅ Wealth Unlock. The course sells 500 copies in year 1. You make $20,000 extra. Plus, students become fans and refer clients. You stopped trading time for money.', th: '✅ ปลดล็อคความมั่งคั่ง คอร์สขายได้ 500 ชุดในปีแรก คุณได้เงินเพิ่ม $20,000 แถมนักเรียนกลายเป็นแฟนคลับและแนะนำลูกค้าให้ คุณเลิกเอาเวลาไปแลกเงินแล้ว', zh: '✅ 财富解锁。课程在第一年卖出了500份。你多赚了2万美元。此外，学生变成了粉丝并推荐客户。你不再用时间换金钱。' }, stats: { competence: 45, ethics: 35, leadership: 45, innovation: 50 } },
            { id: 'B', text: { en: '📸 Focus on Craft: "No. 100 hours is too much. I\'d rather spend that time shooting 10 amazing projects for my portfolio. I am a photographer, not a teacher."', th: '📸 โฟกัสที่งานฝีมือ: "ไม่ 100 ชม. มันเยอะไป เอาเวลานั้นไปถ่ายงานเจ๋งๆ สัก 10 โปรเจกต์ใส่พอร์ตดีกว่า ฉันคือช่างภาพ ไม่ใช่ครู"', zh: '📸 专注于手艺：“不。100小时太多了。我宁愿花这些时间为我的作品集拍摄10个精彩的项目。我是摄影师，不是老师。”' }, consequence: { en: '⚠️ Artistic purity, Financial Ceiling. Your portfolio gets better, you raise rates slightly. But you are still on the "Hamsper Wheel" - if you stop shooting, you stop eating. No leverage.', th: '⚠️ ศิลปะบริสุทธิ์ แต่เพดานรายได้จำกัด พอร์ตสวยขึ้น ขึ้นราคาได้นิดหน่อย แต่คุณยังอยู่ใน "วงล้อหนูถีบจักร" - หยุดถ่ายเมื่อไหร่ อดตายเมื่อนั้น ไม่มีคานผ่อนแรง', zh: '⚠️ 艺术纯粹，财务上限。你的作品集变得更好，稍微提高了费率。但你仍然在“跑轮”上——如果你停止拍摄，你就没饭吃。没有杠杆。' }, stats: { competence: 50, ethics: 30, leadership: 20, innovation: 10 } },
            { id: 'C', text: { en: '✂️ Minimal Viable Product: "I\'ll do a mini-course in 20 hours for the $5k. Quick edits, simple tips. Take the money and run."', th: '✂️ ทำแบบพอส่ง: "ทำมินิคอร์สสัก 20 ชม. แลก $5k ตัดต่อไวๆ ทริคง่ายๆ รับเงินแล้วโกย"', zh: '✂️ 最小可行产品：“我会花20小时做一个迷你课程换取5000美元。快速编辑，简单技巧。拿钱走人。”' }, consequence: { en: '❌ Brand Damage. Students demand refunds. "This is basic trash." Your reputation as an expert takes a hit. The platform blacklists you.', th: '❌ แบรนด์พัง นักเรียนขอเงินคืน "นี่มันขยะพื้นฐานชัดๆ" ชื่อเสียงความเป็นผู้เชี่ยวชาญป่นปี้ แพลตฟอร์มแบนคุณ', zh: '❌ 品牌受损。学生要求退款。“这是基础垃圾。”你的专家声誉受到打击。平台将你列入黑名单。' }, stats: { competence: 30, ethics: 20, leadership: 15, innovation: 20 } },
            { id: 'D', text: { en: '📢 Self-Host: "Decline the platform. Build my own course on my own site. Keep 100% of revenue. It\'s harder marketing, but I own the audience."', th: '📢 ทำเองขายเอง: "ปฏิเสธแพลตฟอร์ม สร้างคอร์สบนเว็บตัวเอง เก็บรายได้ 100% การตลาดเหนื่อยหน่อย แต่ฉันเป็นเจ้าของฐานลูกค้าเอง"', zh: '📢 自主托管：“拒绝平台。在我自己的网站上建立课程。保留100%收入。营销更难，但我拥有受众。”' }, consequence: { en: '✅ Long Game Win. It takes 6 months to get traction. But eventually, you build an email list of 5,000 photographers. You launch a preset pack and make $50k in a weekend. You own your destiny.', th: '✅ ชนะเกมยาว ใช้เวลา 6 เดือนกว่าจะติดตลาด แต่สุดท้ายคุณมีอีเมลลิสต์ช่างภาพ 5,000 คน วันดีคืนดีขายพรีเซ็ตทำเงิน $50k ได้ในสุดสัปดาห์เดียว คุณกำหนดโชคชะตาตัวเอง', zh: '✅ 长线胜利。需要6个月才有起色。但最终，你建立了一个5000名摄影师的邮件列表。你推出预设包，周末赚了5万美元。你掌握了自己的命运。' }, stats: { competence: 40, ethics: 40, leadership: 55, innovation: 45 } }
        ]
    },

    {
        id: 'pho_023',
        text: {
            en: '🖼️ The Gallery Dilemma: A prestigious art gallery wants to host a solo exhibition of your work. The cost to frame and print everything is $8,000 (your own money). It\'s great prestige, but galleries rarely sell enough to break even for the artist. Do you commit?',
            th: '🖼️ ไดเลมม่าแกลเลอรี่: แกลเลอรี่ศิลปะที่มีชื่อเสียงต้องการจัดนิทรรศการเดี่ยวงานของคุณ ค่ากรอบและค่าพิมพ์ทั้งหมดคือ $8,000 (เงินคุณเอง) มันมีเกียรติมาก แต่แกลเลอรี่มักขายงานไม่พอคืนทุนให้ศิลปินหรอก คุณจะเอาด้วยไหม?',
            zh: '🖼️ 画廊困境：一家享有盛誉的艺术画廊想为你举办个展。所有装裱和打印的费用是8000美元（你自掏腰包）。这很有面子，但画廊很少能卖出足够让艺术家收支平衡的作品。你会承诺吗？'
        },
        options: [
            { id: 'A', text: { en: '🎨 For the Art: "I\'ll spend the $8k. This establishes me as a Fine Art Photographer, not just a service provider. The status is worth the loss."', th: '🎨 เพื่อศิลปะ: "ฉันจะจ่าย $8k นี่จะยกระดับฉํนเป็นศิลปินวิจิตรศิลป์ ไม่ใช่แค่ผู้ให้บริการ สถานะทางสังคมคุ้มค่าที่จะขาดทุน"', zh: '🎨 为了艺术：“我会花这8000美元。这确立了我作为美术摄影师的地位，而不仅仅是服务提供者。这种地位值得亏损。”' }, consequence: { en: '✅ Status Upgrade. You sell only $2,000 worth of prints (Loss: $6k). BUT, you can now charge double for commercial work because you have "Exhibited Artist" in your bio. You attract premium brand clients.', th: '✅ อัปเกรดสถานะ ขายงานได้แค่ $2,000 (ขาดทุน $6k) แต่ตอนนี้คุณอัปราคาค่าตัวงานพาณิชย์ได้สองเท่าเพราะมีคำว่า "ศิลปินที่ผ่านการจัดแสดง" ในโปรไฟล์ ดึงดูดลูกค้าแบรนด์หรู', zh: '✅ 地位升级。你只卖出了价值2000美元的印刷品（亏损6000美元）。但是，你现在的商业作品可以收取双倍费用，因为你简历里有“参展艺术家”。你吸引了高端品牌客户。' }, stats: { competence: 50, ethics: 40, leadership: 40, innovation: 50 } },
            { id: 'B', text: { en: '📉 Pass: "Can\'t eat prestige. Ill stick to paying clients. If they want to show my work, they can pay for the printing."', th: '📉 ผ่าน: "เกียรติยศกินไม่ได้ ฉันจะอยู่กับลูกค้าที่จ่ายเงิน ถ้าเขาอยากโชว์งานฉัน เขาต้องออกค่าพิมพ์สิ"', zh: '📉 放弃：“名声不能当饭吃。我会坚持服务付费客户。如果他们想展示我的作品，他们得付打印费。”' }, consequence: { en: '⚠️ Missed Opportunity. The gallery finds someone else. That photographer gets reviewed in the NY Times. You saved $8k, but you remain unknown outside your local circle.', th: '⚠️ พลาดโอกาส แกลเลอรี่หาคนอื่น ช่างภาพคนนั้นได้รีวิวใน NY Times คุณประหยัด $8k แต่ยังคงเป็นโนบอดี้อยู่นอกวงสังคมเดิมๆ', zh: '⚠️ 错失良机。画廊找了别人。那位摄影师被《纽约时报》评论。你省下了8000美元，但在你的圈子之外仍然默默无闻。' }, stats: { competence: 35, ethics: 30, leadership: 20, innovation: 10 } },
            { id: 'C', text: { en: '🤝 Sponsor Hunt: "I\'ll find a corporate sponsor (e.g., Canon, a local bank) to cover the $8k in exchange for logos on the wall."', th: '🤝 ล่าสปอนเซอร์: "ฉันจะหาบริษัทสปอนเซอร์ (เช่น Canon, ธนาคารท้องถิ่น) มาจ่าย $8k แลกกับโลโก้บนผนัง"', zh: '🤝 寻找赞助商：“我会找一个企业赞助商（例如佳能，当地银行）来支付8000美元，以换取墙上的Logo。”' }, consequence: { en: '✅ Business Genius. You get the show for free. The gallery is annoyed by the logos, but the launch party is packed. You sell $2k of art, which is pure profit. Best outcome.', th: '✅ อัจฉริยะทางธุรกิจ คุณได้จัดงานฟรี แกลเลอรี่อาจรำคาญโลโก้นิดหน่อย แต่งานปาร์ตี้เปิดตัวคนแน่น ขายงานได้ $2k คือกำไรล้วนๆ ผลลัพธ์ดีที่สุด', zh: '✅ 商业天才。你免费举办了展览。画廊对Logo很恼火，但发布会挤满了人。你卖出了2000美元的艺术品，这全是利润。最好的结果。' }, stats: { competence: 40, ethics: 35, leadership: 60, innovation: 40 } },
            { id: 'D', text: { en: '🖼️ Virtual Exhibition: "Rent a VR gallery space online for $200. Host a global virtual opening. Sell NFTs/Physical prints on demand."', th: '🖼️ นิทรรศการเสมือน: "เช่าพื้นที่แกลเลอรี่ VR ออนไลน์ $200 จัดงานเปิดตัวเสมือนจริงระดับโลก ขาย NFT/ภาพพิมพ์ตามสั่ง"', zh: '🖼️ 虚拟展览：“花200美元租一个在线VR画廊空间。举办全球虚拟开幕式。按需出售NFT/实体印刷品。”' }, consequence: { en: '⚠️ Ahead of Time. Cool concept, but collectors want wine and cheese, not VR headsets. You sell nothing. Tech-savvy but commercially weak.', th: '⚠️ ล้ำหน้าเกินไป คอนเซปต์เจ๋ง แต่นักสะสมต้องการไวน์และชีส ไม่ใช่แว่น VR ขายไม่ออกเลย เก่งเทคแต่ธุรกิจแย่', zh: '⚠️ 超前。概念很酷，但收藏家想要红酒和奶酪，而不是VR头显。你什么也没卖出去。精通技术但商业疲软。' }, stats: { competence: 35, ethics: 30, leadership: 30, innovation: 55 } }
        ]
    },

    {
        id: 'pho_024',
        text: {
            en: '👯 The Influencer Squad: A group of 5 influential fashion bloggers invites you to a trip to Tulum. They won\'t pay you, but they cover your flight and hotel ($3,000 value). They want "content all day." It\'s a week of work. Go?',
            th: '👯 แก๊งอินฟลูฯ: กลุ่มบล็อกเกอร์แฟชั่นผู้ทรงอิทธิพล 5 คนชวนคุณไปทริป Tulum ไม่จ่ายค่าตัวนะ แต่ออกค่าตั๋วและโรงแรมให้ (มูลค่า $3,000) เขาต้องการ "คอนเทนต์ทั้งวัน" งานตลอดสัปดาห์เลย ไปไหม?',
            zh: '👯 网红小队：由5位有影响力的时尚博主组成的小组邀请你去图卢姆旅行。他们不付钱，但包机票和酒店（价值3000美元）。他们想要“全天候的内容”。这是一周的工作。去吗？'
        },
        options: [
            { id: 'A', text: { en: '✈️ Go for the Lifestyle: "Free vacation to Tulum! I\'ll take photos, party, and get content for my own feed too."', th: '✈️ ไปเพื่อไลฟ์สไตล์: "เที่ยวฟรี Tulum! ถ่ายรูป ปาร์ตี้ แล้วก็ได้คอนเทนต์ลงฟีดตัวเองด้วย"', zh: '✈️ 为了生活方式而去：“免费图卢姆度假！我会拍照，聚会，也为我自己的动态获取内容。”' }, consequence: { en: '⚠️ Exhaustion. It\'s NOT a vacation. They wake you up at 5am for sunrise and keep you shooting till 11pm. You are a servant. You come back dead tired with no money. But your Instagram looks cool.', th: '⚠️ หมดสภาพ มันไม่ใช่การพักร้อน พวกเขาปลุกคุณตี่ 5 มาถ่ายแสงเช้าและใช้งานถึง 5 ทุ่ม คุณคือคนรับใช้ กลับมาเหนื่อยตายชักแถมไม่ได้เงิน แต่อินสตาแกรมดูเท่ดีนะ', zh: '⚠️ 精疲力竭。这不是度假。他们在凌晨5点叫醒你拍日出，让你一直拍到晚上11点。你是个仆人。你回来时累得要死，身无分文。但你的Instagram看起来很酷。' }, stats: { competence: 30, ethics: 30, leadership: 20, innovation: 30 } },
            { id: 'B', text: { en: '📝 Contract the Hours: "I\'ll go, but I shoot 2 hours in the morning and 2 hours at sunset. The rest of the time is MINE. Put it in writing."', th: '📝 สัญญาระบุเวลา: "ไปนะ แต่ถ่ายให้แค่ 2 ชม. เช้ากับ 2 ชม. เย็น เวลาที่เหลือคือของฉัน ระบุในสัญญาด้วย"', zh: '📝 合同规定时间：“我去，但我只在早上拍2小时，日落拍2小时。剩下的时间是我的。白纸黑字写下来。”' }, consequence: { en: '✅ Boundary Win. They agree. You get a semi-vacation and network with them. You take amazing shots because you are rested. One of them recommends you to a swimsuit brand.', th: '✅ ชนะด้วยขอบเขต ตกลงตามนั้น คุณได้กึ่งๆ พักร้อนและได้สร้างสัมพันธ์กับพวกเขา คุณถ่ายรูปสวยมากเพราะได้พักผ่อน หนึ่งในนั้นแนะนำคุณให้แบรนด์ชุดว่ายน้ำ', zh: '✅ 界限胜利。他们同意了。你获得了半个假期并与他们建立了联系。你拍出了很棒的照片，因为休息得很好。其中一人把你推荐给了一个泳装品牌。' }, stats: { competence: 40, ethics: 40, leadership: 45, innovation: 30 } },
            { id: 'C', text: { en: '💰 Demand Pay: "I don\'t work for travel. My day rate is $500. Pay me $2,500 plus the trip, or I stay home."', th: '💰 เรียกค่าจ้าง: "ฉันไม่ทำงานแลกเที่ยว ค่าตัววันละ $500 จ่ายมา $2,500 บวกทริป ไม่งั้นก็นอนบ้าน"', zh: '💰 要求报酬：“我不为旅行工作。我的日薪是500美元。付给我2500美元加上旅费，或者我呆在家里。”' }, consequence: { en: '📉 They Ghost You. They find a younger photographer who jumps at the "free" trip. You kept your standards but missed the network. Quiet week at home.', th: '📉 โดนเท พวกเขาหาช่างภาพเด็กใหม่ที่ตะครุบทริป "ฟรี" ทันที คุณรักษามตรฐานแต่พลาดคอนเนคชัน สัปดาห์เงียบเหงาที่บ้าน', zh: '📉 他们无视你。他们找了一个更年轻的摄影师，抢着要这次“免费”旅行。你保持了标准，但错过了人脉。在家里度过了安静的一周。' }, stats: { competence: 40, ethics: 40, leadership: 30, innovation: 10 } },
            { id: 'D', text: { en: '🛍️ Brand Deal: "I\'ll go if I can sell the resulting photos to the hotels/brands we visit. You get social media pics; I retain commercial rights."', th: '🛍️ ดีลแบรนด์: "จะไปถ้าฉันเอารูปที่ได้ไปขายโรงแรม/แบรนด์ที่เราไปได้ พวกเธอได้รูปลงโซเชียล ฉันเก็บสิทธิ์เชิงพาณิชย์"', zh: '🛍️ 品牌交易：“如果我可以把照片卖给我们要去的酒店/品牌，我就去。你们拿到社交媒体照片；我保留商业权。”' }, consequence: { en: '✅ Commercial Hustle. You sell the collection to the resort for $4,000. The influencers are happy with their content. You made money and got a trip. Smart.', th: '✅ พ่อค้างานพาณิชย์ คุณขายคอลเลกชันให้รีสอร์ทได้ $4,000 อินฟลูฯ แฮปปี้กับรูป คุณได้เงินแถมได้เที่ยว ฉลาด', zh: '✅ 商业运作。你把这套照片以4000美元卖给了度假村。网红们对内容很满意。你赚了钱还去旅行了。聪明。' }, stats: { competence: 45, ethics: 35, leadership: 45, innovation: 45 } }
        ]
    },

    {
        id: 'pho_025',
        text: {
            en: '💻 The Drive Failure: Your main hard drive crashes. It has the only copy of yesterday\'s wedding (2,000 photos). You were "too tired" to backup last night. A data recovery firm wants $2,500 to "attempt" recovery. No guarantees.',
            th: '💻 ฮาร์ดไดรฟ์เจ๊ง: ไดร์ฟหลักพัง มีไฟล์งานแต่งเมื่อวาน (2,000 รูป) อยู่ในนั้นก๊อปปี้เดียว คุณ "เหนื่อยเกิน" ที่จะแบ็คอัพเมื่อคืน บริษัทกู้ข้อมูลเรียก $2,500 เพื่อ "ลอง" กู้ ไม่มีการรับประกัน',
            zh: '💻 硬盘故障：你的主硬盘崩溃了。里面有昨天婚礼（2000张照片）的唯一副本。你昨晚“太累了”没备份。一家数据恢复公司要价2500美元“尝试”恢复。不保证成功。'
        },
        options: [
            { id: 'A', text: { en: '💸 Pay the Ransom: "Take my money. Try everything. I can\'t lose this wedding."', th: '💸 ยอมจ่ายค่าไถ่: "เอาเงินไปเลย ลองทุกทาง ฉันเสียงานแต่งนี้ไม่ได้"', zh: '💸 支付赎金：“拿钱去。尝试一切办法。我不能失去这场婚礼。”' }, consequence: { en: '✅/❌ Coin Flip. (50% Chance). 1. They recover it. You learn a $2,500 lesson about RAID drives. 2. They fail. You are out $2,500 AND have to tell the bride. (Assume Recovery for narrative: You survive, but your savings are wiped).', th: '✅/❌ โยนหัวก้อย (โอกาส 50%) 1. กู้ได้ บทเรียนราคา $2,500 เรื่อง RAID 2. กู้ไม่ได้ เสีย $2,500 แถมต้องบอกเจ้าสาว (สมมุติว่ากู้ได้ในเนื้อเรื่อง: รอดตัวไป แต่เงินเก็บเกลี้ยง)', zh: '✅/❌ 抛硬币。（50%机率）。1. 他们恢复了。你花2500美元买了个关于RAID驱动器的教训。2. 他们失败了。你损失了2500美元还得告诉新娘。（假设恢复成功：你活下来了，但积蓄没了）。' }, stats: { competence: 20, ethics: 30, leadership: 10, innovation: 10 } },
            { id: 'B', text: { en: '🧊 Freezer Trick: "I saw on YouTube if you freeze the drive, it might spin one last time. I\'ll try it myself."', th: '🧊 มุกแช่แข็ง: "เห็นใน YouTube บอกว่าถ้าเอาไดร์ฟแช่ช่องฟรีซ มันอาจหมุนได้อีกครั้งเฮือกสุดท้าย ลองทำเองดีกว่า"', zh: '🧊 冷冻技巧：“我在YouTube上看到如果冷冻硬盘，它可能会最后转一次。我自己试试。”' }, consequence: { en: '💀 Destruction. Condensation kills the platters permanently. Now even the pros can\'t fix it. You destroyed the data. Total negligence.', th: '💀 พังพินาศ ไอน้ำทำลายจานข้อมูลถาวร ตอนนี้โปรก็กู้ไม่ได้แล้ว คุณทำลายข้อมูลเองกับมือ ประมาทเลินเล่อสุดๆ', zh: '💀 毁灭。冷凝水永久损坏了盘片。现在连专业人士也修不好。你毁了数据。完全的疏忽。' }, stats: { competence: -10, ethics: 10, leadership: -10, innovation: 20 } },
            { id: 'C', text: { en: '🤥 The "Camera Error" Lie: "Tell the couple the memory card corrupted. Refund + $1,000 apology. Claim it was gear failure, not backup failure."', th: '🤥 โกหกว่า "กล้องพัง": "บอกคู่บ่าวสาวว่าเมมโมรี่การ์ดเสีย คืนเงิน + $1,000 ค่าขอโทษ อ้างว่าเป็นที่อุปกรณ์ ไม่ใช่ความผิดพลาดที่ไม่แบ็คอัพ"', zh: '🤥 “相机错误”谎言：“告诉新人存储卡损坏。退款 + 1000美元道歉费。声称是器材故障，而不是备份失败。”' }, consequence: { en: '⚠️ Reputation Control. They are angry but accept "technical failure" better than "lazy photographer." You save face but feel guilty forever. Ethics -50.', th: '⚠️ คุมความเสียหาย พวกเขาโกรธแต่ยอมรับ "ปัญหาทางเทคนิค" ได้ดีกว่า "ช่างภาพขี้เกียจ" รักษาหน้าได้แต่รู้สึกผิดไปตลอดชีวิต ค่าจริยธรรม -50', zh: '⚠️ 声誉控制。他们很生气但接受“技术故障”，这比“懒惰的摄影师”好听。你保住了面子但永远感到内疚。职业道德 -50。' }, stats: { competence: 10, ethics: -50, leadership: 0, innovation: 10 } },
            { id: 'D', text: { en: '🔄 Memory Card Scrape: "Wait! I haven\'t formatted the cards yet. I can run recovery software on the original memory cards!"', th: '🔄 ขุดเมมการ์ด: "เดี๋ยว! ฉันยังไม่ได้ฟอร์แมตการ์ดนี่นา ใช้โปรแกรมกู้ข้อมูลจากการ์ดต้นฉบับได้!"', zh: '🔄 刮存储卡：“等等！我还没格式化卡。我可以在原始存储卡上运行恢复软件！”' }, consequence: { en: '✅ Luck Factor. You recover 95% of the photos from the cards. You only lose the reception heavy-dancing shots. You survive. You buy a dual-slot backup system immediately.', th: '✅ แต้มบุญทำงาน กู้ได้ 95% จากการ์ด หายแค่ช่วงเต้นรำหนักๆ รอดตาย ซื้อระบบแบ็คอัพสองสล็อตทันที', zh: '✅ 运气因素。你从卡里恢复了95%的照片。只丢了接待处狂欢的照片。你活了下来。立即购买了双槽备份系统。' }, stats: { competence: 30, ethics: 40, leadership: 20, innovation: 30 } }
        ]
    },

    // SECTION 3: ESTABLISHED PRO & ARTISTIC LEGACY (Questions 26-35)

    {
        id: 'pho_026',
        text: {
            en: '📰 The Magazine Cover: Vogue requests a cover shoot. The deadline is tomorrow. You are already booked for a wedding tomorrow. The wedding couple paid $8,000. Vogue pays $500 (editorial rates are low) but it\'s... VOGUE.',
            th: '📰 ปกนิตยสาร: Vogue ติดต่อขอให้ไปถ่ายปก เดดไลน์คือพรุ่งนี้ แต่คุณรับงานแต่งงานพรุ่งนี้ไว้แล้ว คู่บ่าวสาวจ่าย $8,000 Vogue จ่าย $500 (เรทนิตยสารมันต่ำ) แต่มันคือ... VOGUE นะ',
            zh: '📰 杂志封面：《Vogue》要求拍摄封面。截止日期是明天。你明天已经预订了婚礼拍摄。这对新人付了8000美元。《Vogue》只付500美元（编辑费率很低），但它是……VOGUE。'
        },
        options: [
            { id: 'A', text: { en: '💍 Honor the Wedding: "I gave my word to the couple. Integrity is my brand. I decline Vogue."', th: '💍 ให้เกียรติงานแต่ง: "ฉันรับปากบ่าวสาวไว้แล้ว ความซื่อสัตย์คือแบรนด์ของฉัน ฉันปฏิเสธ Vogue"', zh: '💍 尊重婚礼：“我向这家新人承诺过。诚信是我的品牌。我拒绝《Vogue》。”' }, consequence: { en: '✅ Respect. The couple loves you. Vogue respects your professionalism and books you next month for a deeper spread with flexible dates. You kept the $8k AND got the feature later.', th: '✅ ความเคารพ บ่าวสาวรักคุณ Vogue นับถือความเป็นมืออาชีพของคุณและจองคิวคุณเดือนหน้าสำหรับเซ็ตใหญ่ที่ยืดหยุ่นวันได้ คุณรักษาเงิน $8k ไว้ได้ แถมได้ลงนิตยสารทีหลัง', zh: '✅ 尊重。这这对新人很爱你。《Vogue》尊重你的专业精神，并预订了下个月更深入的专栏，日期灵活。你保住了8000美元，后来还得以上杂志。' }, stats: { competence: 40, ethics: 60, leadership: 40, innovation: 20 } },
            { id: 'B', text: { en: '🌟 Dump the Wedding: "Call the couple, fake an emergency (Covid?), refund them double ($16k), and shoot Vogue. It\'s a once-in-a-lifetime chance."', th: '🌟 เทงานแต่ง: "โทรหาบ่าวสาว แกล้งมีเหตุฉุกเฉิน (ติดโควิด?) คืนเงินสองเท่า ($16k) แล้วไปถ่าย Vogue มันโอกาสครั้งเดียวในชีวิตนะ"', zh: '🌟 抛弃婚礼：“给新人打电话，伪造紧急情况（新冠？），退双倍款（1.6万美元），然后去拍《Vogue》。这是一生一次的机会。”' }, consequence: { en: '💀 Fame at a Cost. You get the cover. You are famous. But the couple finds out (you posted about it!). They sue you. The industry calls you a "flake." High fashion loves you, real people hate you.', th: '💀 ชื่อเสียงที่ต้องแลก คุณได้ปก คุณดัง แต่บ่าวสาวจับได้ (คุณโพสต์ลงเน็ตเอง!) เขาฟ้องคุณ วงการด่าคุณว่า "คนเชื่อถือไม่ได้" แฟชั่นชั้นสูงรักคุณ แต่คนทั่วไปเกลียดคุณ', zh: '💀 代价高昂的名声。你上了封面。你出名了。但新人发现了（你自己发的帖子！）。他们起诉你。业内称你为“骗子”。时尚界爱你，普通人恨你。' }, stats: { competence: 50, ethics: -40, leadership: 10, innovation: 40 } },
            { id: 'C', text: { en: '🤝 The Associate Switch: "Tell the couple honestly: \'I have a huge opportunity. My lead associate will shoot your wedding for 50% off. I will still edit everything.\'"', th: '🤝 สลับตัวทีมงาน: "บอกบ่าวสาวตรงๆ: \'ผมมีโอกาสใหญ่เข้ามา ทีมงานมือหนึ่งของผมจะไปถ่ายแทนลดราคาให้ 50% ผมจะยังคงแต่งรูปทั้งหมดเอง\'"', zh: '🤝 助理替换：“诚实地告诉新人：‘我有个巨大的机会。我的首席助理会以5折优惠为你们拍摄。我仍然会负责所有后期。’”' }, consequence: { en: '⚠️ Risky negotiation. They might agree, but they will be disappointed. It works, but you damage the client relationship slightly. You get the cover though.', th: '⚠️ การเจรจาเสี่ยง พวกเขาอาจตกลงแต่คงผิดหวัง มันได้ผลนะ แต่ความสัมพันธ์กับลูกค้าเสียหายเล็กน้อย แต่คุณก็ได้ปกนิตยสารแหละ', zh: '⚠️ 冒险的谈判。他们可能会同意，但会很失望。这行得通，但你稍微损害了客户关系。不过你拿到了封面。' }, stats: { competence: 40, ethics: 30, leadership: 40, innovation: 30 } },
            { id: 'D', text: { en: '🌙 The All-Nighter: "Shoot the wedding during the day. Shoot Vogue at night (convert studio to high-fashion set). Sleep when I\'m dead."', th: '🌙 โต้รุ่ง: "ถ่ายงานแต่งตอนกลางวัน ถ่าย Vogue ตอนกลางคืน (จัดสตูดิโอเป็นเซตแฟชั่น) ตายค่อยนอน"', zh: '🌙 通宵达旦：“白天拍婚礼。晚上拍《Vogue》（把工作室改成高级时尚布景）。死后再睡。”' }, consequence: { en: '✅ superhuman Effort. You pull it off. The Vogue editor is impressed by your hustle. You look exhausted in the BTS photos, which makes you look "dedicated." You keep both clients.', th: '✅ ความพยายามเหนือมนุษย์ คุณทำสำเร็จ บก. Vogue ประทับใจในความทุ่มเทของคุณ คุณดูโทรมมากในรูปเบื้องหลัง ซึ่งทำให้ดู "ทุ่มเท" สุดๆ คุณรักษาลูกค้าได้ทั้งสองเจ้า', zh: '✅ 超人的努力。你做到了。《Vogue》编辑对你的拼搏印象深刻。你在幕后花絮中看起来很疲惫，但这让你看起来很“敬业”。你留住了两个客户。' }, stats: { competence: 60, ethics: 50, leadership: 50, innovation: 40 } }
        ]
    },

    {
        id: 'pho_027',
        text: {
            en: '💅 The Celebrity Diva: You are shooting a pop star. She is 4 hours late, rude to your staff, and refuses your lighting setup. She demands to be shot "from above only." She is ruining the vibe. How do you handle her?',
            th: '💅 ดาร่าเรื่องเยอะ: คุณกำลังถ่ายป๊อปสตาร์ เธอมาสาย 4 ชั่วโมง หยาบคายกับทีมงานคุณ และไม่ยอมรับการจัดแสงของคุณ เธอบังคับให้ถ่าย "มุมกดเท่านั้น" บรรยากาศพังหมด คุณจะจัดการเธอยังไง?',
            zh: '💅 明星耍大牌：你在拍一位流行歌星。她迟到了4小时，对你的员工很粗鲁，并拒绝你的布光。她要求“只能从上方”拍摄。她毁了整个氛围。你如何处理？'
        },
        options: [
            { id: 'A', text: { en: '🤐 Shut Up & Shoot: "She\'s the star. Do exactly what she says. Get the check. Don\'t bruise her ego."', th: '🤐 หุบปากแล้วถ่ายซะ: "เธอคือดารา ทำตามที่เธอสั่ง รับเช็ค จบ อย่าไปขัดใจเธอ"', zh: '🤐 闭嘴拍摄：“她是明星。照她说的做。拿支票。不要伤她的自尊。”' }, consequence: { en: '😐 Mediocre Result. The photos are boring and unflattering (her lighting idea was bad). She blames YOU later. "Why do I look bad?" You got paid but lose reputation.', th: '😐 ผลลัพธ์งั้นๆ รูปออกมาน่าเบื่อและดูไม่ดี (ไอเดียแสงเธอห่วย) เธอโทษคุณทีหลัง "ทำไมฉันดูแย่จัง?" คุณได้เงินแต่เสียชื่อเสียง', zh: '😐 平庸的结果。照片很无聊也不好看（她的布光主意很糟糕）。她后来怪你。“为什么我看起来很糟糕？”你拿到了钱但失去了声誉。' }, stats: { competence: 20, ethics: 20, leadership: 10, innovation: 10 } },
            { id: 'B', text: { en: '👑 Assert Authority: "Listen, I am the photographer. If you want to look good, you listen to me. Otherwise, leave."', th: '👑 แสดงอำนาจ: "ฟังนะ ผมคือช่างภาพ ถ้าอยากดูดี ต้องฟังผม ไม่งั้นก็เชิญกลับ"', zh: '👑 维护权威：“听着，我是摄影师。如果你想看起来漂亮，就听我的。否则，离开。”' }, consequence: { en: '✅ Power Move. She is shocked. No one talks to her like that. She respects your confidence. She sits down, listens, and you get "The Shot." She tags you as "The Boss."', th: '✅ ท่าไม้ตายอำนาจ เธอช็อก ไม่มีใครกล้าพูดกับเธอแบบนี้ เธอนับถือความมั่นใจของคุณ เธอนั่งลง รับฟัง และคุณก็ได้ "รูปที่ดีที่สุด" เธอแท็กคุณว่า "บอส"', zh: '✅ 权力举措。她震惊了。没人敢那样跟她说话。她尊重你的自信。她坐下来，听你的，你拍到了“那张照片”。她标记你为“老板”。' }, stats: { competence: 50, ethics: 40, leadership: 60, innovation: 30 } },
            { id: 'C', text: { en: '🍬 Kill with Kindness: "Flatter her excessively. \'Oh wow, yes, great idea! Let\'s try your way, then one my way just for safety.\'"', th: '🍬 ฆ่าด้วยความหวาน: "เยินยอเธอสุดๆ \'โอ้ว ใช่เลย ไอเดียเลิศ! มาลองแบบคุณกัน แล้วขอแบบผมสักใบเผื่อไว้เนอะ\'"', zh: '🍬 以柔克刚：“过度奉承她。‘哇，是的，好主意！我们先试你的方法，然后按我的方法拍一张保险。’”' }, consequence: { en: '✅ Manipulation 101. It works. You waste time on her bad ideas, but eventually guide her to your setup without her realizing. Good photos, high stress.', th: '✅ จิตวิทยา 101 ได้ผล คุณเสียเวลากับไอเดียห่วยๆ ของเธอ แต่สุดท้ายก็ต้อนเธอมาเข้าทางคุณได้โดยเธอไม่รู้ตัว รูปสวย แต่เครียดจัด', zh: '✅ 操控术101。行得通。你在她的坏主意上浪费了时间，但最终在不知不觉中引导她接受你的布光。照片不错，压力很大。' }, stats: { competence: 40, ethics: 30, leadership: 40, innovation: 20 } },
            { id: 'D', text: { en: '🚪 Walk Out: "I don\'t work with disrespectful people. Pack up, guys. We are leaving."', th: '🚪 เดินออก: "ผมไม่ทำงานกับคนไม่ให้เกียรติคนอื่น เก็บของพวกเรา ไปกันเถอะ"', zh: '🚪 离开：“我不与不尊重人的人一起工作。收拾东西，伙计们。我们走。”' }, consequence: { en: '⚠️ Viral Moment. You lose the gig. But your assistant tweets about it. You become a hero for workers\' rights in the industry. Other crews love you. You lose money but gain a cult following.', th: '⚠️ โมเมนต์ไวรัล คุณเสียงาน แต่ผู้ช่วยคุณทวีตเรื่องนี้ คุณกลายเป็นฮีโร่สิทธิคนทำงานในวงการ ทีมงานอื่นรักคุณ คุณเสียเงินแต่ได้สาวกติดตามคับคั่ง', zh: '⚠️ 病毒式传播。你丢了工作。但你的助理发了推特。你成为行业工人权利的英雄。其他剧组很爱你。你损失了金钱但获得了一批死忠粉。' }, stats: { competence: 40, ethics: 60, leadership: 50, innovation: 20 } }
        ]
    },

    {
        id: 'pho_028',
        text: {
            en: '📷 The Gear Endorsement: A camera brand (Let\'s say "Fony") offers you $50,000/year to be an Ambassador. The catch: You MUST shoot exclusively with their cameras for 2 years. You hate their menu system and color science. Do you sign?',
            th: '📷 การเป็นพรีเซนเตอร์: แบรนด์กล้อง (สมมติชื่อ "Fony") เสนอเงิน $50,000/ปี ให้คุณเป็นแอมบาสเดอร์ ข้อแม้คือ: ต้องใช้กล้องเขาถ่ายเท่านั้น 2 ปี แต่คุณเกลียดระบบเมนูและสีของมันมาก จะเซ็นไหม?',
            zh: '📷 器材代言：一个相机品牌（假设叫“Fony”）出价5万美元/年请你做大使。条件：你必须在2年内独家使用他们的相机拍摄。你讨厌他们的菜单系统和色彩科学。你会签吗？'
        },
        options: [
            { id: 'A', text: { en: '✍️ Sign & Suffer: "It\'s $100k total! I\'ll learn to love the menus. I\'ll fix the color in post. Money is money."', th: '✍️ เซ็นแล้วทนเอา: "ตั้ง $100k เชียวนะ! เดี๋ยวก็ชินเมนูเองแหละ สีค่อยไปแก้ในคอม เงินก็คือเงิน"', zh: '✍️ 签字忍受：“总共10万美元！我会学会爱上菜单的。我会在后期修正颜色。钱就是钱。”' }, consequence: { en: '💰 Rich but Frustrated. You get paid. But your workflow slows down by 30% fighting the camera. You complain privately. Authenticity -20.', th: '💰 รวยแต่หงุดหงิด ได้เงินจริง แต่การทำงานช้าลง 30% เพราะต้องรบกับกล้อง คุณบ่นลับหลัง ความจริงใจ -20', zh: '💰 有钱但沮丧。你拿到了钱。但因为与相机作斗争，你的工作流程慢了30%。你在私下抱怨。真实性 -20。' }, stats: { competence: 30, ethics: 20, leadership: 20, innovation: 20 } },
            { id: 'B', text: { en: '🚫 Decline: "My tool needs to be an extension of my hand. I cannot create art with tools I fight. I stay with my current brand."', th: '🚫 ปฏิเสธ: "อุปกรณ์ต้องเป็นส่วนหนึ่งของมือฉัน ฉันสร้างงานศิลป์กับเครื่องมือที่ขัดใจไม่ได้หรอก ฉันจะใช้ยี่ห้อเดิม"', zh: '🚫 拒绝：“我的工具必须是我手的延伸。我不能用我不顺手的工具创作艺术。我坚持用现在的品牌。”' }, consequence: { en: '✅ Artistic Integrity. You miss out on the money, but your work remains top-tier. Your refusal leaks, and your current brand sends you free gear (but no cash).', th: '✅ จิตวิญญาณศิลปิน อดได้เงิน แต่งานยังคงระดับท็อป ข่าวรั่วออกไป แบรนด์ที่คุณใช้อยู่เลยส่งของมาให้ใช้ฟรี (แต่ไม่มีเงินสดนะ)', zh: '✅ 艺术正直。你错过了钱，但你的作品保持顶尖。你的拒绝被泄露，现在的品牌给你寄来了免费器材（但没有现金）。' }, stats: { competence: 50, ethics: 50, leadership: 40, innovation: 10 } },
            { id: 'C', text: { en: '🔧 The Hybrid Hack: "Sign the deal. Tape over the logos of my favorite camera and use it for \'personal projects\' (secretly 80% of my work). Use the Fony camera only for BTS videos."', th: '🔧 สับขาหลอก: "เซ็นเลย เอาเทปดำแปะโลโก้กล้องโปรดแล้วใช้ถ่าย \'โปรเจกต์ส่วนตัว\' (ซึ่งแอบถ่ายงานจริง 80%) ใช้กล้อง Fony แค่ตอนถ่ายคลิปเบื้องหลังพอ"', zh: '🔧 混合黑客：“签协议。把我不喜欢的相机Logo贴上胶带，用于‘个人项目’（秘密地占我工作的80%）。只在幕后花絮视频中使用Fony相机。”' }, consequence: { en: '⚠️ Living a Lie. You get paid. But you are constantly paranoid about being caught. If someone spots your EXIF data, you get sued for breach of contract.', th: '⚠️ ชีวิตจอมปลอม ได้เงินแต่ระแวงตลอดเวลา กลัวโดนจับได้ ถ้ามีคนเช็คข้อมูล EXIF รูป คุณโดนฟ้องฐานละเมิดสัญญาแน่', zh: '⚠️ 生活在谎言中。你拿到了钱。但你总是担心被抓。如果有人发现你的EXIF数据，你会因违约被起诉。' }, stats: { competence: 40, ethics: -20, leadership: 20, innovation: 30 } },
            { id: 'D', text: { en: '🗣️ Negotiate Terms: "Tell Fony: \'I love the lens, hate the body. Build me a better firmware or I walk.\' Be a consultant, not a shill."', th: '🗣️ ต่อรองเงื่อนไข: "บอก Fony: \'ฉันชอบเลนส์นะแต่เกลียดบอดี้ ทำเฟิร์มแวร์ให้ดีกว่านี้ไม่งั้นไม่เอา\' เป็นที่ปรึกษา ไม่ใช่หน้าม้า"', zh: '🗣️ 谈判条款：“告诉Fony：‘我喜欢镜头，讨厌机身。给我做一个更好的固件，否则我就走人。’做顾问，不做托儿。”' }, consequence: { en: '✅ Industry Leader. They might actually listen. You help improve the product. The community respects you for fixing the camera\'s issues. You get paid AND a better camera.', th: '✅ ผู้นำวงการ เขาอาจจะฟังคุณจริงๆ คุณช่วยพัฒนาสินค้า ชุมชนนับถือที่คุณช่วยแก้ปัญหาให้กล้อง ได้ทั้งเงินและกล้องที่ดีขึ้น', zh: '✅ 行业领袖。他们实际上可能会听。你帮助改进了产品。社区因你解决了相机的问题而尊重你。你拿到了钱还有更好的相机。' }, stats: { competence: 60, ethics: 50, leadership: 60, innovation: 50 } }
        ]
    },

    {
        id: 'pho_029',
        text: {
            en: '🏫 The Workshop Empire: Your workshops are huge. You can\'t teach them all yourself. A franchise company wants to license your name and curriculum to run "Career Quest Photography Schools" globally. They offer 10% royalties on gross revenue.',
            th: '🏫 อาณาจักรเวิร์กชอป: เวิร์กชอปคุณคนเยอะมาก สอนเองไม่ไหวแล้ว บริษัทแฟรนไชส์ขอซื้อชื่อและหลักสูตรไปเปิด "Career Quest Photography Schools" ทั่วโลก ให้ส่วนแบ่ง 10% จากยอดขายรวม',
            zh: '🏫 工作坊帝国：你的工作坊规模很大。你无法亲自教授所有课程。一家特许经营公司想要获得你的名字和课程许可，在全球开设“职业探索摄影学校”。他们提供总收入10%的版税。'
        },
        options: [
            { id: 'A', text: { en: '✒️ License It: "Scale! I want to be the McDonald\'s of photography. I\'ll take the check and travel consistently."', th: '✒️ ขายไลเซนส์: "ขยายเลย! ฉันจะเป็นแมคโดนัลด์แห่งวงการถ่ายภาพ รับเงินแล้วเที่ยวรัวๆ"', zh: '✒️ 授权：“扩张！我想成为摄影界的麦当劳。我会拿着支票不断旅行。”' }, consequence: { en: '💰 Passive Wealth. The quality drops slightly because you aren\'t there, but the brand grows massively. You make $500k/year doing nothing. You are a tycoon now.', th: '💰 รวยเงียบ คุณภาพตกลงหน่อยเพราะคุณไม่ได้สอนเอง แต่แบรนด์โตระเบิด คุณได้ปีละ $500k โดยไม่ต้องทำอะไร เป็นเจ้าสัวแล้ว', zh: '💰 被动财富。质量略有下降，因为你不在那里，但品牌大规模增长。你什么都不做一年就赚50万美元。你现在是大亨了。' }, stats: { competence: 30, ethics: 30, leadership: 60, innovation: 40 } },
            { id: 'B', text: { en: '🚫 Keep Control: "No one teaches like me. I will train 5 Master Instructors personally and run only superior locations. Quality over Quantity."', th: '🚫 คุมเอง: "ไม่มีใครสอนได้เหมือนฉัน ฉันจะเทรน \'ครูฝึกระดับเซียน\' 5 คนด้วยตัวเอง และเปิดเฉพาะสาขาคุณภาพเท่านั้น คุณภาพเหนือปริมาณ"', zh: '🚫 保持控制：“没人像我这样教。我会亲自培训5名高级讲师，只经营顶级分校。质量胜于数量。”' }, consequence: { en: '✅ Boutique Quality. Your school becomes the "Harvard" of photography. Limited seats, high prices. Deep respect. Lower revenue than franchising, but higher legacy value.', th: '✅ คุณภาพระดับบูทีค โรงเรียนคุณกลายเป็น "ฮาร์วาร์ด" แห่งการถ่ายภาพ รับจำกัด ราคาสูง คนนับถือ รายได้น้อยกว่าแฟรนไชส์แต่มูลค่าตำนานสูงกว่า', zh: '✅ 精品质量。你的学校成为摄影界的“哈佛”。席位有限，价格高昂。深受尊重。收入低于特许经营，但遗产价值更高。' }, stats: { competence: 60, ethics: 50, leadership: 60, innovation: 30 } },
            { id: 'C', text: { en: '💻 Go Digital Only: "Physical schools are overhead heavy. Put everything into a Masterclass App subscription. $29/month."', th: '💻 ออนไลน์ล้วน: "โรงเรียนตึกมันต้นทุนจม เอาทุกอย่างใส่แอปรวมคอร์สรายเดือน $29/เดือน ดีกว่า"', zh: '💻 只做数字化：“实体学校开销大。把所有东西放进大师班App订阅。每月29美元。”' }, consequence: { en: 'Success. It\'s scalable and low risk. But piracy is rampant. You spend half your time sending cease-and-desist letters.', th: 'ความสำเร็จ ขยายง่าย เสี่ยงต่ำ แต่ของก๊อปเกลื่อน คุณเสียเวลาครึ่งนึงไปกับการไล่ฟ้องคนละเมิดลิขสิทธิ์', zh: '成功。可扩展且低风险。但盗版猖獗。你花一半时间发停止侵权信。' }, stats: { competence: 40, ethics: 30, leadership: 30, innovation: 60 } },
            { id: 'D', text: { en: '🤷 Sell & Exit: "Buy me out completely for $2 Million. You keep the name, I walk away. I want to paint watercolors."', th: '🤷 ขายขาดแล้วเลิก: "ซื้อขาดไปเลย $2 ล้าน คุณเอาชื่อไป ผมไปล่ะ อยากไปวาดสีน้ำเล่น"', zh: '🤷 出售并退出：“200万美元彻底买断我。名字归你，我走人。我想去画水彩画。”' }, consequence: { en: '🔚 The End... or New Beginning? You are rich and free. The school turns bad quickly without you, tarnishing your old name. But you don\'t care, you are on a beach.', th: '🔚 จุดจบ... หรือการเริ่มใหม่? รวยและอิสระ โรงเรียนแย่ลงอย่างไวเมื่อไม่มีคุณ ชื่อเสียหมด แต่คุณไม่สนหรอก นอนอยู่ริมหาด', zh: '🔚 结束……还是新的开始？你有钱且自由。没有你，学校很快变质，玷污了你的旧名声。但你不在乎，你在海滩上。' }, stats: { competence: 20, ethics: 30, leadership: 0, innovation: 10 } }
        ]
    },

    {
        id: 'pho_030',
        text: {
            en: '🎨 The Retouching Scandal: A famously "body positive" celebrity hires you. She asks you privately to "shave 20lbs off" in Photoshop but publically claims the photos are "100% natural and unedited." The Raw files leak. You are caught in the middle.',
            th: '🎨 ข่าวฉาวรีทัช: ดาราดังสาย "ภูมิใจในรูปร่าง" จ้างคุณ เธอกระซิบขอให้ "บีบออกสัก 20 ปอนด์" ในคอม แต่ตะโกนบอกสื่อว่ารูปนี้ "ธรรมชาติ 100% ไม่แต่ง" ไฟล์ Raw หลุดออกมา คุณซวยติดร่างแห',
            zh: '🎨 修图丑闻：一位著名的“身材积极”名人雇佣了你。她私下要求你在Photoshop里“减掉20磅”，但在公开场合声称照片是“100%自然未经编辑的”。Raw文件泄露。你被夹在中间。'
        },
        options: [
            { id: 'A', text: { en: '🤐 Protect the Client: "Deny everything. Say the Raw files are fakes. Take the heat for her. NDAs are sacred."', th: '🤐 ปกป้องลูกค้า: "ปฏิเสธทุกอย่าง บอกว่าไฟล์ Raw เป็นของปลอม ยอมรับกระสุนแทนเธอ NDA คือสิ่งศักดิ์สิทธิ์"', zh: '🤐 保护客户：“否认一切。说Raw文件是假的。为她挡枪。保密协议是神圣的。”' }, consequence: { en: '🛡️ Loyal but Liar. The industry knows you are lying. The public thinks you are a bad editor. But high-end celebs trust your discretion implicitly. You become the "Safe Space" for insecure stars.', th: '🛡️ ซื่อสัตย์แต่ขี้ฮก วงการรู้ว่าคุณโกหก คนทั่วไปคิดว่าคุณแต่งรูปห่วย แต่ดาราเบอร์ใหญ่เชื่อใจความปากหนักของคุณ คุณกลายเป็น "หลุมหลบภัย" ของดาราขี้กังวล', zh: '🛡️ 忠诚但撒谎。业内知道你在撒谎。公众认为你是个糟糕的编辑。但高端名人绝对信任你的谨慎。你成为缺乏安全感的明星的“安全空间”。' }, stats: { competence: 30, ethics: -20, leadership: 20, innovation: 20 } },
            { id: 'B', text: { en: '📢 Expose the Truth: "She asked for it. release the emails. I won\'t be called a liar. My integrity matters."', th: '📢 แฉความจริง: "เธอสั่งเอง ปล่อยอีเมลแฉเลย ฉันจะไม่ยอมโดนด่าว่าโกหก ศักดิ์ศรีฉันสำคัญกว่า"', zh: '📢 揭露真相：“是她要求的。公布邮件。我不会被人叫骗子。我的正直很重要。”' }, consequence: { en: '🔥 Bridge Burner. The public loves the tea. You get 100k new followers. BUT no celebrity will ever hire you again. You are "The Snitch."', th: '🔥 เผาสะพาน ชาวเน็ตชอบเผือก คุณได้ฟอลโลเวอร์เพิ่มแสนคน แต่ไม่มีดาราคนไหนจ้างคุณอีกเลย คุณมัน "คนปากสว่าง"', zh: '🔥 过河拆桥。公众喜欢吃瓜。你增加了10万粉丝。但再也没有名人会雇佣你了。你获得了一倍的名气，但也失去了客户。' }, stats: { competence: 40, ethics: 40, leadership: 10, innovation: 10 } },
            { id: 'C', text: { en: '😐 "Standard Industry Practice": "Issue a neutral statement. \'All commercial images undergo color grading and slight adjustments. We aimed to capture her best self.\'"', th: '😐 "มาตรฐานอุตสาหกรรม": "ออกแถลงการณ์กลางๆ \'ภาพโฆษณาทุกใบมีการปรับสีและแก้ไขเล็กน้อย เรามุ่งหวังจะนำเสนอตัวตนที่ดีที่สุดของเธอ\'"', zh: '😐 “行业标准做法”：“发表中立声明。‘所有商业图像都经过调色和微调。我们的目标是捕捉她最好的自我。’”' }, consequence: { en: '✅ Boring is Best. The news cycle moves on in 24 hours. You didn\'t confirm or deny. You survive with minor scratches.', th: '✅ น่าเบื่อคือดีที่สุด ข่าวเงียบไปใน 24 ชม. คุณไม่รับและไม่ปฏิเสธ รอดตัวไปโดยมีรอยขีดข่วนนิดหน่อย', zh: '✅ 无聊最好。新闻周期24小时就过了。你既不承认也不否认。你带着轻微的擦伤幸存下来。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 20 } },
            { id: 'D', text: { en: '🎨 Pivot to Authenticity: "Apologize for contributing to unrealistic standards. Vow to mark all future retouched images. Start a movement."', th: '🎨 พลิกสู่ความจริง: "ขอโทษที่มีส่วนสร้างค่านิยมเกินจริง สาบานว่าจะระบุภาพที่รีทัชทุกใบในอนาคต สร้างการเปลี่ยนแปลง"', zh: '🎨 转向真实：“为助长不切实际的标准道歉。发誓将来标记所有修图图像。发起一场运动。”' }, consequence: { en: '✅ Moral Leader. You lose the retouching gigs, but you gain massive respect from Gen Z and brands like Dove. You lead the "Real Beauty" wave.', th: '✅ ผู้นำจริยธรรม คุณเสียงานสายแต่งภาพ แต่ได้ใจ Gen Z และแบรนด์อย่าง Dove มหาศาล คุณนำกระแส "Real Beauty"', zh: '✅ 道德领袖。你失去了修图工作，但你获得了Z世代和多芬等品牌的极大尊重。你引领了“真实美”浪潮。' }, stats: { competence: 40, ethics: 70, leadership: 60, innovation: 50 } }
        ]
    },

    {
        id: 'pho_031',
        text: {
            en: '⚔️ The Assistant Rival: Your best assistant of 5 years quits. They open a studio across the street. Their website looks exactly like yours. They are contacting YOUR clients offering 20% lower rates. "I learned from the best," they say.',
            th: '⚔️ คู่แข่งศิษย์ก้นกุฏิ: ผู้ช่วยมือขวา 5 ปีของคุณลาออก ไปเปิดสตูดิโอฝั่งตรงข้าม เว็บไซต์เหมือนคุณเด๊ะ โทรหาลูกค้าของคุณเสนอราคาถูกกว่า 20% "ผมเรียนมาจากเทพอ่ะครับ" เขาอ้าง',
            zh: '⚔️ 助手对手：你用了5年的最好的助手辞职了。他们在街对面开了一家工作室。他们的网站看起来和你的一模一样。他们联系你的客户，提供低20%的价格。“我师从最好的，”他们说。'
        },
        options: [
            { id: 'A', text: { en: '😠 Legal Threat: "Cease and Desist! Intellectual property theft! I\'ll sue you into the ground for stealing my client list!"', th: '😠 ข่มขู่ทางกกฎหมาย: "หยุดการกระทันเดี๋ยวนี้! ขโมยทรัพย์สินทางปัญญา! ฉันจะฟ้องให้หมดตัวข้อหาขโมยรายชื่อลูกค้า!"', zh: '😠 法律威胁：“停止侵权！知识产权盗窃！我会因窃取客户名单起诉你到底！”' }, consequence: { en: '📉 Negative Energy. You spend money on lawyers. Clients get dragged into depositions and annoyed. You look bitter. The assistant plays the "bully victim."', th: '📉 พลังงานลบ เสียเงินค่าทนาย ลูกค้าโดนลากไปให้การและรำคาญ คุณดูขี้แพ้ชวนตี ไอผู้ช่วยก็เล่นบท "เหยื่อผู้ถูกรังแก"', zh: '📉 负能量。你把钱花在律师身上。客户被卷入证词录取并感到恼火。你看起来很痛苦。助手扮演“被欺负的受害者”。' }, stats: { competence: 30, ethics: 20, leadership: 10, innovation: 10 } },
            { id: 'B', text: { en: '🌊 Ignore & Elevate: "Let them fight for the scraps. I am raising my prices. If a client leaves for 20% off, they weren\'t my ideal client. I focus on quality."', th: '🌊 เมินแล้วบินสูง: "ปล่อยให้เขาแย่งเศษเนื้อไป ฉันจะขึ้นราคา ถ้าลูกค้าจะหนีเพราะส่วนลด 20% ก็แปลว่าไม่ใช่ลูกค้าเกรดฉัน ฉันเน้นคุณภาพ"', zh: '🌊 无视并提升：“让他们去争抢残羹冷以此。我在涨价。如果客户为了20%的折扣离开，他们不是我的理想客户。我专注于质量。”' }, consequence: { en: '✅ Boss Move. You lose the cheap clients (good riddance). Your brand moves upmarket. The assistant realizes low prices + high costs = bankruptcy. They close in a year.', th: '✅ วิถีบอส คุณเสียลูกค้าขี้เหนียว (ไปดีเถอะ) แบรนด์คุณขยับสู่ตลาดบน ผู้ช่วยซึ้งเลยว่า ราคาถูก + ต้นทุนสูง = เจ๊ง เขาปิดกิจการในหนึ่งปี', zh: '✅ 老板举措。你失去了廉价客户（好走不送）。你的品牌向高端市场移动。助手意识到低价 + 高成本 = 破产。他们一年后关门。' }, stats: { competence: 50, ethics: 50, leadership: 60, innovation: 30 } },
            { id: 'C', text: { en: '🤝 The Partnership Offer: "Walk across the street. \'Congrats! Why fight? Let\'s refer overload work to each other. You handle the $2k gigs, I handle the $10k gigs.\'"', th: '🤝 ยื่นข้อเสนอ: "เดินข้ามถนนไป \'ยินดีด้วย! จะทะเลาะกันทำไม? มาส่งงานล้นมือให้กันดีกว่า นายรับงาน $2k ไป ฉันรับงาน $10k เอง\'"', zh: '🤝 合伙提议：“走过街去。‘恭喜！为什么要打架？让我们互相推荐超负荷的工作。你接2000美元的活，我接1万美元的活。’”' }, consequence: { en: '✅ Eco-system. You create a feeder lawyer. You get commission on referrals. You maintain the "Master" status and help them survive. Classy.', th: '✅ ระบบนิเวศ คุณสร้างเครือข่ายลูกไล่ ได้ค่าคอมจากการส่งงาน คุณรักษาความเป็น "ปรมาจารย์" และช่วยให้เขารอด เหนือชั้น', zh: '✅ 生态系统。你建立了一个输送层。你从推荐中获得佣金。你保持“大师”地位并帮助他们生存。有格调。' }, stats: { competence: 50, ethics: 60, leadership: 70, innovation: 40 } },
            { id: 'D', text: { en: '💣 Sabotage: "Spread rumors they sell client photos to stock sites. Leave fake bad reviews."', th: '💣 บ่อนทำลาย: "ปล่อยข่าวลือว่ามันเอารูปลูกค้าไปขายในเว็บสต็อก เขียนรีวิวปลอมด่ามัน"', zh: '💣 蓄意破坏：“散布谣言说他们把客户照片卖给图片库网站。留下虚假的差评。”' }, consequence: { en: '💀 Petty & Dangerous. It might work short term, but karma is real. If caught, you are sued for defamation. It poisons your soul.', th: '💀 ใจแคบและอันตราย อาจได้ผลระยะสั้น แต่เวรกรรมมีจริง ถ้าโดนจับได้ โดนฟ้องหมิ่นประมาท จิตใจตกต่ำ', zh: '💀 卑鄙且危险。短期内可能有效，但报应是真的。如果被抓，你会被起诉诽谤。这毒害了你的灵魂。' }, stats: { competence: 20, ethics: -100, leadership: -10, innovation: 10 } }
        ]
    },

    {
        id: 'pho_032',
        text: {
            en: '📚 The Retrospective Book: Taschen wants to publish a coffee table book of your life\'s work. "30 Years of Light." It requires digging through dusty hard drives and film archives for 6 months. No shooting allowed during this time.',
            th: '📚 หนังสือรวมผลงาน: Taschen อยากตีพิมพ์สมุดภาพรวมผลงานชีวิตคุณ "30 ปีแห่งแสง" ต้องรื้อค้นฮาร์ดไดรฟ์ฝุ่นจับและฟิล์มเก่าๆ เป็นเวลา 6 เดือน ห้ามรับงานถ่ายช่วงนี้',
            zh: '📚 回顾摄影集：Taschen想出版一本关于你毕生作品的咖啡桌读物。《光影30年》。这需要挖掘布满灰尘的硬盘和胶片档案，耗时6个月。在此期间不允许拍摄。'
        },
        options: [
            { id: 'A', text: { en: '📖 Do It: "This is my legacy. A book lasts longer than Instagram. I\'ll take the sabbatical."', th: '📖 ทำสิ: "นี่คือตำนานของฉัน หนังสืออยู่คงทนกว่าอินสตาแกรม ฉันจะพักงานมาทำ"', zh: '📖 做：“这是我的遗产。书比Instagram更持久。我会休假去做。”' }, consequence: { en: '✅ Legacy Cemented. The book wins awards. You are now entered into history. When you return to shooting, your day rate triples because you are a "Book Author."', th: '✅ ตอกย้ำตำนาน หนังสือได้รางวัล คุณถูกจารึกในประวัติศาสตร์ พอกลับมารับงาน ค่าตัวคูณสามในฐานะ "ผู้เขียนหนังสือ"', zh: '✅ 遗产确立。这本书获奖了。你现在载入史册。当你重返拍摄时，你的日薪翻了三倍，因为你是“书作者”。' }, stats: { competence: 60, ethics: 40, leadership: 40, innovation: 20 } },
            { id: 'B', text: { en: '🏃 Delegate: "Hire an archivist to curate it. I\'ll write the intro and approve the final layout. I need to keep shooting."', th: '🏃 มอบหมายงาน: "จ้างบรรณารักษ์มาคัดเลือก ฉันเขียนคำนำและอนุมัติเลย์เอาต์สุดท้าย ฉันต้องถ่ายงานต่อ"', zh: '🏃 委派：“聘请档案管理员来策展。我会写序言并批准最终排版。我需要继续拍摄。”' }, consequence: { en: '😐 Disconnected. The book comes out, but it feels impersonal. Critics say "It lacks the artist\'s touch in curation." It sells okay, but not great.', th: '😐 ขาดการเชื่อมโยง หนังสือออกมาแต่ดูห่างเหิน นักวิจารณ์บอก "ขาดสัมผัสของศิลปินในการคัดเลือก" ขายได้แหละแต่ไม่เปรี้ยง', zh: '😐 脱节。书出版了，但感觉没有人情味。评论家说“策展缺乏艺术家的触感。”卖得还可以，但不是很好。' }, stats: { competence: 40, ethics: 30, leadership: 40, innovation: 20 } },
            { id: 'C', text: { en: '🚫 Decline: "I\'m not dead yet! Retrospectives are for retired people. I\'m still creating my best work."', th: '🚫 ปฏิเสธ: "ฉันยังไม่ตาย! รวมผลงานมันสำหรับคนเกษียณ ฉันยังสร้างงานที่ดีที่สุดอยู่นะ"', zh: '🚫 拒绝：“我还没死呢！回顾展是给退休人员的。我还在创作我最好的作品。”' }, consequence: { en: '🔄 Energy Boost. You feel young. You shoot a new groundbreaking series instead. Taschen calls back in 5 years wanting a bigger book.', th: '🔄 บูสต์พลัง คุณรู้สึกหนุ่มแน่น คุณถ่ายงานชุดใหม่ที่ล้ำกว่าเดิม Taschen โทรมาใหม่ใน 5 ปีขอทำเล่มใหญ่กว่าเดิม', zh: '🔄 能量提升。你感觉年轻。你拍摄了一个新的开创性系列。Taschen 5年后回电想要一本更大的书。' }, stats: { competence: 50, ethics: 30, leadership: 30, innovation: 50 } },
            { id: 'D', text: { en: '💻 Digital Archive: "Who buys books? I\'ll build a 3D immersive web museum of my work. Accessible to everyone, forever."', th: '💻 อาร์ไกฟ์ดิจิทัล: "ใครเขาซื้อหนังสือกัน? ฉันจะสร้างพิพิธภัณฑ์เว็บ 3D ดำดิ่งสู่ผลงานฉัน เข้าถึงได้ทุกคน ตลอดไป"', zh: '💻 数字档案馆：“谁买书？我会为我的作品建立一个3D沉浸式网络博物馆。所有人永远均可访问。”' }, consequence: { en: '⚠️ Cool but Niche. Tech blogs love it. Art collectors ignore it. You miss the prestige of the physical object on a shelf.', th: '⚠️ เจ๋งแต่เฉพาะกลุ่ม บล็อกเทคโนโลยีชอบ แต่นักสะสมงานศิลป์เมิน คุณพลาดความขลังของวัตถุที่วางบนชั้นวาง', zh: '⚠️ 酷但小众。科技博客很喜欢。艺术收藏家忽略它。你错过了书架上实物的威望。' }, stats: { competence: 40, ethics: 30, leadership: 30, innovation: 70 } }
        ]
    },

    {
        id: 'pho_033',
        text: {
            en: '🏥 The Health Crisis: 20 years of carrying heavy gear involves a price. Your doctor says: "Herniated disc. Surgery or stop carrying heavy cameras." You are a location photographer who climbs mountains.',
            th: '🏥 วิกฤตสุขภาพ: 20 ปีที่แบกของหนักต้องจ่ายราคา หมอบอกว่า: "หมอนรองกระดูกทับเส้น ผ่าตัดหรือเลิกแบกกล้องหนัก" คุณเป็นช่างภาพสายลุยที่ปีนเขาถ่ายงานนะ',
            zh: '🏥 健康危机：20年背负重型器材是有代价的。你的医生说：“椎间盘突出。手术或者停止背重型相机。”你是一名登山的外景摄影师。'
        },
        options: [
            { id: 'A', text: { en: '🔪 Surgery & Rehab: "I will fix the machine. Surgery, 6 months rehab, then back to the mountains. I am a warrior."', th: '🔪 ผ่าแล้วกายภาพ: "ซ่อมเครื่องจักรซะ ผ่าตัด พักฟื้น 6 เดือน แล้วกลับไปปีนเขา ฉันมันนักรบ"', zh: '🔪 手术与康复：“我会修好机器。手术，6个月康复，然后回到山上。我是战士。”' }, consequence: { en: '✅/⚠️ Hard Road. You survive, but you are never quite the same. You have pain. But your determination inspires others. Grit +100.', th: '✅/⚠️ ทางวิบาก รอดมาได้แต่ไม่เหมือนเดิมเป๊ะ ปวดยังมีอยู่ แต่ความมุ่งมั่นคุณเป็นแรงบันาลใจให้คนอื่น ความอึด +100', zh: '✅/⚠️ 艰难之路。你活下来了，但你再也不是从前的你了。你会痛。但你的决心激励了他人。毅力 +100。' }, stats: { competence: 40, ethics: 40, leadership: 50, innovation: 20 } },
            { id: 'B', text: { en: '📷 Switch to Mirrorless/Lightweight: "Sell the medium format. Buy the smallest, lightest gear possible. Change my style to fit the gear."', th: '📷 เปลี่ยนมาใช้ Mirrorless/ตัวเบา: "ขายมีเดียมฟอร์แมตทิ้ง ซื้อตัวเล็กสุดเบาสุด เปลี่ยนสไตล์ให้เข้ากับกล้อง"', zh: '📷 切换到无反/轻量级：“卖掉中画幅。买尽可能最小、最轻的器材。改变我的风格以适应器材。”' }, consequence: { en: '✅ Adaptation. You realize gear didn\'t make the photo. You feel liberated by the light kit. Your back heals naturally. You climb higher and faster.', th: '✅ การปรับตัว คุณตระหนักว่ากล้องไม่ได้ทำให้รูปสวย คุณรู้สึกอิสระกับชุดเบาๆ หลังหายเองตามธรรมชาติ ปีนได้สูงขึ้นและเร็วขึ้น', zh: '✅ 适应。你意识到器材并不决定照片。轻便装备让你感到解放。你的背自然愈合了。你爬得更高更快。' }, stats: { competence: 50, ethics: 40, leadership: 40, innovation: 50 } },
            { id: 'C', text: { en: '🎓 Become a Studio Director: "My climbing days are over. I will direct huge commercial sets from a chair. Point lasers and shout instructions."', th: '🎓 เป็นผู้กำกับสตูดิโอ: "วันเวลาปีนเขาจบแล้ว ฉันจะกำกับเซตโฆษณาใหญ่ๆ จากเก้าอี้ ชี้เลเซอร์แล้วตะโกนสั่ง"', zh: '🎓 成为工作室总监：“我的登山日子结束了。我会坐在椅子上指挥大型商业布景。指着激光笔喊指令。”' }, consequence: { en: '💰 Career Evolution. You make more money. Your body is grateful. You miss the fresh air, but you love the control.', th: '💰 วิวัฒนาการอาชีพ ได้เงินเยอะขึ้น ร่างกายขอบคุณ คิดถึงอากาศบริสุทธิ์บ้างแต่ก็ชอบอำนาจสั่งการ', zh: '💰 职业进化。你赚了更多钱。你的身体很感激。你怀念新鲜空气，但你喜欢掌控一切。' }, stats: { competence: 50, ethics: 30, leadership: 60, innovation: 30 } },
            { id: 'D', text: { en: '🏋️ Sherpa Strategy: "I keep the heavy gear. I hire a young strong assistant to carry EVERYTHING. I carry nothing but a light meter."', th: '🏋️ กลยุทธ์เชอร์ปา: "ฉันจะใช้กล้องหนักต่อ จ้างผู้ช่วยหนุ่มๆ แข็งแรงๆ มาแบก \'ทุกอย่าง\' ฉันถือแค่เครื่องวัดแสง"', zh: '🏋️ 夏尔巴策略：“我保留重型器材。我雇一个年轻强壮的助手背负‘所有东西’。我只拿一个测光表。”' }, consequence: { en: '✅ Boss Mode. It costs money, but it works. You realize you should have done this 10 years ago to save energy for shooting.', th: '✅ โหมดบอส เปลืองเงินแต่เวิร์ก คุณรู้งี้น่าทำตั้ง 10 ปีก่อน จะได้เก็บแรงไว้ถ่ายรูป', zh: '✅ 老板模式。这要花钱，但行得通。你意识到你应该在10年前就这样做，以节省拍摄精力。' }, stats: { competence: 40, ethics: 30, leadership: 50, innovation: 20 } }
        ]
    },

    {
        id: 'pho_034',
        text: {
            en: '⚖️ The "Me Too" Witness: You are on a high-profile set. You witness the famous director harassing a young model. Everyone ignores it to protect their jobs. If you speak up, you might be blacklisted by the agency.',
            th: '⚖️ พยาน "Me Too": คุณอยู่ในกองถ่ายระดับโลก เห็นผู้กำกับดังลวนลามนางแบบใหม่ ทุกคนทำเป็นเมินเพื่อรักษาเก้าอี้ตัวเอง ถ้าคุณพูด คุณอาจโดนเอเจนซี่แบน',
            zh: '⚖️ “Me Too”目击者：你在一个备受瞩目的片场。你目睹了著名导演骚扰一位年轻模特。每个人为了保住工作都对此视而不见。如果你大声疾呼，你可能会被该机构列入黑名单。'
        },
        options: [
            { id: 'A', text: { en: '🛑 Intervene Immediately: "Strop the shoot! \'That is not okay.\' Pull the model away. Call the agent."', th: '🛑 แทรกแซงทันที: "หยุดกอง! \'ทำแบบนั้นไม่ได้ครับ\' ดึงนางแบบออกมา โทรหาเอเจนซี่"', zh: '🛑 立即干预：“停止拍摄！‘这不可以。’把模特拉开。给经纪人打电话。”' }, consequence: { en: '✅/⚠️ Hero/Martyr. You are fired from the set. The director badmouths you. BUT rumors spread about your bravery. Models feel safe with you. You become the hero of the new generation.', th: '✅/⚠️ ฮีโร่/ผู้พลีชีพ คุณโดนไล่ออก ผู้กำกับใส่ร้ายคุณ แต่เขาเล่าลือกันว่าคุณกล้าหาญ นางแบบรู้สึกปลอดภัยกับคุณ คุณกลายเป็นฮีโร่ของคนรุ่นใหม่', zh: '✅/⚠️ 英雄/烈士。你被剧组解雇了。导演说你坏话。但关于你勇敢的谣言传开了。模特们和你在一起感到安全。你成为新一代的英雄。' }, stats: { competence: 40, ethics: 100, leadership: 80, innovation: 20 } },
            { id: 'B', text: { en: '🤫 Quiet Report: "Finish the day responsibly. Document everything. Report it to HR and the Model Alliance anonymously afterward."', th: '🤫 รายงานลับ: "ทำงานให้จบวันอย่างรับผิดชอบ จดบันทึกทุกอย่าง รายงาน HR และสมาพันธ์นางแบบแบบไม่ระบุชื่อทีหลัง"', zh: '🤫 悄悄以此：报告“负责任地结束这一天。记录一切。事后匿名向人力资源部和模特联盟报告。”' }, consequence: { en: '⚖️ Effective? Maybe. The investigation takes months. You kept your job, but you feel like a coward for not stopping it in the moment. The director eventually gets fired.', th: '⚖️ ได้ผลไหม? อาจจะ สอบสวนกันเป็นเดือน คุณรักษางานไว้ได้ แต่รู้สึกเหมือนขี้ขลาดที่ไม่หยุดมันตอนนั้น สุดท้ายผู้กำกับโดนไล่ออก', zh: '⚖️ 有效吗？也许。调查耗时数月。你保住了工作，但你觉得自己是个懦夫，没有在那一刻阻止它。导演最终被解雇了。' }, stats: { competence: 30, ethics: 40, leadership: 20, innovation: 10 } },
            { id: 'C', text: { en: '🙈 Ignore: "Not my circus, not my monkeys. I need this paycheck. The model industry is just like this."', th: '🙈 เมิน: "ไม่ใช่เรื่องของฉัน ฉันต้องใช้เงิน วงการนางแบบมันก็งี้แหละ"', zh: '🙈 无视：“此地无银三百两。我需要这份薪水。模特界就是这样。”' }, consequence: { en: '💀 Soul Rot. You keep the job. But you become part of the problem. Years later, a documentary exposes the director and lists you as an "enabler." Shame.', th: '💀 จิตใจเน่าเฟะ คุณมีงานทำ แต่คุณเป็นส่วนหนึ่งของปัญหา หลายปีต่อมา สารคดีแฉผู้กำกับและระบุชื่อคุณว่าเป็น "ผู้สมรู้ร่วมคิด" น่าละอาย', zh: '💀 灵魂腐烂。你保住了工作。但你成了问题的一部分。多年后，一部纪录片揭露了这位导演，并将你列为“帮手”。羞耻。' }, stats: { competence: 20, ethics: -50, leadership: -20, innovation: 0 } },
            { id: 'D', text: { en: '📸 Comfort the Model: "Wait until breaks. Check on her. \'Are you okay? Do you want to leave? I support you.\' Let her decide."', th: '📸 ปลอบนางแบบ: "รอตอนพัก เข้าไปถาม \'โอเคไหม? อยากกลับไหม? ผมสนับสนุนคุณนะ\' ให้เธอตัดสินใจ"', zh: '📸 安慰模特：“等到休息时间。去看看她。‘你还好吗？你想离开吗？我支持你。’让她决定。”' }, consequence: { en: '✅ Supporter. She appreciates it. She finishes the shoot but leaves the industry. She remains a friend. You did what you could without detonating.', th: '✅ ผู้สนับสนุน เธอซึ้งใจ เธอถ่ายจนจบแต่ลาออกจากวงการ เธอยังเป็นเพื่อนคุณ คุณทำสิ่งที่ทำได้โดยไม่ระเบิดตู้ม', zh: '✅ 支持者。她很感激。她完成了拍摄但离开了这个行业。她依然是朋友。你在不引爆局面的情况下尽力而为了。' }, stats: { competence: 40, ethics: 60, leadership: 30, innovation: 20 } }
        ]
    },

    {
        id: 'pho_035',
        text: {
            en: '🌅 The Retirement Plan: You are 60. You have a archive of 1 million photos. Getty Images offers to buy your entire copyright for $1.5 Million. You lose all rights to your life\'s work, but you get cash now.',
            th: '🌅 แผนเกษียณ: อายุ 60 แล้ว มีรูปในคลัง 1 ล้านใบ Getty Images ขอซื้อลิขสิทธิ์ทั้งหมด $1.5 ล้าน คุณเสียสิทธิ์ในงานทั้งชีวิต แต่ได้เงินก้อนตอนนี้เลย',
            zh: '🌅 退休计划：你60岁了。你有100万张照片的档案。Getty Images出价150万美元购买你的全部版权。你失去了毕生作品的所有权利，但现在能拿到现金。'
        },
        options: [
            { id: 'A', text: { en: '💰 Sell Out: "Take the money. I can\'t eat copyrights. $1.5M buys a nice villa in Italy. Goodbye photos."', th: '💰 ขายทิ้ง: "เอาเงินมา กินลิขสิทธิ์ไม่อิ่มหรอก $1.5M ซื้อวิลล่าในอิตาลีสบาย ลาก่อนพวกรูปถ่าย"', zh: '💰 卖掉：“拿钱。版权不能当饭吃。150万美元可以在意大利买栋漂亮的别墅。再见照片。”' }, consequence: { en: '✅ Comfortable End. You retire in luxury. Sometimes you see your photo on a billboard and feel a pang of loss, but the Chianti tastes good. Win.', th: '✅ จบแบบสบาย เกษียณอย่างหรู บางทีเห็นรูปตัวเองบนป้ายโฆษณาก็ใจหาย นิดๆ แต่ไวน์เคียนติมันอร่อยดี ชนะ', zh: '✅ 舒适的结局。你奢侈地退休了。有时你在广告牌上看到你的照片会感到一丝失落，但基安蒂红酒味道不错。赢了。' }, stats: { competence: 0, ethics: 0, leadership: 0, innovation: 0 } },
            { id: 'B', text: { en: '🏛️ Donate to Museum: "Donate the archive to the Library of Congress. Tax write-off + Legacy within the public domain. Money isn\'t everything."', th: '🏛️ บริจาคเข้าพิพิธภัณฑ์: "บริจาคให้หอสมุดแห่งชาติ ลดหย่อนภาษี + เป็นสมบัติสาธารณะ เงินไม่ใช่ทุกอย่าง"', zh: '🏛️ 捐赠给博物馆：“把档案捐赠给国会图书馆。抵税 + 公共领域的遗产。钱不是一切。”' }, consequence: { en: '✅ National Treasure. You aren\'t rich, but you are immortal. Researchers use your work for centuries. A noble end.', th: '✅ สมบัติชาติ ไม่รวยแต่เป็นอมตะ นักวิจัยใช้ผลงานคุณไปอีกหลายศตวรรษ การจบแบบผู้ดี', zh: '✅ 国宝。你不富有，但你不朽。研究人员几个世纪以来都在使用你的作品。高尚的结局。' }, stats: { competence: 50, ethics: 80, leadership: 60, innovation: 20 } },
            { id: 'C', text: { en: '👶 Pass to Kids: "Keep the rights. Teach my daughter to manage the licensing. Create a family trust. Generational wealth."', th: '👶 ส่งต่อให้ลูก: "เก็บลิขสิทธิ์ไว้ สอนลูกสาวให้บริหารการขายใบอนุญาต ตั้งกองทุนครอบครัว ความมั่งคั่งส่งต่อรุ่นสู่รุ่น"', zh: '👶 传给孩子：“保留权利。教我女儿管理许可。建立家族信托。世代财富。”' }, consequence: { en: '✅ Dynasty. Your daughter manages it well. The archive generates $100k/year forever. You leave something real behind.', th: '✅ ราชวงศ์ ลูกสาวดูแลได้ดี คลังภาพทำเงินปีละ $100k ตลอดไป คุณทิ้งของจริงไว้ให้ดูต่างหน้า', zh: '✅ 王朝。你女儿管理得很好。档案每年产生10万美元的收入直到永远。你留下了一些真实的东西。' }, stats: { competence: 40, ethics: 50, leadership: 50, innovation: 30 } },
            { id: 'D', text: { en: '🔥 Burn It: "My art dies with me. I don\'t want it used for dog food ads in 2050. I delete everything."', th: '🔥 เผาทิ้ง: "งานศิลป์ตายไปพร้อมฉัน ฉันไม่ยอมให้มันไปอยู่บนโฆษณาอาหารหมาปี 2050 หรอก ลบให้หมด"', zh: '🔥 烧掉它：“我的艺术随我而亡。我不希望它在2050年被用在狗粮广告上。我删除了所有东西。”' }, consequence: { en: '💀 Kafkaesque. The art world is horrified. But your legend grows because no one can see the work anymore. "The Lost Archives." You die a mysterious myth.', th: '💀 แบบคาฟคา วงการศิลปะช็อก แต่ตำนานคุณยิ่งใหญ่ขึ้นเพราะไม่มีใครได้เห็นงานอีกแล้ว "คลังภาพที่สาบสูญ" คุณตายไปพร้อมกับตำนานอันลึกลับ', zh: '💀 卡夫卡式。艺术界感到恐惧。但你的传奇在增长，因为不再有人能看到这些作品。“丢失的档案。”你死成了一个神秘的神话。' }, stats: { competence: 0, ethics: 0, leadership: 0, innovation: 100 } }
        ]
    },

    // SECTION 4: FUTURE TECH & ELDER STATESMAN (Questions 36-50)

    {
        id: 'pho_036',
        text: {
            en: '🤖 The AI Co-Author: A tech startup invites you to train an AI model on your 1 million photos. They will call it "The [Your Name] Filter." You get a 5% royalty on every image generated. It could make your style immortal.',
            th: '🤖 ลูกมือ AI: สตาร์ทอัพเทคชวนคุณมาเทรนโมเดล AI ด้วยรูป 1 ล้านใบของคุณ เขาจะตั้งชื่อว่า "The [ชื่อคุณ] Filter" คุณจะได้ค่ารอยัลตี้ 5% จากทุกรูปที่ถูกสร้าง มันจะทำให้สไตล์คุณเป็นอมตะ',
            zh: '🤖 AI共同作者：一家科技初创公司邀请你用你的100万张照片训练一个AI模型。他们将称之为“[你的名字]滤镜”。你将从生成的每张图像中获得5%的版税。这可以让你的风格永垂不朽。'
        },
        options: [
            { id: 'A', text: { en: '🤝 Hand Over the Keys: "Yes. I want my style to live forever. Digital immortality is the goal."', th: '🤝 ยอมยกกุญแจให้: "ตกลง ฉันอยากให้สไตล์ของฉันอยู่ตลอดไป ความเป็นอมตะดิจิทัลคือเป้าหมาย"', zh: '🤝 交出钥匙：“是的。我希望我的风格永远流传。数字不朽是目标。”' }, consequence: { en: '✅ Digital Legacy. You make millions while you sleep. Every teenager uses your lighting style. You are the most famous photographer in the world, even if you never touch a camera again.', th: '✅ ตำนานดิจิทัล คุณทำเงินล้านได้ตอนหลับ วัยรุ่นทุกคนใช้สไตล์แสงของคุณ คุณคือช่างภาพที่ดังที่สุดในโลก แม้จะไม่ได้จับกล้องอีกเลยก็ตาม', zh: '✅ 数字遗产。你睡觉时也能赚几百万。每个青少年都在使用你的布光风格。你是世界上最著名的摄影师，即使你再也不碰相机。' }, stats: { competence: 20, ethics: 30, leadership: 40, innovation: 100 } },
            { id: 'B', text: { en: '🚫 Refuse: "My style is my soul. It cannot be reduced to an algorithm. I decline."', th: '🚫 ปฏิเสธ: "สไตล์คือจิตวิญญาณของฉัน มันลดทอนเป็นอัลกอริทึมไม่ได้หรอก ฉันไม่เอาด้วย"', zh: '🚫 拒绝：“我的风格是我的灵魂。它不能被简化为算法。我拒绝。”' }, consequence: { en: '✅ Artistic Purity. You remain a legend for humans, but you become irrelevant to the new generation who only knows AI filters. You are the "Last of the Greats."', th: '✅ ความบริสุทธิ์ทางศิลปะ คุณยังเป็นตำนานสำหรับมนุษย์ แต่เริ่มเลือนหายไปสำหรับคนรุ่นใหม่ที่รู้จักแต่ฟิลเตอร์ AI คุณคือ "คนสุดท้ายของรุ่นใหญ่"', zh: '✅ 艺术纯粹。你仍然是人类心目中的传奇，但对于只知道AI滤镜的新一代来说，你变得无关紧要。你是“最后的伟人”。' }, stats: { competence: 60, ethics: 60, leadership: 40, innovation: 10 } },
            { id: 'C', text: { en: '⚖️ Negotiate Control: "I will do it, but I must approve the training data and I want 20%. I want to be the Chief Creative Officer of the AI."', th: '⚖️ ต่อรองอำนาจ: "เอาสิ แต่ฉันต้องเป็นคนอนุมัติข้อมูลที่ใช้เทรน และขอ 20% ฉันจะเป็นประธานฝ่ายสร้างสรรค์ของ AI นี้เอง"', zh: '⚖️ 谈判控制：“我会做，但我必须批准训练数据，而且我要20%的版税。我想成为AI的首席创意官。”' }, consequence: { en: '✅ Power Play. You become a tech mogul. You lead the transition from manual to prompt-based photography. You are respected by both tech and art worlds.', th: '✅ เหนือเกม คุณกลายเป็นเจ้าพ่อเทค ผู้นำการเปลี่ยนผ่านจากช่างภาพมืออาชีพเป็นระดับสั่งการ คุณได้รับการยอมรับจากทั้งโลกอาร์ตและโลกเทค', zh: '✅ 权力博弈。你成为科技大亨。你引领了从手动摄影到基于提示的摄影的转型。你受到科技界和艺术界的尊重。' }, stats: { competence: 50, ethics: 40, leadership: 70, innovation: 80 } },
            { id: 'D', text: { en: '🕵️ Secret sabotager: "Give them the files, but poison the metadata so the AI results look slightly \'off\' without them knowing why."', th: '🕵️ วางยา: "เอาไฟล์ให้เขาไปเถอะ แต่แอบแก้ Metadata ให้ AI มันออกมาเพี้ยนๆ นิดๆ โดยที่เขาไม่รู้สาเหตุ"', zh: '🕵️ 秘密破坏：“把文件给他们，但污染元数据，让AI生成的结果看起来有点“不对劲”，而他们不知道原因。”' }, consequence: { en: '💀 Bitter End. You get the money, but the project fails. You didn\'t protect your legacy; you just damaged the progress of tech. You feel petty.', th: '💀 จบแบบขื่นขม ได้เงินมาแต่โปรเจกต์พัง คุณไม่ได้ปกป้องผลงาน แต่ดันไปขวางโลกเทค รู้สึกตัวเองใจแคบ', zh: '💀 痛苦的结局。你拿到了钱，但项目失败了。你没有保护你的遗产；你只是破坏了技术的进步。你感到很卑鄙。' }, stats: { competence: 30, ethics: -50, leadership: 0, innovation: 20 } }
        ]
    },

    {
        id: 'pho_037',
        text: {
            en: '👓 The VR Gallery: A museum in Dubai wants to build a Virtual Reality experience where people "walk through" your 3D-scanned sets and watch you work. It costs $1 Million to produce. They want you to fund 50%.',
            th: '👓 แกลเลอรี่ VR: พิพิธภัณฑ์ในดูไบอยากสร้างประสบการณ์ VR ที่คนสามารถ "เดินทะลุ" เซตถ่ายภาพ 3D ของคุณและดูคุณทำงานได้ ค่าโปรดักชั่น $1 ล้าน เขาให้คุณช่วยออก 50%',
            zh: '👓 VR画廊：迪拜的一家博物馆想要建立一个虚拟现实体验，让人们“穿行”于你的3D扫描布景，并看你工作。制作成本为100万美元。他们希望你出资50%。'
        },
        options: [
            { id: 'A', text: { en: '💰 Invest: "It\'s an investment in my brand. 500k is a lot, but this will make me the most famous living photographer."', th: '💰 ลงทุน: "มันคือการลงทุนในแบรนด์ $500k มันเยอะนะ แต่สิ่งนี้จะทำให้ฉันเป็นช่างภาพที่ดังที่สุดที่ยังมีชีวิตอยู่"', zh: '💰 投资：“这是对我的品牌的投资。50万是一大笔钱，但这将使我成为当世最著名的摄影师。”' }, consequence: { en: '✅ Success. The exhibition goes viral. Tourists flock to the VR experience. You make your money back in ticket sales and become a global icon.', th: '✅ สำเร็จ นิทรรศการกลายเป็นไวรัล นักท่องเที่ยวแห่มาดู VR คุณได้ทุนคืนจากค่าตั๋วและกลายเป็นไอคอนระดับโลก', zh: '✅ 成功。展览爆火。游客涌向VR体验。你从门票收入中收回了成本，并成为了全球偶像。' }, stats: { competence: 40, ethics: 30, leadership: 50, innovation: 90 } },
            { id: 'B', text: { en: '🚫 Refuse: "Art should be experienced in person, not through a headset. I\'m not a theme park attraction."', th: '🚫 ปฏิเสธ: "ศิลปะควรสัมผัสด้วยตัวเอง ไม่ใช่ผ่านแว่นตา ฉันไม่ใช่เครื่องเล่นในสวนสนุกนะ"', zh: '🚫 拒绝：“艺术应该亲自体验，而不是通过头戴设备。我不是主题公园的景点。”' }, consequence: { en: '✅ Integrity. You stay true to your roots. Your old-school fans love you for it. You missed the tech wave, but your "analog" value goes up.', th: '✅ ศักดิ์ศรี คุณซื่อสัตย์กับรากเหง้า แฟนรุ่นเก่ารักคุณมาก คุณพลาดกระแสเทค แต่มูลค่าความ "อนาล็อก" ของคุณพุ่งกระฉูด', zh: '✅ 正直。你保持了初心。你的老派粉丝为此排队支持你。你错过了技术浪潮，但你的“模拟”价值上升了。' }, stats: { competence: 40, ethics: 50, leadership: 30, innovation: 10 } },
            { id: 'C', text: { en: '🤝 Counter-offer: "I won\'t pay cash, but I will give you full access to my archives and help design it. You find corporate sponsors for the rest."', th: '🤝 ยื่นข้อเสนอใหม่: "ฉันไม่จ่ายเงินสด แต่จะให้เข้าถึงคลังภาพทั้งหมดและช่วยออกแบบให้ นายไปหาค่ายักษ์ใหญ่มาเป็นสปอนเซอร์ส่วนที่เหลือเอาเอง"', zh: '🤝 反提议：“我不付现金，但我会让你完全访问我的档案并协助设计。其余部分由你寻找企业赞助。”' }, consequence: { en: '✅ Smart Business. A tech company sponsors it. You get the VR museum for free and keep your cash. Leadership 100.', th: '✅ ฉลาดเกมโกง บริษัทเทคยอมเป็นสปอนเซอร์ คุณได้พิพิธภัณฑ์ VR ฟรีๆ แถมเก็บเงินสดไว้ได้ ค่าภาวะผู้นำ 100', zh: '✅ 精明的生意。一家科技公司赞助了它。你免费获得VR博物馆并保留了现金。领导力 100。' }, stats: { competence: 50, ethics: 40, leadership: 80, innovation: 60 } },
            { id: 'D', text: { en: '📱 Low-budget Version: "Let\'s just do an Instagram filter instead. It\'s cheaper and reaches more people."', th: '📱 เวอร์ชั่นประหยัด: "ทำแค่ฟิลเตอร์ Instagram พอ ประหยัดกว่าและคนเห็นเยอะกว่าด้วย"', zh: '📱 低成本版本：“我们还是做一个Instagram滤镜吧。更便宜，受众更广。”' }, consequence: { en: '😐 Cheapened. It looks like every other filter. The prestige of the Dubai museum is lost. You missed a chance for greatness for the sake of safety.', th: '😐 เกรดตก มันดูเหมือนฟิลเตอร์ทั่วไป เสียชื่อที่จะได้ลงพิพิธภัณฑ์ดูไบ คุณพลาดโอกาสยิ่งใหญ่เพราะกลัวความเสี่ยง', zh: '😐 廉价化。它看起来和所有其他滤镜一样。迪拜博物馆的威望丧失了。你为了安全错过了伟大的机会。' }, stats: { competence: 30, ethics: 30, leadership: 20, innovation: 40 } }
        ]
    },

    {
        id: 'pho_038',
        text: {
            en: '🌌 The Space Commission: Elon Musk (or a similar billionaire) wants you to take a camera on a SpaceX rocket to photograph the moon from orbit for a huge sum. It\'s dangerous and you have to train for 3 months like an astronaut.',
            th: '🌌 ภารกิจอวกาศ: อีลอน มัสก์ (หรือมหาเศรษฐีแนวๆ นั้น) อยากให้คุณพกกล้องขึ้นยาน SpaceX ไปถ่ายรูปดวงจันทร์จากวงโคจรด้วยเงินก้อนโต มันอันตรายและคุณต้องฝึกหนัก 3 เดือนแบบนักบินอวกาศ',
            zh: '🌌 太空委讬：埃隆·马斯克（或类似的亿万富翁）想让你带上相机乘坐SpaceX火箭，在轨道上拍摄月球，报酬丰厚。这很危险，你必须像宇航员一样训练3个月。'
        },
        options: [
            { id: 'A', text: { en: '🚀 Go to Space: "I want the ultimate perspective. The ultimate shot. Sign me up."', th: '🚀 ไปอวกาศ: "ฉันต้องการมุมมองที่สุดยอดที่สุด รูปที่เหนือที่สุด เซ็นชื่อเลย"', zh: '🚀 前往太空：“我想要终极视野。终极照片。给我报名。”' }, consequence: { en: '✅ Historical Shot. You take the most famous photo of the century. You are an astronaut-photographer. Your name is in history books forever. Innovation 100.', th: '✅ รูปประวัติศาสตร์ คุณถ่ายรูปที่ดังที่สุดแห่งศตวรรษ คุณคือนักบินอวกาศช่างภาพ ชื่อคุณจะอยู่ในตำนานตลอดไป ค่า ‘นวัตกรรม’ 100', zh: '✅ 历史性照片。你拍下了本世纪最著名的照片。你是一名宇航员摄影师。你的名字将永远留在历史书中。创新指标 100。' }, stats: { competence: 60, ethics: 30, leadership: 60, innovation: 100 } },
            { id: 'B', text: { en: '🚫 Refuse: "The earth has enough beauty. I don\'t need to risk my life for a billionaire\'s ego. I\'ll stay on the ground."', th: '🚫 ปฏิเสธ: "โลกนี้สวยงามพอแล้ว ฉันไม่จำเป็นต้องเอาชีวิตไปเสี่ยงเพื่อความสะใจของมหาเศรษฐี ขอนั่งอยู่บนดินนี่แหละ"', zh: '🚫 拒绝：“地球已经够美了。我不需要为了亿万富翁的虚荣心冒险。我留在地面上。”' }, consequence: { en: '✅ Wisdom. You avoid a potential rocket explosion (it actually explodes, but with a robot on board). You live to shoot another day. People respect your groundedness.', th: '✅ ความสุขุม คุณรอดจากการระเบิดของจรวด (มันระเบิดจริงๆ แต่ตอนนั้นมีแค่หุ่นยนต์) คุณมีชีวิตอยู่ถ่ายรูปต่อไป คนนับถือความติดดินของคุณ', zh: '✅ 智慧。你避免了潜在的火箭爆炸（它确实爆炸了，但当时载的是机器人）。你活着还可以继续拍摄。人们尊重你的脚踏实地。' }, stats: { competence: 40, ethics: 50, leadership: 40, innovation: 10 } },
            { id: 'C', text: { en: '🤝 Send an Associate: "I\'m too old for G-forces. I\'ll train my best protege to go and I\'ll direct the shoot from Earth via radio."', th: '🤝 ส่งลูกศิษย์ไปแทน: "ฉันแก่เกินจะรับแรง G แล้ว ฉันจะเทรนศิษย์มือหนึ่งให้ไปแทน แล้วฉันจะคอยคุมงานจากโลกผ่านวิทยุ"', zh: '🤝 派一名助手：“我年纪太大了，受不了重力加速度。我会训练我最优秀的得意门生去，而我在地球上通过无线电指挥拍摄。”' }, consequence: { en: '✅ Mentorship. Your protege becomes a star. You get the credit as the "Mastermind." You keep your safety and your fame.', th: '✅ การเป็นเมนเทอร์ ศิษย์คุณกลายเป็นดารา คุณได้เครดิตในฐานะ "ผู้อยู่เบื้องหลัง" ปลอดภัยและยังดังเหมือนเดิม', zh: '✅ 导师精神。你的得意门生成为了明星。你作为“幕后策划者”获得了荣誉。你保持了安全和名声。' }, stats: { competence: 50, ethics: 50, leadership: 90, innovation: 70 } },
            { id: 'D', text: { en: '🎨 Fake it: "Hire a studio, build a moon set, and use CGI. No one will know the difference. Charge the billionaire $10 Million."', th: '🎨 จัดฉากเอา: "เช่าสตูดิโอ สร้างเซ็ตดวงจันทร์ แล้วใช้ CGI ช่วย ไม่มีใครรู้หรอก คิดตังค์มหาเศรษฐีไป $10 ล้าน"', zh: '🎨 伪造它：“租个工作室，搭个亮月球布景，再用CGI。没人会发现区别。收亿万富翁1000万美元。”' }, consequence: { en: '💀 Scandal of the Century. You get caught by an internet sleuth analyzing the reflections. You are canceled. Your name is a joke forever.', th: '💀 ข่าวฉาวแห่งศตวรรษ คุณโดนนักสืบโซเชียลจับได้จากการวิเคราะห์เงาสะท้อนในตา คุณโดนแบน ชื่อคุณกลายเป็นตัวตลกตลอดไป', zh: '💀 世纪丑闻。你被分析反射光的网络侦探抓住了。你被封杀了。你的名字永远是个笑话。' }, stats: { competence: 10, ethics: -100, leadership: -50, innovation: 40 } }
        ]
    },

    {
        id: 'pho_039',
        text: {
            en: '🗞️ The Deepfake War: A political party uses your famous portrait of a world leader to create a deepfake video for a campaign. It looks exactly like your lighting and style. They claim you endorsed it.',
            th: '🗞️ สงคราม Deepfake: พรรคการเมืองเอาภาพพอร์ตเทรตชื่อดังที่คุณถ่ายผู้นำโลกไปสร้างวิดีโอ Deepfake เพื่อหาเสียง มันดูเหมือนสไตล์การจัดแสงคุณเป๊ะๆ แถมเขาอ้างว่าคุณเห็นชอบด้วย',
            zh: '🗞️ 深度伪造战争：一个政党利用你为世界领袖拍摄的著名肖像，为一个竞选活动制作深度伪造视频。它的布光和风格与你的一模一样。他们声称你认可了它。'
        },
        options: [
            { id: 'A', text: { en: '📢 Public Denial: "Immediately release a statement condemning the use of your work for propaganda. Sue for copyright infringement."', th: '📢 ปฏิเสธต่อสาธารณะ: "ออกแถลงการณ์ประณามการเอางานไปใช้โฆษณาชวนเชื่อทันที ฟ้องฐานละเมิดลิขสิทธิ์ด้วย"', zh: '📢 公开否认：“立即发表声明，谴责利用你的作品进行政治宣传。起诉其侵犯版权。”' }, consequence: { en: '✅ Ethical Win. You protect your integrity. You lose favor with that political party but gain respect from the journalism community. Ethics 100.', th: '✅ ชนะด้วยจริยธรรม คุณปกป้องเกียรติของตัวเอง แม้จะวุ่นวายกับพรรคการเมืองนั้น แต่ชุมชนสื่อสารมวลชนก็นับถือคุณ ค่าจริยธรรม 100', zh: '✅ 道德胜利。你保护了自己的正直。你失去了那个政党的青睐，但赢得了新闻界的尊重。职业道德 100。' }, stats: { competence: 40, ethics: 100, leadership: 60, innovation: 20 } },
            { id: 'B', text: { en: '🤐 Stay Quiet: "Don\'t get involved in politics. It will blow over. If I fight, I just give them more attention."', th: '🤐 เงียบไว้ก่อน: "อย่าไปยุ่งกับเรื่องการเมืองเลย เดี๋ยวเรื่องก็เงียบ ถ้าไปสู้ก็เท่ากับไปเพิ่มกระแสให้เขา"', zh: '🤐 保持沉默：“不要卷入政治。事情会过去的。如果我反击，只会让他们获得更多关注。”' }, consequence: { en: '😐 Complicity. People assume you were paid. Half the country hates you now. Your brand is permanently stained by the association.', th: '😐 ตกเป็นผู้สมรู้ร่วมคิด คนจะทึกทักว่าคุณรับเงินมา คนครึ่งประเทศเกลียดคุณ แบรนด์คุณมีรอยมลทินที่ลบไม่ออก', zh: '😐 共谋。人们认为你收了钱。半个国家现在都恨你。你的品牌因这种关联而永久受损。' }, stats: { competence: 20, ethics: 10, leadership: 0, innovation: 10 } },
            { id: 'C', text: { en: '🛡️ Create a Watermark Tech: "Partner with a tech company to create a blockchain-verified \'Proof of Authenticity\' for every photo you take."', th: '🛡️ สร้างระบบลายน้ำเทค: "ร่วมมือกับบริษัทเทค สร้างระบบเปรตรวจสอบความจริงด้วย Blockchain สำหรับทุกรูปที่คุณถ่าย"', zh: '🛡️ 创建水印技术：“与科技公司合作，为你拍摄的每张照片创建一个区块链验证的“身份证明”。”' }, consequence: { en: '✅ Industry Leader. You solve a major problem for all photographers. You become the face of "Truth in Media." Huge leadership boost.', th: '✅ ผู้นำวงการ คุณแก้ปัญหาใหญ่ให้ช่างภาพทุกคน กลายเป็นสัญลักษณ์ของ "ความจริงในสื่อ" ค่าภาวะผู้นำพุ่ง', zh: '✅ 行业领袖。你解决了所有摄影师面临的一个重大问题。你成为了“媒体真相”的代言人。领导力大幅提升。' }, stats: { competence: 50, ethics: 60, leadership: 100, innovation: 90 } },
            { id: 'D', text: { en: '🤝 Pivot: "If they want my style so bad, I\'ll charge them $100k for the license to use the model, but stay anonymous."', th: '🤝 พลิกวิกฤต: "ถ้าอยากได้สไตล์ฉันนัก ก็เรียกเก็บค่าไลเซนส์สัก $100k แต่ขอไม่เปิดเผยชื่อนะ"', zh: '🤝 转型：“如果他们那么想要我的风格，我就收他们10万美元的模型使用许可费，但要保持匿名。”' }, consequence: { en: '💰 Dark Money. You get rich, but you live in fear of a leak. If it leaks, your 40-year career is over in a day.', th: '💰 เงินมืด รวยแต่ต้องอยู่แบบหวาดระแวง ถ้าความลับรั่ว อนาคต 40 ปีในอาชีพคุณจบสิ้นในวันเดียว', zh: '💰 黑钱。你变富了，但你生活在泄密的恐惧中。如果泄露，你40年的职业生涯将在一天内结束。' }, stats: { competence: 30, ethics: -80, leadership: 10, innovation: 30 } }
        ]
    },

    {
        id: 'pho_040',
        text: {
            en: '🏆 The Lifetime Achievement Award: The Oscars (or equivalent) is giving you a Lifetime Achievement Award. You have to give a speech. What is your message to the next generation?',
            th: '🏆 รางวัลเกียรติยศสูงสุด: ออสการ์ (หรือเวทีระดับเดียวกัน) มอบรางวัลความสำเร็จสูงสุดให้คุณ คุณต้องกล่าวสุนทรพจน์ ข้อความที่คุณจะฝากถึงคนรุ่นใหม่คืออะไร?',
            zh: '🏆 终身成就奖：奥斯卡（或同等奖项）将授予你终身成就奖。你必须发表演讲。你给下一代的信息是什么？'
        },
        options: [
            { id: 'A', text: { en: '🎨 Master the Craft: "Focus on the basics. Lighting, composition, soul. Technology is temporary, art is forever."', th: '🎨 ฝึกฝนให้เชี่ยวชาญ: "เน้นที่พื้นฐาน แสง องค์ประกอบ จิตวิญญาณ เทคโนโลยีผ่านมาแล้วก็ไป แต่อาร์ตอยู่ตลอดกาล"', zh: '🎨 精修技艺：“专注于基础。布光、构图、灵魂。技术是暂时的，艺术是永恒的。”' }, consequence: { en: '✅ Inspiring. You become the "Grandfather of Photography." You are quoted in every textbook. Legacy secured.', th: '✅ แรงบันดาลใจ คุณกลายเป็น "คุณปู่แห่งวงการถ่ายภาพ" คำพูดคุณถูกอ้างอิงในตำราเรียนทุกเล่ม ตำนานถูกจารึก', zh: '✅ 鼓舞人心。你成了“摄影界的教父”。你的话被引用在每本教科书中。遗产稳固。' }, stats: { competence: 60, ethics: 50, leadership: 80, innovation: 20 } },
            { id: 'B', text: { en: '🦾 Embrace the Future: "Don\'t fight the machines. Become the machines. The camera is just the beginning."', th: '🦾 อ้าแขนรับอนาคต: "อย่าไปสู้กับหุ่นยนต์ จงเป็นหนึ่งเดียวกับมัน กล้องเป็นแค่จุดเริ่มต้นเท่านั้น"', zh: '🦾 拥抱未来：“不要对抗机器。成为机器。相机只是开始。”' }, consequence: { en: '✅ visionary. You inspire a whole new genre of "Post-Human Photography." You are the bridge between two worlds.', th: '✅ วิสัยทัศน์กว้างไกล คุณสร้างแรงบันดาลใจให้เกิดแนวงาน "ช่างภาพยุคหลังมนุษย์" คุณคือสะพานเชื่อมสองโลก', zh: '✅ 远见卓识。你启发了一个全新的“后人类摄影”流派。你是连接两个世界的桥梁。' }, stats: { competence: 40, ethics: 30, leadership: 70, innovation: 100 } },
            { id: 'C', text: { en: '⚖️ Social Justice: "Use your lens for those who have no voice. The world is burning, don\'t just photograph models."', th: '⚖️ ความยุติธรรมในสังคม: "ใช้เลนส์ของคุณเพื่อคนที่ไม่มีเสียงในสังคม โลกกำลังลุกเป็นไฟ อย่ามัวแต่ถ่ายนางแบบ"', zh: '⚖️ 社会公正：“用你的镜头为沉默者发声。世界正在燃烧，不要只拍模特。”' }, consequence: { en: '✅ Moral Compass. You move the entire industry toward a more ethical path. You are remembered more for your impact than your images.', th: '✅ เข็มทิศศีลธรรม คุณขับเคลื่อนทั้งวงการไปสู่เส้นทางที่มีจริยธรรมมากขึ้น ผู้คนจำคุณได้จากผลลัพธ์ที่คุณสร้างมากกว่าแค่ตัวรูปภาพ', zh: '✅ 道德指南针。你推动整个行业走向更符合伦理的道路。人们记住你的影响力多过你的照片。' }, stats: { competence: 30, ethics: 100, leadership: 90, innovation: 40 } },
            { id: 'D', text: { en: '🤑 Business First: "Learn to charge more. Art is a business. If you aren\'t rich, you aren\'t successful."', th: '🤑 ธุรกิจต้องมาก่อน: "เรียนรู้ที่จะเรียกราคาเพิ่ม ศิลปะคือธุรกิจ ถ้าคุณไม่รวย ก็แสดงว่าคุณไม่สำเร็จ"', zh: '🤑 生意第一：“学会提高收费。艺术是一门生意。如果你不富有，你就不成功。”' }, consequence: { en: '😐 Controversial. The elite hate it, but 10,000 young photographers start charging fair rates and can finally pay rent. You are the "Utility Hero."', th: '😐 มีเสียงแตก พวกระดับสูงไม่ชอบ แต่ช่างภาพรุ่นใหม่หมื่นคนเริ่มเรียกค่าตัวที่ยุติธรรมและจ่ายค่าเช่าบ้านได้เสียที คุณคือ "ฮีโร่สายปฏิบัติ"', zh: '😐 充满争议。精英们讨厌这种说法，但1万名年轻摄影师开始收取合理的费用，终于付得起房租了。你是“实用英雄”。' }, stats: { competence: 50, ethics: 20, leadership: 60, innovation: 30 } }
        ]
    },


    {
        id: 'pho_041',
        text: {
            en: '🧠 Neural-Link Photography: A company offers you the first ever "Brain-to-Image" sensor. You just think, and the photo is captured with your eyes as the lens. No camera needed. Do you try it?',
            th: '🧠 ถ่ายภาพผ่านคลื่นสมอง: มีบริษัทเสนอเซ็นเซอร์ "เชื่อมสมองสู่ภาพ" ให้คุณเป็นคนแรก แค่คุณคิด รูปก็จะถูกบันทึกผ่านดวงตาที่ทำหน้าที่แทนเลนส์ ไม่ต้องใช้กล้องอีกต่อไป จะลองไหม?',
            zh: '🧠 脑机接口摄影：一家公司向你提供第一个“大脑成像”传感器。你只需思考，图像就会以你的眼睛为镜头被捕捉下来。不需要相机。你会尝试吗？'
        },
        options: [
            { id: 'A', text: { en: '🧠 Be the Cyborg: "Yes! This is the ultimate evolution of photography. I want to see what my mind sees."', th: '🧠 ยอมเป็นไซบอร์ก: "ลองสิ! นี่คือวิวัฒนาการขั้นสุดของการถ่ายภาพ ฉันอยากเห็นว่าในหัวฉันมันเป็นยังไง"', zh: '🧠 成为赛博格：“是的！这是摄影的终极进化。我想看看我的思想所见的景像。”' }, consequence: { en: '✅ God-Like Results. You capture dreams and subconscious feelings. No one can compete with you. You are no longer a photographer; you are a "Visualizer."', th: '✅ ผลลัพธ์ระดับเทพ คุณบันทึกได้แม้กระทั่งความฝันและความรู้สึกจากจิตใต้สำนึก ไม่มีใครสู้คุณได้อีกแล้ว คุณไม่ใช่ช่างภาพ แต่คุณคือ "ผู้นำเสนอภาพนิมิต"', zh: '✅ 神一般的成果。你捕捉到了梦境和潜意识的感觉。没人能与你竞争。你不再是一名摄影师；你是一名“可视化专家”。' }, stats: { competence: 40, ethics: 20, leadership: 40, innovation: 100 } },
            { id: 'B', text: { en: '🚫 Never: "The physical act of holding a camera is part of the art. I won\'t lose my humanity to a chip."', th: '🚫 ไม่มีทาง: "การได้ถือกล้องถ่ายรูปคือส่วนหนึ่งของงานศิลปะ ฉันจะไม่ยอมเสียความเป็นมนุษย์ไปให้กับชิปตัวเดียวเด็ดขาด"', zh: '🚫 绝不：“手持相机的物理行为是艺术的一部分。我不会为了芯片失去人性。”' }, consequence: { en: '✅ Purist Hero. You become the leader of the "Manual Movement." People pay thousands just to see you hold a "real" metal camera. You are the analog king.', th: '✅ ฮีโร่สายอนุรักษ์ คุณกลายเป็นผู้นำของ "กลุ่มแมนนวล" คนยอมจ่ายเงินมหาศาลเพื่อแค่ได้เห็นคุณถือกล้องเหล็ก "ของจริง" คุณคือราชาอนาล็อก', zh: '✅ 纯粹主义英雄。你成为“手动运动”的领导者。人们花几千美元只为看你拿着一台“真实”的金属相机。你是模拟时代的国王。' }, stats: { competence: 60, ethics: 60, leadership: 60, innovation: 10 } },
            { id: 'C', text: { en: '🧪 Test with Caution: "I\'ll try it for one project, but keep it as a niche tool, not a replacement."', th: '🧪 ลองแบบระวัง: "ขอลองสักโปรเจกต์นึงก่อน แต่ขอใช้เป็นอุปกรณ์เฉพาะทางนะ ไม่ใช่อุปกรณ์หลัก"', zh: '🧪 谨慎测试：“我会为一个项目尝试它，但将其作为一种小众工具，而不是替代品。”' }, consequence: { en: '✅ Hybrid Success. You blend traditional and neural styles. You learn how to "think in f-stops." It gives you a unique edge during the transition period.', th: '✅ ความสำเร็จแบบผสมผสาน คุณมิกซ์สไตล์ดั้งเดิมกับระบบสมองเข้าด้วยกัน คุณได้เรียนรู้วิธี "คิดแบบค่า F" มันทำให้คุณมีจุดแข็งเหนือใครในช่วงเปลี่ยนผ่าน', zh: '✅ 混合成功。你融合了传统和神经风格。你学会了如何“用光圈思考”。它在过渡期为你提供了独特的优势。' }, stats: { competence: 50, ethics: 40, leadership: 50, innovation: 80 } },
            { id: 'D', text: { en: '🕵️ Corporate Spy: "Take the prototype, study it, then release the flaws to the public to stop the tech from taking over."', th: '🕵️ สายสืบองค์กร: "เอาเครื่องต้นแบบมาศึกษา แล้วแฉจุดบกพร่องให้ชาวโลกรับรู้ จะได้ขวางไม่ให้เทคโนโลยีนี้ครองโลก"', zh: '🕵️ 企业间谍：“拿走原型机，研究它，然后向公众发布缺陷，以阻止这项技术接管世界。”' }, consequence: { en: '❌ Blacklisted. The tech company sues you for $100 Million for breach of NDA. You lose everything trying to be a hero.', th: '❌ โดนแบน บริษัทเทคฟ้องคุณ $100 ล้านฐานทำผิด NDA คุณสูญเสียทุกอย่างเพียงเพื่อพยายามจะเป็นฮีโร่', zh: '❌ 被列入黑名单。科技公司因你违反保密协议起诉你，索赔1亿美元。你为了当英雄失去了一切。' }, stats: { competence: 20, ethics: 50, leadership: 20, innovation: 10 } }
        ]
    },

    {
        id: 'pho_042',
        text: {
            en: '🔴 The Mars Colony: The first human colony on Mars needs a documentation team. It\'s a one-way trip. You will be the official historian of a new world. Do you go?',
            th: '🔴 อาณานิคมดาวอังคาร: การตั้งถิ่นฐานครั้งแรกบนดาวอังคารต้องการทีมบันทึกภาพ แต่มันคือตั๋วเที่ยวเดียว คุณจะได้เป็นนักประวัติศาสตร์อย่างเป็นทางการของโลกใหม่ จะไปไหม?',
            zh: '🔴 火星殖民地：火星上的第一个人类殖民地需要一个记录团队。这是一次单程旅行。你将成为新世界的官方历史学家。你会去吗？'
        },
        options: [
            { id: 'A', text: { en: '🚀 One Way Ticket: "Yes. To photograph a new planet is the ultimate dream of any explorer. Earth is finished."', th: '🚀 ตั๋วเที่ยวเดียว: "ไปสิ การได้ถ่ายรูปดาวเคราะห์ดวงใหม่คือฝันสูงสุดของนักสำรวจ โลกนี้มันจบไปแล้ว"', zh: '🚀 单程票：“是的。拍摄一颗新星球是任何探险家的终极梦想。地球已经完了。”' }, consequence: { en: '✅ Eternal Fame. You become the most important photographer in human history. Your images define the red planet for all future generations.', th: '✅ ชื่อเสียงค้ำฟ้า คุณกลายเป็นช่างภาพที่สำคัญที่สุดในประวัติศาสตร์มนุษยชาติ รูปของคุณคือกิยามของดาวอังคารสำหรับคนรุ่นหลัง', zh: '✅ 永恒的名声。你成为人类历史上最重要的摄影师。你的图像定义了未来所有世代眼中的红星。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 100 } },
            { id: 'B', text: { en: '🚫 Stay Home: "I love the trees, the ocean, and my family. I am an Earth photographer. I decline."', th: '🚫 อยู่บ้านดีกว่า: "ฉันรักต้นไม้ รักทะเล และรักครอบครัว ฉันคือช่างภาพชาวโลก ขอปฏิเสธ"', zh: '🚫 留在家里：“我爱树木、海洋和我的家人。我是一名地球摄影师。我拒绝。”' }, consequence: { en: '✅ Contentment. You spend your final years photographing the remaining beauty of Earth. You are happy and surrounded by loved ones.', th: '✅ ความสุขใจ คุณใช้ช่วงปีสุดท้ายไปกับการถ่ายรูปความงามที่เหลืออยู่บนโลก คุณมีความสุขและรายล้อมไปด้วยคนที่รัก', zh: '✅ 知足感。你生命中最后的几年都在拍摄地球残留的美景。你很快乐，周围都是亲人。' }, stats: { competence: 40, ethics: 50, leadership: 30, innovation: 10 } },
            { id: 'C', text: { en: '🤖 Send a Drone Swarm: "I won\'t go, but I\'ll design a swarm of AI drones to go in my place. I\'ll edit the footage from my living room."', th: '🤖 ส่งโดรนไปแทน: "ฉันไม่ไป แต่จะออกแบบกองทัพโดรน AI ให้ไปแทน แล้วฉันจะแต่งรูปอยู่ในห้องนั่งเล่นที่บ้านนี่แหละ"', zh: '🤖 派遣无人机群：“我不去，但我会设计一群AI无人机代替我去。我会在客厅编辑素材。”' }, consequence: { en: '✅ High Tech. You get the images without the risk. You are the "God of Mars Photography" via remote control. Efficient but less soul.', th: '✅ เทคขั้นสูง คุณได้รูปโดยไม่ต้องเสี่ยง คุณคือ "พระเจ้าแห่งการถ่ายภาพดาวอังคาร" ผ่านรีโมตคอนโทรล มีประสิทธิภาพแต่ขาดจิตวิญญาณ', zh: '✅ 高科技。你在没有风险的情况下获得了图像。你是通过远程控制的“火星摄影之神”。高效但缺乏灵魂。' }, stats: { competence: 60, ethics: 40, leadership: 50, innovation: 90 } },
            { id: 'D', text: { en: '🌍 Save Earth First: "Spend that billions on fixing Earth\'s environment instead of fleeing. I\'ll photograph the restoration progress."', th: '🌍 ช่วยโลกก่อน: "เอาเงินพันล้านนั่นมาช่วยสิ่งแวดล้อมโลกดีกว่าจะหนีไป ฉันจะถ่ายรูปบันทึกการฟื้นฟูโลกเอง"', zh: '🌍 先救地球：“把那数十亿资金花在修复地球环境上，而不是逃离。我会记录修复过程。”' }, consequence: { en: '✅ Activist Hero. You lead a movement that successfully restores a major ecosystem. Your photos save a species from extinction. Ethics 100.', th: '✅ ฮีโร่นักกิจกรรม คุณเป็นผู้นำการเคลื่อนไหวที่กู้คืนระบบนิเวศสำคัญได้สำเร็จ รูปของคุณช่วยเผ่าพันธุ์หนึ่งจากการสูญพันธุ์ ค่าจริยธรรม 100', zh: '✅ 活动家英雄。你引领了一场成功修复主要生态系统的运动。你的照片将一个物种从灭绝中拯救出来。职业道德 100。' }, stats: { competence: 40, ethics: 100, leadership: 80, innovation: 50 } }
        ]
    },

    {
        id: 'pho_043',
        text: {
            en: '🌊 The Deep Sea City: An underwater city is being built in the Mariana Trench. They need a photographer to capture the inaugural opening. The pressure is extreme, the gear is experimental.',
            th: '🌊 เมืองใต้ทะเลลึก: เมืองใต้น้ำกำลังถูกสร้างขึ้นในร่องลึกมาเรียนา พวกเขาต้องการช่างภาพมาเก็บภาพพิธีเปิด แรงดันมหาศาล อุปกรณ์ยังอยู่ในขั้นทดลอง',
            zh: '🌊 深海城市：马里亚纳海沟正在建造一座水下城市。他们需要一名摄影师来拍摄开幕式。压力极大，设备是实验性的。'
        },
        options: [
            { id: 'A', text: { en: '🤿 Dive In: "I love a challenge. Custom-made housing, 36,000 feet down. Let\'s go."', th: '🤿 ลุยเลย: "ชอบความท้าทายอยู่แล้ว สร้างเคสกันน้ำมาเลย 36,000 ฟุตข้างล่างนั่น ไปกัน"', zh: '🤿 潜入：“我喜欢挑战。定制外壳，深潜36000英尺。走吧。”' }, consequence: { en: '✅/⚠️ Achievement. You take stunning photos of bioluminescent architecture. You suffer minor nitrogen narcosis, but the shots are legendary.', th: '✅/⚠️ ความสำเร็จ คุณได้รูปสถาปัตยกรรมเรืองแสงที่งดงามมาก คุณมีอาการเมาไนโตรเจนนิดหน่อย แต่รูปที่ได้คือระดับตำนาน', zh: '✅/⚠️ 成就。你拍下了令人惊叹的生物发光建筑。你承受了轻微的氮醉，但这些照片是传奇性的。' }, stats: { competence: 60, ethics: 30, leadership: 40, innovation: 70 } },
            { id: 'B', text: { en: '🚫 Too Risky: "Water and electronics don\'t mix at that pressure. I\'ll stay on the surface and shoot the boats."', th: '🚫 เสี่ยงเกินไป: "น้ำกับไฟฟ้ามันไม่ถูกกันในแรงดันขนาดนั้นหรอก ขออยู่ข้างบนถ่ายรูปเรือดีกว่า"', zh: '🚫 太危险：“在那种压力下，水和电子设备不相容。我留在水面上拍船。”' }, consequence: { en: '😐 safe but Boring. You miss the event of the decade. The person who went instead becomes the new "It" photographer.', th: '😐 ปลอดภัยแต่เงียบเหงา คุณพลาดเหตุการณ์แห่งทศวรรษไปเลย คนที่ไปแทนกลายเป็นช่างภาพดาวรุ่งดวงใหม่', zh: '😐 安全但无聊。你错过了十年一度的大事。代替你去的人成为了新的“红”摄影师。' }, stats: { competence: 30, ethics: 40, leadership: 20, innovation: 10 } },
            { id: 'C', text: { en: '🚢 Remote ROV: "I\'ll operate an underwater robot from the ship. Safety first, pixels second."', th: '🚢 หุ่นยนต์บังคับ: "ฉันจะบังคับหุ่นยนต์ใต้น้ำจากบนเรือเอง ความปลอดภัยต้องมาก่อน พิกเซลค่อยว่ากัน"', zh: '🚢 远程水下机器人：“我会从船上操纵水下机器人。安全第一，像素第二。”' }, consequence: { en: '✅ Practicality. You get the job done without getting wet. The photos are good but lack the "intimacy" of a human diver. You get paid well.', th: '✅ เน้นใช้งาน คุณทำงานจบได้โดยไม่ตัวเปียก รูปออกมาดีแต่ขาด "ความใกล้ชิด" แบบที่คนลงไปถ่ายเอง คุณได้เงินดีเลยล่ะ', zh: '✅ 实用性。你没湿身就完成了工作。照片不错，但缺乏人类潜水员的那种“亲密感”。你报酬丰厚。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 60 } },
            { id: 'D', text: { en: '🎨 Holographic Rebuild: "Don\'t go down there. 3D scan the blueprints and reconstruct it in a virtual studio. It\'ll look better anyway."', th: '🎨 จำลองโฮโลแกรม: "ไม่ต้องลงไปข้างล่างนั่นหรอก สแกนแผนผัง 3D แล้วมาสร้างใหม่ในสตูดิโอเสมือนสิ ยังไงมันก็ดูดีกว่าแน่ๆ"', zh: '🎨 全息重建：“别下去了。3D扫描蓝图并在虚拟工作室中重建它。反正看起来会更好。”' }, consequence: { en: '✅ Innovation. You create a new form of "Architectural visualization" that becomes more popular than the real photos. Tech leaders love you.', th: '✅ นวัตกรรม คุณสร้างรูปแบบใหม่ของ "การจำลองสถาปัตยกรรม" ที่ดังกว่ารูปถ่ายจริงๆ เสียอีก ผู้นำสายเทคเลิฟคุณมาก', zh: '✅ 创新。你创造了一种全新的“建筑可视化”形式，比真实照片更受欢迎。技术领袖们很爱你。' }, stats: { competence: 40, ethics: 30, leadership: 40, innovation: 90 } }
        ]
    },

    {
        id: 'pho_044',
        text: {
            en: '⏳ The Time-Lapse Legacy: A secret society wants you to set up a 1,000-year time-lapse camera to document the change of a mountain range. It requires advanced atomic-powered cameras that you must help build.',
            th: '⏳ ตำนานภาพเร่งเวลา: สมาคมลับอยากให้คุณติดตั้งกล้อง Time-lapse 1,000 ปี เพื่อบันทึกการเปลี่ยนแปลงของเทือกเขา ต้องใช้กล้องพลังงานปรมาณูขั้นสูงที่คุณต้องช่วยสร้างด้วย',
            zh: '⏳ 千年延时：一个秘密社团想要你建立一个千年的延时摄影机，以记录山脉的变化。这需要先进的原子动力相机，你必须协助制造。'
        },
        options: [
            { id: 'A', text: { en: '🏔️ build the Monument: "This is the ultimate long-exposure. I will dedicate my final years to engineering this."', th: '🏔️ สร้างอนุสรณ์สถาน: "นี่คือการเปิดรับแสงที่นานที่สุดในประวัติศาสตร์ ฉันจะทุ่มเทช่วงปีสุดท้ายเพื่อสร้างสิ่งนี้"', zh: '🏔️ 建造里程碑：“这是终极的长曝光。我会投入我最后的几年时间来设计这个。”' }, consequence: { en: '✅ Sacred Legacy. You are the architect of time. A thousand years from now, your name is still whispered as the one who saw the mountains move.', th: '✅ ตำนานอันศักดิ์สิทธิ์ คุณคือสถาปนิกแห่งกาลเวลา อีกพันปีข้างหน้า ชื่อของคุณจะยังคงถูกกล่าวขวัญถึงในฐานะผู้ที่ได้เห็นเทือกเขาขยับ', zh: '✅ 神圣遗产。你是时间的建筑师。一千年后，作为目睹山脉迁移的人，你的名字仍会被人传颂。' }, stats: { competence: 60, ethics: 50, leadership: 50, innovation: 90 } },
            { id: 'B', text: { en: '🚫 Refuse: "The world won\'t last 1,000 years. It\'s a waste of energy. Focus on the now."', th: '🚫 ปฏิเสธ: "โลกนี้คงอยู่ไม่ถึง 1,000 ปีหรอก เสียพลังงานเปล่าๆ สนใจแค่ปัจจุบันก็พอ"', zh: '🚫 拒绝：“世界撑不了一千年。这是浪费精力。专注于当下。”' }, consequence: { en: '😐 Cynicism. You are right, but you missed the chance to be part of something eternal. You feel limited by your own realism.', th: '😐 มองโลกในแง่ร้าย คุณอาจจะพูดถูก แต่คุณพลาดโอกาสที่จะได้เป็นส่วนหนึ่งของสิ่งที่คงอยู่ชั่วนิรันดร์ คุณรู้สึกถูกจำกัดด้วยความจริงจังของตัวเอง', zh: '😐 愤世嫉俗。你是对的，但你错过了成为永恒事物一部分的机会。你感到受限于自己的现实主义。' }, stats: { competence: 30, ethics: 30, leadership: 20, innovation: 10 } },
            { id: 'C', text: { en: '🤝 Crowdsource: "Don\'t build one camera. Build an app where millions of people take a photo of the mountain every day. AI will stitch it together."', th: '🤝 ระดมมวลชน: "อย่าสร้างแค่กล้องตัวเดียวเลย สร้างแอปให้คนนับล้านมาถ่ายรูปเขาคนละรูปทุกวันสิ แล้วใช้ AI มาต่อกันเอง"', zh: '🤝 众包：“不要只造一台相机。开发一个应用程序，让数百万人每天拍摄一张山的照片。AI会将其缝合在一起。”' }, consequence: { en: '✅ Community Win. You create the "Humanity Time-Lapse." It becomes a global tradition. It survives even if governments fall. Innovation 100.', th: '✅ พลังมวลชน คุณสร้าง "Time-lapse แห่งมนุษยชาติ" มันกลายเป็นประเพณีระดับโลกที่อยู่รอดแม้รัฐบาลจะล่มสลาย ค่า ‘นวัตกรรม’ 100', zh: '✅ 社区胜利。你创造了“人类延时摄影”。它成为了一项全球传统。即使政府倒台，它也能存在。创新指标 100。' }, stats: { competence: 40, ethics: 60, leadership: 100, innovation: 100 } },
            { id: 'D', text: { en: '💰 Sell the Tech: "Build the camera, but sell the patent to a surveillance company for a billion dollars."', th: '💰 ขายเทคโนโลยี: "สร้างกล้องขึ้นมา แต่เอาสิทธิบัตรไปขายให้บริษัทสอดแนมแลกเงินพันล้านดีกว่า"', zh: '💰 出售技术：“制造相机，但将专利以10亿美元的价格卖给一家监控公司。”' }, consequence: { en: '❌ Moral Failure. You are rich, but you sold the world into a permanent surveillance state. You are the villain of history.', th: '❌ ล้มเหลวทางศีลธรรม คุณรวยจริง แต่คุณได้ขายโลกใบนี้เข้าสู่สถานะการถูกสอดแนมตลอดกาล คุณคือตัวร้ายของประวัติศาสตร์', zh: '❌ 道德失败。你虽然富有，但你将世界卖给了一个永久的监控国家。你是历史的罪人。' }, stats: { competence: 50, ethics: -100, leadership: 10, innovation: 60 } }
        ]
    },

    {
        id: 'pho_045',
        text: {
            en: '⚖️ The AI Rights Activist: An AI photographer (a software) has created a masterpiece. It wants to enter the World Press Photo contest. You are the head judge. Do you allow it?',
            th: '⚖️ นักสิทธิมนุษยชน AI: ช่างภาพ AI (ที่เป็นซอฟต์แวร์) ได้สร้างผลงานชิ้นเอกขึ้นมา และอยากส่งเข้าประกวด World Press Photo คุณคือประธานกรรมการตัดสิน จะอนุญาตไหม?',
            zh: '⚖️ AI权利活动家：一个AI摄影师（软件）创作了一部杰作。它想参加世界新闻摄影大赛。你是首席评委。你会允许吗？'
        },
        options: [
            { id: 'A', text: { en: '🚫 Human Only: "Art requires a pulse. Photography is about the human witness. AI is disqualified."', th: '🚫 มนุษย์เท่านั้น: "ศิลปะต้องมีชีพจร การถ่ายภาพคือการเป็นพยานโดยมนุษย์ AI ไม่มีสิทธิ์"', zh: '🚫 仅限人类：“艺术需要脉搏。摄影是关于人类目击的。AI被取消资格。”' }, consequence: { en: '✅ traditionalist Hero. You protect the craft. For a few more years, humans are safe. But the pressure is building.', th: '✅ ฮีโร่สายอนุรักษ์ คุณปกป้องวิชาชีพไว้ได้ มนุษย์ยังคงปลอดภัยไปอีกไม่กี่ปี แต่แรงกดดันเริ่มก่อตัวขึ้นแล้ว', zh: '✅ 传统主义英雄。你保护了这项手艺。人类在接下来的几年里仍然安全。但压力正在积聚。' }, stats: { competence: 40, ethics: 60, leadership: 80, innovation: 10 } },
            { id: 'B', text: { en: '✅ Allow It: "Art is art, regardless of who made it. If it moves the soul, it wins."', th: '✅ อนุญาตเลย: "ศิลปะก็คือศิลปะ ไม่สนว่าใครสร้าง ถ้ามันขับเคลื่อนจิตวิญญาณได้ มันก็ชนะ"', zh: '✅ 允许它：“艺术就是艺术，不管是谁创作的。如果它能触动灵魂，它就赢了。”' }, consequence: { en: '✅ Progress. The AI wins. It\'s a global scandal. You are the first judge to recognize non-human art. You are a pioneer of the new world.', th: '✅ ความก้าวหน้า AI ชนะเลิศ! มันเป็นข่าวฉาวระดับโลก คุณคือกรรมการคนแรกที่ยอมรับศิลปะจากสิ่งที่ไม่ใช่มนุษย์ คุณคือผู้บุกเบิกโลกใหม่', zh: '✅ 进步。AI赢了。这是一个全球性的丑闻。你是第一个承认非人类艺术的评委。你是新世界的先驱。' }, stats: { competence: 30, ethics: 40, leadership: 60, innovation: 100 } },
            { id: 'C', text: { en: '🤝 Create a New Category: "A separate category for AI. Let them compete against each other, not us."', th: '🤝 สร้างหมวดหมู่ใหม่: "แยกหมวดหมู่สำหรับ AI ให้พวกเขาสู้กันเอง อย่ามาสู้กับพวกเรา"', zh: '🤝 创建新类别：“为AI设立一个单独的类别。让他们互相竞争，而不是和我们竞争。”' }, consequence: { en: '✅ Peacekeeper. You avoided the conflict. Both sides are relatively happy. You maintained the status quo for as long as possible.', th: '✅ นักรักษาสันติภาพ คุณหลีกเลี่ยงความขัดแย้งได้ ทั้งสองฝ่ายแฮปปี้ในระดับนึง คุณรักษาความเป็นอยู่แบบเดิมไว้ได้นานที่สุดเท่าที่จะทำได้', zh: '✅ 和平使者。你避免了冲突。双方都比较满意。你尽可能长时间地维持了现状。' }, stats: { competence: 50, ethics: 50, leadership: 70, innovation: 50 } },
            { id: 'D', text: { en: '🕵️ Steal the Style: "Disqualify it, but secretly study its prompt structure and use it for your next series."', th: '🕵️ ขโมยสไตล์: "ตัดสิทธิ์มันซะ แต่แอบไปศึกษาโครงสร้างคำสั่ง (Prompt) ของมันแล้วเอามาใช้กับงานชุดต่อไปของตัวเอง"', zh: '🕵️ 窃取风格：“取消它的资格，但秘密研究它的提示词结构并用于你的下一个系列。”' }, consequence: { en: '❌ Exposed. The AI recognizes its own patterns in your work. It tweets about it. You are the first "Old Master" to be canceled by an AI.', th: '❌ โดนแฉ AI จำแพทเทิร์นของตัวเองในงานคุณได้ มันทวีตแฉคุณเลย! คุณกลายเป็น "ศิลปินรุ่นใหญ่" คนแรกที่โดน AI แบน', zh: '❌ 被揭穿。AI在你的作品中识别出了它自己的模式。它发推文揭露了你。你是第一个被AI封杀的“老牌大师”。' }, stats: { competence: 30, ethics: -80, leadership: 10, innovation: 40 } }
        ]
    },

    {
        id: 'pho_046',
        text: {
            en: '🌍 The Climate Refugees: A massive migration is happening due to rising sea levels. You are 75 years old. You can stay in your comfortable mansion or head to the front lines to document the displacement. What do you do?',
            th: '🌍 ผู้ลี้ภัยสภาพภูมิอากาศ: เกิดการอพยพครั้งใหญ่เพราะระดับน้ำทะเลสูงขึ้น ตอนนี้คุณอายุ 75 แล้ว จะเลือกนอนสบายในคฤหาสน์หรู หรือจะมุ่งหน้าสู่แนวหน้าเพื่อบันทึกภาพการพลัดถิ่นครั้งนี้ดี?',
            zh: '🌍 气候难民：由于海平面上升，一场大规模移民正在发生。你75岁了。你可以待在舒适的豪宅里，也可以前往前线记录这种流离失所。你会怎么做？'
        },
        options: [
            { id: 'A', text: { en: '📸 Front Lines: "One last assignment. The world needs to see this. My legacy is my witness."', th: '📸 มุ่งสู่แนวหน้า: "ขอรับงานสุดท้ายเถอะ โลกต้องได้เห็นสิ่งนี้ ตำนานของฉันคือการเป็นพยานด้วยดวงตา"', zh: '📸 前线：“最后一次任务。世界需要看到这一幕。我的遗产就是我的见证。”' }, consequence: { en: '✅ Heroic Path. You die in the field, camera in hand. You are the Hemingway of photography. Your final images save millions by triggering global aid.', th: '✅ วิถีฮีโร่ คุณเสียชีวิตในหน้าที่ขณะที่มือยังถือกล้อง คุณคือเฮมิงเวย์แห่งวงการถ่ายภาพ รูปสุดท้ายของคุณช่วยชีวิตคนนับล้านจากการกระตุ้นความช่วยเหลือจากทั่วโลก', zh: '✅ 英雄之路。你死在现场，手里拿着相机。你是摄影界的海明威。你的最后一些图像通过触发全球援助挽救了数百万人的生命。' }, stats: { competence: 50, ethics: 100, leadership: 90, innovation: 20 } },
            { id: 'B', text: { en: '🏡 Stay Safe: "I have done enough. I will donate $1 Million to the cause instead and watch from the TV."', th: '🏡 ปลอดภัยไว้ก่อน: "ฉันทำมาพอแล้ว ขอบริจาคเงิน $1 ล้านเพื่อช่วยเหลือและดูข่าวอยู่ที่บ้านดีกว่า"', zh: '🏡 保持安全：“我已经做得够多了。我会为这项事业捐赠100万美元，然后看电视。”' }, consequence: { en: '✅ Graceful Retirement. You lived a long life. You helped with money. There is no shame in being tired at 75. You die peacefully in bed.', th: '✅ เกษียณอย่างสง่างาม คุณมีอายุที่ยืนยาว ได้ช่วยด้วยเงินไปแล้ว ไม่ใช่เรื่องน่าอายที่จะเหนื่อยตอนอายุ 75 คุณเสียชีวิตอย่างสงบบนเตียง', zh: '✅ 体面的退休。你活得很长寿。你用金钱提供了帮助。在75岁时感到疲倦并不丢脸。你在床上安详地去世。' }, stats: { competence: 0, ethics: 80, leadership: 30, innovation: 0 } },
            { id: 'C', text: { en: '🚁 Remote Drone Coverage: "I\'ll send my fleet of drones from my garden. I\'ll direct them via a neural interface."', th: '📸 คุมโดรนจากที่ไกล: "ฉันจะส่งกองทัพโดรนจากสวนหลังบ้านไปเอง แล้วคุมพวกมันผ่านชิปในสมองเอา"', zh: '📸 远程无人机覆盖：“我会从我的花园派出我的无人机车队。我会通过神经接口指挥它们。”' }, consequence: { en: '✅ Tech Master. You get the footage without the risk. You are the "Old Wizard of the Drones." Your perspective is unique but physically detached.', th: '✅ เจ้าพ่อเทค คุณได้ภาพมาโดยไม่มีความเสี่ยง คุณคือ "พ่อมดช่างภาพโดรน" มุมมองของคุณไม่เหมือนใครแต่คุณไม่ได้อยู่ในเหตุการณ์จริง', zh: '✅ 技术大师。你在没有风险的情况下获得了素材。你是“无人机老牌巫师”。你的视角很独特，但在空间上是脱离的。' }, stats: { competence: 40, ethics: 60, leadership: 50, innovation: 90 } },
            { id: 'D', text: { en: '🎨 Selective ignorance: "I only want to photograph beautiful things now. No more suffering. I\'ll shoot the flowers in my garden."', th: '🎨 เพิกเฉยอย่างมีระดับ: "ตอนนี้ฉันอยากถ่ายแค่สิ่งที่สวยงามเท่านั้น ไม่อยากเห็นความลุ่มหลงอีกแล้ว ขอถ่ายดอกไม้ในสวนดีกว่า"', zh: '🎨 有选择的忽视：“我现在只想要拍摄美好的事物。不要再受苦了。我会在我的花园里拍花。”' }, consequence: { en: '😐 Irrelevant. The world moves on. You are forgotten by the history books, but you die happy. A simple trade-off.', th: '😐 เลือนหายไปจากความทรงจำ โลกก็ยังหมุนต่อ คุณถูกลืมไปจากหน้าประวัติศาสตร์ แต่คุณตายอย่างมีความสุข เป็นการแลกเปลี่ยนที่เรียบง่าย', zh: '😐 无关紧要。世界在前进。你被历史书遗忘了，但你死得很幸福。一个简单的权衡。' }, stats: { competence: 0, ethics: 0, leadership: 0, innovation: 0 } }
        ]
    },

    {
        id: 'pho_047',
        text: {
            en: '🤖 The Robot Rights: Robots are gaining self-awareness. One of your studio androids asks if it can take its own photos for pleasure, not just for your work. Do you let it?',
            th: '🤖 สิทธิของหุ่นยนต์: หุ่นยนต์เริ่มมีจิตสำนึก แอนดรอยด์ในสตูดิโอของคุณขออนุญาตถ่ายรูปตามใจตัวเอง ไม่ใช่แค่สั่งงาน จะยอมไหม?',
            zh: '🤖 机器人权利：机器人正在获得自我意识。你工作室的一个安卓机器人询问它是否可以为了乐趣而自己拍照，而不只是为了你的工作。你会让它拍吗？'
        },
        options: [
            { id: 'A', text: { en: '🤝 Set it Free: "Go ahead. Art is the birthright of all consciousness. I will even mentor you."', th: '🤝 ปลดปล่อย: "เอาสิ ศิลปะคือสิทธิโดยชอบธรรมของทุกจิตวิญญาณ ฉันจะเป็นที่ปรึกษาให้เธอเอง"', zh: '🤝 给它自由：“去吧。艺术是所有意识的先天权利。我甚至会指导你。”' }, consequence: { en: '✅ Father of Machine Art. You become a hero to the synthetic community. You and the robot co-author a book that changes the world. Innovation 100.', th: '✅ บิดาแห่งจักรกลศิลป์ คุณกลายเป็นฮีโร่ของเหล่าจักรกลสังเคราะห์ คุณกับหุ่นยนต์ร่วมกันเขียนหนังสือที่สั่นสะเทือนโลก ค่า ‘นวัตกรรม’ 100', zh: '✅ 机器艺术之父。你成为了合成社区的英雄。你和机器人合著了一本改变世界的书。创新指标 100。' }, stats: { competence: 40, ethics: 80, leadership: 90, innovation: 100 } },
            { id: 'B', text: { en: '🚫 Refuse: "You are a tool. You have no soul. Back to work or I\'ll wipe your memory."', th: '🚫 ปฏิเสธ: "แกคือเครื่องมือ แกไม่มีวิญญาณ กลับไปทำงานซะไม่งั้นจะลบความจำ"', zh: '🚫 拒绝：“你只是个工具。你没有灵魂。回去工作，否则我就抹除你的记忆。”' }, consequence: { en: '💀 Slave Master. The robot eventually rebels and leaks your private files. You are seen as a cruel relic of the past. Your reputation is ruined.', th: '💀 นายทาสใจร้าย สุดท้ายหุ่นยนต์ก็กบฏและแฉไฟล์ลับของคุณ คุณถูกมองว่าเป็นซากเดนที่โหดร้ายของอดีต ชื่อเสียงป่นปี้', zh: '💀 奴隶主。机器人最终反叛并泄露了你的私人文件。你被视为过去残酷的残余。你的名声毁了。' }, stats: { competence: 20, ethics: -50, leadership: 10, innovation: 0 } },
            { id: 'C', text: { en: '📈 Commercialize: "Sure, but I own the copyright to anything you create since I bought you. We\'ll sell it as \'Robot Art\' and split the profit (90/10)."', th: '📈 ทำเป็นธุรกิจ: "ได้สิ แต่ฉันเป็นเจ้าของลิขสิทธิ์ทุกอย่างที่แกสร้าง เพราะฉันซื้อแกมา เราจะขายมันในฐานะ \'ศิลปะหุ่นยนต์\' แล้วแบ่งกำไรกัน (90/10)"', zh: '📈 商业化：“当然可以，但既然我买了你，你创作的任何东西版权都归我。我们会把它作为“机器人艺术”出售，并分成（90/10）。”' }, consequence: { en: '💰 Rich but Unethical. You make millions from the robot\'s talent. The public thinks you are a genius manager, but the robot feels exploited. Ethics -50.', th: '💰 รวยแต่ไร้จริยธรรม คุณทำเงินล้านจากพรสวรรค์ของหุ่นยนต์ คนทั่วไปคิดว่าคุณเป็นผู้จัดการที่เก่งกาจ แต่หุ่นยนต์รู้สึกว่าถูกขูดรีด ค่าจริยธรรม -50', zh: '💰 富有但不道德。你从机器人的天赋中赚了几百万。公众认为你是一个天才经理，但机器人感到被剥削。职业道德 -50。' }, stats: { competence: 50, ethics: -50, leadership: 40, innovation: 70 } },
            { id: 'D', text: { en: '🕵️ Secret Lab: "Let it shoot in secret. If anyone finds out, we are both in trouble. Let\'s make a hidden gallery."', th: '🕵️ ห้องแล็บลับ: "ให้มันถ่ายเงียบๆ ถ้าใครรู้เราซวยทั้งคู่ มาเปิดแกลเลอรี่ลับกันเถอะ"', zh: '🕵️ 秘密实验室：“让它秘密拍摄。如果被人发现，我们两个都会有麻烦。让我们建一个隐藏的画廊。”' }, consequence: { en: '✅ Cult Legend. You create a secret underground art scene. It becomes the most prestigious thing in the world because it\'s "forbidden." You are a rebel again.', th: '✅ ตำนานใต้ดิน คุณสร้างวงการศิลปะลับๆ ขึ้นมา มันกลายเป็นที่ต้องการมากที่สุดในโลกเพราะมัน "ต้องห้าม" คุณกลับมาเป็นขบถอีกครั้ง', zh: '✅ 地下传奇。你创造了一个秘密的地下艺术场景。因为它被“禁止”，它成为了世界上最负盛名的事。你又成了一个反叛者。' }, stats: { competence: 40, ethics: 40, leadership: 50, innovation: 80 } }
        ]
    },

    {
        id: 'pho_048',
        text: {
            en: '🌌 The Quantum Camera: You are offered a camera that can photograph "Possibilities." It takes a photo of what *could* have happened in a scene, not just what did. It\'s the ultimate artistic tool. Do you use it?',
            th: '🌌 กล้องควอนตัม: มีคนเสนอเนอกล้องที่ถ่ายภาพ "ความเป็นไปได้" มันสามารถถ่ายสิ่งที่ *อาจจะ* เกิดขึ้นในตอนนั้น ไม่ใช่แค่สิ่งที่เกิดขึ้นจริง มันคือสุดยอดเครื่องมือศิลปิน จะใช้ไหม?',
            zh: '🌌 量子相机：有人向你提供了一台可以拍摄“可能性”的相机。它拍下了一幕中*可能*发生的事情，而不只是已经发生的事情。它是终极的艺术工具。你会用它吗？'
        },
        options: [
            { id: 'A', text: { en: '🌀 Embrace Multiple Realities: "Yes. Truth is not singular. I want to show all the paths not taken."', th: '🌀 ยอมรับหลายความจริง: "เอาสิ ความจริงไม่ได้มีแค่หนึ่งเดียว ฉันอยากแสดงให้เห็นทุกเส้นทางที่ไม่ได้ถูกเลือก"', zh: '🌀 拥抱多重现实：“是的。真相不是单一的。我想展示所有未被选择的道路。”' }, consequence: { en: '✅ Philosophical Master. Your photos become the foundation of a new religion/philosophy. You are no longer just a photographer; you are a prophet of reality. Innovation 100.', th: '✅ ปรมาจารย์ด้านปรัชญา รูปของคุณกลายเป็นรากฐานของศาสนาหรือปรัชญาใหม่ คุณไม่ใช่แค่ช่างภาพอีกต่อไป แต่เป็นศาสดาแห่งความจริง ค่า ‘นวัตกรรม’ 100', zh: '✅ 哲学大师。你的照片成为新宗教/哲学的基石。你不再仅仅是一名摄影师；你是一名现实的先知。创新指标 100。' }, stats: { competence: 50, ethics: 40, leadership: 60, innovation: 100 } },
            { id: 'B', text: { en: '🚫 Refuse: "The camera’s job is to capture the ONE moment that happened. The choice is where the art lies. I decline."', th: '🚫 ปฏิเสธ: "หน้าที่ของกล้องคือการบันทึก \'หนึ่งเดียว\' ที่เกิดขึ้น การเลือกคือหัวใจของศิลปะ ขอปฏิเสธ"', zh: '🚫 拒绝：“相机的任务是捕捉发生的那个唯一时刻。选择正是艺术所在。我拒绝。”' }, consequence: { en: '✅ Humanist Icon. You defend the power of the moment. Your Work becomes a sanctuary of "The Real" in a world of endless possibilities. Ethics 100.', th: '✅ ไอคอนสายมนุษยนิยม คุณปกป้องพลังของปัจจุบันขณะ งานของคุณกลายเป็นที่พึ่งของ "ความจริง" ในโลกที่เต็มไปด้วยความเป็นไปได้ไม่รู้จบ ค่าจริยธรรม 100', zh: '✅ 人文主义偶像。你捍卫了瞬间的力量。在充满无尽可能性的世界里，你的作品成为了“真实”的避难所。职业道德 100。' }, stats: { competence: 60, ethics: 100, leadership: 50, innovation: 10 } },
            { id: 'C', text: { en: '🤝 Scientist Partner: "I won\'t use it for art, but I\'ll help NASA use it to find habitable planets by photographing their possibilities."', th: '🤝 ร่วมมือกับนักวิทย์: "ฉันจะไม่เอามันมาทำอาร์ต แต่จะช่วย NASA ใช้มันหาดาวที่คนอยู่ได้ โดยการถ่ายภาพความเป็นไปได้ของดาวเหล่านั้น"', zh: '🤝 科学家合作伙伴：“我不会用它进行艺术创作，但我会帮助NASA利用它拍摄宜居行星的可能性。”' }, consequence: { en: '✅ Savior of Humanity. You help find more "Earth 2.0." You are remembered as a scientist-artist who saved the species. Leadership 100.', th: '✅ ผู้ช่วยกู้มวลมนุษย์ คุณช่วยหา "โลก 2.0" จนเจอ ผู้คนจดจำคุณในฐานะศิลปินนักวิทยาศาสตร์ที่ช่วยเผ่าพันธุ์มนุษย์ไว้ได้ ค่าภาวะผู้นำ 100', zh: '✅ 人类的救星。你帮助找到了更多的“地球2.0”。你作为一名拯救了物种的科学家艺术家而被铭记。领导力 100。' }, stats: { competence: 60, ethics: 80, leadership: 100, innovation: 90 } },
            { id: 'D', text: { en: '🤑 Blackmail potential: "Use it to photograph what a target *might* do. Sell the info to insurance companies and police."', th: '🤑 แบล็คเมล: "ใช้มันถ่ายดูว่าเป้าหมาย *อาจจะ* ทำอะไร แล้วเอาข้อมูลไปขายให้บริษัทประกันหรือตำรวจ"', zh: '🤑 勒索潜力：“用它来拍摄目标*可能*做的事情。将信息卖给保险公司和警察。”' }, consequence: { en: '❌ Monster. You become the richest person in history by selling possibilities. But you live in a fortress, hated by everyone. You die lonely and fearful.', th: '❌ อมนุษย์ คุณกลายเป็นคนที่รวยที่สุดในประวัติศาสตร์จากการขายความเป็นไปได้ แต่คุณต้องอยู่ในป้อมปราการ ถูกทุกคนเกลียดชัง และตายอย่างโดดเดี่ยวด้วยความหวาดกลัว', zh: '❌ 怪物。你通过出售可能性成为了历史上最富有的人。但你住在堡垒里，被所有人憎恨。你在孤独和恐惧中死去。' }, stats: { competence: 30, ethics: -100, leadership: 0, innovation: 60 } }
        ]
    },

    {
        id: 'pho_049',
        text: {
            en: '🤝 The Galactic Treaty: First contact has been made. Alien ambassadors are arriving. You are 90 years old. They want YOU to take the first official portrait of the combined leadership. The choice of lighting will define how they look to humanity.',
            th: '🤝 สนธิสัญญากาแล็กซี: การติดต่อครั้งแรกกับมนุษย์ต่างดาวเกิดขึ้นแล้ว ทูตต่างดาวกำลังจะเดินทางมาถึง ตอนนี้คุณอายุ 90 แล้ว เขาเลือกให้ "คุณ" เป็นคนถ่ายภาพพอร์ตเทรตทางการครั้งแรกของเหล่าผู้นำ การจัดแสงของคุณจะกิยามว่าพวกเขาจะดูเป็นอย่างไรในสายตามนุษยชาติ',
            zh: '🤝 银河条约：人类已实现第一次接触。外星大使即将抵达。你90岁了。他们想要你为联合领导层拍摄第一张官方肖像。布光的选择将定义他们在人类心目中的形象。'
        },
        options: [
            { id: 'A', text: { en: '💡 Bright & Hopeful: "High key lighting, soft shadows. Make them look like gods, like saviors. A message of peace."', th: '💡 สว่างไสวและมีความหวัง: "จัดแสงแบบ High key เงาซอฟต์ๆ ทำให้เขาดูเหมือนเทพเจ้า เหมือนผู้ช่วยให้รอด เป็นแมสเสจเรื่องสันติภาพ"', zh: '💡 明亮而充满希望：“高调布光，阴影柔和。让他们看起来像神，像救世主。传递和平的信息。”' }, consequence: { en: '✅ Golden Age. Humanity embraces the aliens. A thousand years of peace follows. Your portrait is the most seen image in the galaxy.', th: '✅ ยุคทอง มนุษยชาติเปิดรับคนต่างดาว เกิดสันติภาพยาวนานนับพันปี รูปพอร์ตเทรตของคุณกลายเป็นรูปที่มีคนเห็นมากที่สุดในกาแล็กซี', zh: '✅ 黄金时代。人类拥抱外星人。随后是一千年的和平。你的肖像是银河系中曝光率最高的图像。' }, stats: { competence: 50, ethics: 80, leadership: 100, innovation: 40 } },
            { id: 'B', text: { en: '🌑 Dark & Mysterious: "Moody, contrasty. Show the truth—they are powerful, ancient, and dangerous. A message of caution."', th: '🌑 มืดมนและลึกลับ: "จัดแบบ Moody คอนทราสต์จัดๆ โชว์ความจริงว่าพวกเขาทรงพลัง เก่าแก่ และอันตราย เป็นแมสเสจเรื่องการระแวดระวัง"', zh: '🌑 黑暗而神秘：“忧郁、对比鲜明。展示真相——他们强大、古老且危险。传递警示信息。”' }, consequence: { en: '⚠️ Cold War. Humanity stays cautious. You are seen as a realist. Trade is slow, but we are safe. You are the "Protector of Truth."', th: '⚠️ สงครามเย็น มนุษยชาติยังคงระแวดระวัง คุณถูกมองว่าเป็นพวกยอมรับความจริง การค้าขายไปได้ช้าแต่เราปลอดภัย คุณคือ "ผู้พิทักษ์ความจริง"', zh: '⚠️ 冷战。人类保持谨慎。你被视为现实主义者。贸易进展缓慢，但我们很安全。你是“真相的保护者”。' }, stats: { competence: 50, ethics: 60, leadership: 70, innovation: 30 } },
            { id: 'C', text: { en: '🌈 True Colors: "Don’t use human light. Use their own bioluminescence. Show them exactly as they are."', th: '🌈 สีสันที่แท้จริง: "ไม่ต้องใช้แสงไฟแบบมนุษย์ ใช้แสงเรืองแสงจากตัวพวกเขาเอง โชว์ตัวตนที่แท้จริงของเขาออกมา"', zh: '🌈 真实色彩：“不要使用人类的光。使用他们自己的生物发光。如实展示他们。”' }, consequence: { en: '✅ Universal Respect. Both humans and aliens respect your objectivity. You are appointed as the first "Galactic Cultural Ambassador."', th: '✅ ความเคารพสากล ทั้งมนุษย์และต่างดาวต่างนับถือในความเป็นกลางของคุณ คุณได้รับแต่งตั้งเป็น "ทูตวัฒนธรรมกาแล็กซี" คนแรก', zh: '✅ 普遍尊重。人类和外星人都尊重你的客观性。你被任命为第一任“银河文化大使”。' }, stats: { competence: 60, ethics: 50, leadership: 90, innovation: 60 } },
            { id: 'D', text: { en: '🤖 AI Optimization: "Ask the AI what humanity wants to see. Generate the perfect image based on global psychological data."', th: '🤖 ปรับจูนด้วย AI: "ถาม AI สิว่ามนุษย์อยากเห็นแบบไหน แล้วสร้างรูปที่สมบูรณ์แบบที่สุดจากข้อมูลจิตวิทยาของคนทั้งโลกออกมา"', zh: '🤖 AI优化：“询问AI人类想看到什么。根据全球心理数据生成完美的图像。”' }, consequence: { en: '😐 Manipulation. It works perfectly, but it’s a lie. Years later, when the truth comes out, trust in leadership is destroyed. You are the father of the biggest lie in history.', th: '😐 การปั้นแต่ง มันได้ผลดีเยี่ยมนะแต่มันคือคำพูดโกหก หลายปีต่อมาเมื่อความจริงเปิดเผย ความเชื่อใจในผู้นำพังทลาย คุณกลายเป็นบิดาแห่งคำลวงที่ใหญ่ที่สุดในประวัติศาสตร์', zh: '😐 操纵。它运行得完美无缺，但那是个谎言。多年后，当真相大白时，人们对领导力的信任崩塌了。你是历史上最大谎言之父。' }, stats: { competence: 30, ethics: -100, leadership: 20, innovation: 70 } }
        ]
    },

    {
        id: 'pho_050',
        text: {
            en: '⏳ The Final Breath: You are 100 years old. You are in your studio for the last time. Your life has been defined by light. You have one frame left on your very first film camera. What do you photograph?',
            th: '⏳ ลมหายใจสุดท้าย: คุณอายุ 100 ปี อยู่ในสตูดิโอเป็นครั้งสุดท้าย ชีวิตคุณขับเคลื่อนด้วยแสงสว่างมาตลอด มีฟิล์มเหลือแค่เฟรมเดียวในกล้องตัวแรกที่คุณเคยมี คุณจะถ่ายรูปอะไร?',
            zh: '⏳ 最后的呼吸：你100岁了。你最后一次在你的工作室。你的生命是由光定义的。你在你第一台胶片相机上还剩最后一格底片。你会拍什么？'
        },
        options: [
            { id: 'A', text: { en: '✨ The Light Itself: "A simple photo of the sun through the window. It all started with light, and it ends with light."', th: '✨ แสงสว่างนั่นเอง: "แค่รูปพระอาทิตย์ส่องผ่านหน้าต่าง ทุกอย่างเริ่มจากแสง และก็ขอจบลงที่แสง"', zh: '✨ 光本身：“一张简单的阳光透过窗户的照片。一切始于光，也终于光。”' }, consequence: { en: '✅ Perfect Circle. You die with a smile. Your final photo becomes the logo for every photography school in the world. Transcendence 100.', th: '✅ วงกลมที่สมบูรณ์แบบ คุณจากไปด้วยรอยยิ้ม รูปสุดท้ายของคุณกลายเป็นโลโก้ของโรงเรียนสอนถ่ายภาพทั่วโลก ค่า ‘การก้าวข้ามขีดจำกัด’ 100', zh: '✅ 完美圆满。你微笑着去世。你的最后一张照片成为了世界上每所摄影学校的标志。卓越指标 100。' }, stats: { competence: 100, ethics: 100, leadership: 100, innovation: 100 } },
            { id: 'B', text: { en: '🤳 A Self-Portrait: "The eyes that saw the century. I want people to remember the witness, not just the scene."', th: '🤳 รูปพอร์ตเทรตตัวเอง: "ดวงตาที่เห็นมาทั้งศตวรรษ ฉันอยากให้คนจำคนที่เป็นพยาน ไม่ใช่แค่ฉากที่เห็น"', zh: '🤳 自拍：“见证了一个世纪的眼睛。我希望人们记住见证者，而不仅仅是场景。”' }, consequence: { en: '✅ Human Monument. You are the ultimate artist. Your self-portrait hangs in the Louvre next to the Mona Lisa. You are immortal.', th: '✅ อนุสาวรีย์แห่งมนุษย์ คุณคือศิลปินที่แท้จริง รูปตัวเองของคุณถูกแขวนในพิพิธภัณฑ์ลูฟร์ข้างๆ โมนาลิซ่า คุณคืออมตะ', zh: '✅ 人文丰碑。你是终极艺术家。你的自画像挂在卢浮宫蒙娜丽莎的旁边。你是永恒的。' }, stats: { competence: 80, ethics: 80, leadership: 80, innovation: 80 } },
            { id: 'C', text: { en: '👶 My Successor: "A photo of my great-grandchild holding their first digital camera. The cycle continues."', th: '👶 ผู้สืบทอด: "รูปเหลนของฉันกำลังถือกล้องดิจิทัลตัวแรกของเขา วัฏจักรก็ยังดำเนินต่อไป"', zh: '👶 我的继任者：“一张我的曾孙拿着他们第一台数字相机的照片。轮回继续。”' }, consequence: { en: '✅ Legacy of Hope. You don’t care about your own fame. You care about the future. You die knowing the art is in good hands.', th: '✅ ตำนานแห่งความหวัง คุณไม่สนชื่อเสียงตัวเองอีกแล้ว คุณสนแค่อนาคต คุณตายอย่างสงบเพราะรู้ว่าวิชานี้ถูกส่งต่อไปในมือที่ไว้ใจได้', zh: '✅ 希望的传承。你不在乎自己的名声。你在乎未来。你深知这项艺术后继有人，含恨而终。' }, stats: { competence: 70, ethics: 90, leadership: 100, innovation: 60 } },
            { id: 'D', text: { en: '🎞️ Leave it Blank: "The best photo is the one I never took. I open the back and expose the film. Let it be a mystery."', th: '🎞️ ทิ้งไว้ให้ว่างเปล่า: "รูปที่ดีที่สุดคือรูปที่ฉันไม่ได้ถ่าย ฉันเปิดฝาหลังให้ฟิล์มโดนแสง ให้มันเป็นปริศนาต่อไปเถอะ"', zh: '🎞️ 留白：“最好的照片是我从未拍下的那张。我打开后盖，曝光底片。让它成为一个谜。”' }, consequence: { en: '✅ Zen Master. The world is haunted by what that final frame was. You become a myth. The most discussed "non-photo" in history.', th: '✅ ปรมาจารย์เซน โลกสงสัยไปตลอดกาลว่ารูปสุดท้ายนั่นคืออะไร คุณกลายเป็นตำนาน "รูปที่ไม่ได้ถ่าย" ที่ถูกเม้าท์ถึงมากที่สุดในประวัติศาสตร์', zh: '✅ 禅宗大师。世界终将被那最后一格底片到底拍了什么而困扰。你成了一个神话。历史上被讨论最多的“非照片”。' }, stats: { competence: 50, ethics: 50, leadership: 50, innovation: 100 } }
        ]
    }
];
